(function (root) {
  'use strict';
  var FT = root.CALR_FULLTEXT = root.CALR_FULLTEXT || {};
  FT["VN-H066"] = {"id":"VN-H066","coverage":"full","language":"zh","sourceName":"越南官方发布渠道","sourceUrl":"","fetchedAt":"2026-10-04","articleCount":73,"structureMode":"ARTICLE","title":{"zh":"高等教育法","en":"Law on Higher Education","orig":null},"level":"law","status":"active","docNumber":"年份不详","issuingBody":"越南官方发布渠道","completenessNote":"文本未能可靠切分为条文（或原件为目录式排版），按整篇收录，未作改写。","country":"VN","countryName":"越南","layer":"intl","articles":[{"id":"VN-H066-A1","no":1,"noLabel":{"zh":"第1条"},"chapter":{"zh":"第一章"},"text":{"zh":"“一带一路”法律查明     第 1 卷 ·116· 越南社会主义共和国高等教育法 a 根据第 51/2001/QH10 号决议修改、 补充的 1992 年 《越南社会主义共和国宪法》 。\n国会颁布 《高等教育法》 。\n第一章  总    则\n调整范围本法规定高等学校的组织、 职责和权限， 教学活动、 科学技术活动和国际合作活动， 高等教育质量的保障和评估， 高等学校的教师、 学生、 财政和财产， 以及国家对高等教育的管理。"}},{"id":"VN-H066-A2","no":2,"noLabel":{"zh":"第2条"},"chapter":{"zh":"第一章"},"text":{"zh":"适用对象本法适用于高等专科学校、 高等本科学校、 独立学院、 地区性大学、 国家大学和具有博士生培养资格的科学研究院， 以及与高等教育活动相关的组织和个人。"}},{"id":"VN-H066-A3","no":3,"noLabel":{"zh":"第3条"},"chapter":{"zh":"第一章"},"text":{"zh":"高等教育法的适用高等学校和高等教育管理机构的组织和运行必须遵守本法、 《教育法》 和其他相关法律规定。"}},{"id":"VN-H066-A4","no":4,"noLabel":{"zh":"第4条"},"chapter":{"zh":"第一章"},"text":{"zh":"词语解释在本法中， 以下词语解释如下：\n1. 正规教育是指在高等学校进行全日制学习， 以实施某学历层次的高等教育培养计划的培养形式。\n2. 继续教育包括在职教育和远程教育， 是指根据受教育者的需要， 在高等学校或联合培养机构开设课程以实施专科和本科学历层次的培养计划的培养形式。\n3. 培养学科是指某种职业、 科学活动领域的专业知识和技能的集合。培养学科包括多个培养专业。\n4. 培养专业是培养学科深入的专业知识和技能的集合。\n* 本文译者： 龚敏， 系北京外国语大学亚非学院博士研究生。\n* ·117· 越南社会主义共和国高等教育法\n5. 连接高等教育是指学生利用现有的学习成绩继续在本学科进行更高学历层次的学习或者转向其他学科或其他高等教育学历层次的教学管理措施。\n6. 培养计划的知识和技能水平是指学生在完成培养计划后必须达到的知识和技能的最低要求。\n7. 非营利性的私立大学和外资高等学校是指积累年利润不分享， 而作为公共财产再投资于高等学校的发展， 且各股东或者捐款人不享有股息或者股息不超过政府债券利率的高等学校。\n8. 大学是指高等专科学校、 高等本科学校、 各专业领域的附属科学研究院等高等学校， 分为两种培养形式， 进行高等教育各学历层次的培养。"}},{"id":"VN-H066-A5","no":5,"noLabel":{"zh":"第5条"},"chapter":{"zh":"第一章"},"text":{"zh":"高等教育的目标\n1. 总体目标：\n（1） 培养人力资源， 提高人民素质， 培育人才； 开展科学技术研究以创造新知识、 新产品， 为经济社会发展服务， 保障国防安全， 融入国际社会；\n（2） 培养具有政治和道德品质， 具备实际工作的知识和技能， 具有与其高等教育学历层次相对应的科学技术研究和应用能力， 身体健康， 具有创新能力和职业责任感， 能适应工作环境， 具有服务人民意识的学生。\n2. 专科教育、 本科教育、 硕士生教育、 博士生教育的具体目标：\n（1） 专科教育要使学生掌握本专业的基本知识、 熟练的实践技能， 理解自然与社会的原理和规律在实际生活中的作用， 具有解决本专业常见问题的能力；\n（2） 本科教育要使学生全面掌握本专业知识， 牢固掌握自然与社会的原理和规律， 具有基本的实践技能， 具有独立和创新工作的能力， 且具有解决本专业相关问题的能力；\n（3） 硕士生教育要使学员具有科学知识基础， 具有能在某个科学或者职业领域进行有效研究的深广专业技能， 具有独立和创新工作的能力， 以及发现和解决本专业相关问题的能力；\n（4） 博士生教育要使研究生具有高水平的理论与应用能力， 具有独立和创新的研究能力， 发现新知识和新的自然与社会的原理和规律的能力， 解决新的科学技术问题的能力， 指导科学研究和专业活动的能力。"}},{"id":"VN-H066-A6","no":6,"noLabel":{"zh":"第6条"},"chapter":{"zh":"第一章"},"text":{"zh":"高等教育的学历层次和形式\n1. 高等教育的学历层次包括专科、 本科、 硕士生和博士生。\n教育与培训部部长会同其他部级机关的部长、 首长， 具体规定对某些特殊专业的大学毕业生进行深入的专业应用能力、 实践技能的培养。\n“一带一路”法律查明     第 1 卷 ·118·\n2. 高等教育分为两种形式， 即正规教育和继续教育。"}},{"id":"VN-H066-A7","no":7,"noLabel":{"zh":"第7条"},"chapter":{"zh":"第一章"},"text":{"zh":"高等学校\n1. 国民教育系统的高等学校包括：\n（1） 高等专科学校；\n（2） 高等本科学校、 独立学院；\n（3） 地区性大学、 国家大学 （以下简称 “大学” ） ；\n（4） 具有博士生培养资格的科学研究院。\n2. 越南的高等学校分为以下类型：\n（1） 公立高等学校归国家所有， 由国家投资建设基础设施；\n（2） 私立高等学校归社会组织、 社会与职业组织、 私人经济组织或个人所有， 由社会由社会组织、 社会职业组织、 私人经济组织或个人投资建设基础设施。\n3. 外资高等学校包括：\n（1） 外国人单独投资举办的高等学校；\n（2） 外国人与国内投资者共同投资举办的高等学校。"}},{"id":"VN-H066-A8","no":8,"noLabel":{"zh":"第8条"},"chapter":{"zh":"第一章"},"text":{"zh":"国家大学\n1. 国家大学是高水平的教学研究型综合性大学， 由国家优先投资发展。\n2. 国家大学在教学、 科学研究、 财政、 国际关系和组织结构上享有自主权。国家大学由教育与培训部、 其他部委及其所在的各级人民委员会按照政府的规定进行依法管理。\n国家大学直接与各政府部门、 部级机关、 政府机关、 省人民委员会或直辖市人民委员会共同解决国家大学的相关问题。如有必要， 国家大学的经理可向政府总理报告与国家大学的运行和发展有关的问题。\n3. 国家大学理事会主席、 国家大学经理及副经理由政府总理任免。\n4. 国家大学的职能、 职责和权限由政府具体规定。"}},{"id":"VN-H066-A9","no":9,"noLabel":{"zh":"第9条"},"chapter":{"zh":"第一章"},"text":{"zh":"高等学校的层次划分\n1. 对高等学校进行层次划分的目的是为了落实高等学校网络的规划工作， 以符合经济社会发展和投资发展计划的需要， 提高高等学校的教学能力和科学研究能力， 实现国家管理。\n2. 高等学校排名的目的是为了评价教学的信誉和质量， 为国家管理和国家预算的优先投资工作服务。\n3. 高等学校按如下标准划分层次和排名：\n（1） 在高等教育系统的地位和作用；\n·119· 越南社会主义共和国高等教育法\n（2） 规模、 专业和学历层次；\n（3） 教学和科学技术活动的结构；\n（4） 教学和科学研究的质量；\n（5） 高等教育质量评估结果。\n4. 高等学校有如下类型：\n（1） 研究型高等学校；\n（2） 应用型高等学校；\n（3） 实践型高等学校。\n5. 政府规定高等学校的层次划分标准， 并且政府根据国家预算优先发展高等教育和国家管理工作服务框架中的各层次和层次划分标准， 颁布高等学校的排名。\n政府总理认证大学和高等本科学校排名； 教育与培训部部长认证高等专科学校排名； 根据排名， 政府授权的有关部门决定优先投资计划， 分配任务， 决定高等学校的特殊管理机制， 以满足国家各阶段的经济社会发展和人力资源需求。\n根据排名， 教育与培训部会同高等学校所在的省人民委员会、 直辖市人民委员会 （以下简称 “省级人民委员会” ） 对私立大学的土地、 信用和干部培养提供资助。"}},{"id":"VN-H066-A10","no":10,"noLabel":{"zh":"第10条"},"chapter":{"zh":"第一章"},"text":{"zh":"高等学校的语言使用越南语是高等学校使用的正式语言。\n根据政府总理的决定， 高等学校决定教学使用的外语。"}},{"id":"VN-H066-A11","no":11,"noLabel":{"zh":"第11条"},"chapter":{"zh":"第一章"},"text":{"zh":"高等学校网络的规划\n1. 高等学校网络规划是指对高等专科学校、 高等本科学校、 独立学院和大学进行系统分布和安排， 使职业结构、 学历层次符合于全国和地方各时期的人口规模、 地理位置、 领土， 与国家经济社会发展、 国防安全战略相一致。\n2. 高等学校网络的规划原则\n（1） 符合国家、 行业、 地区、 地方的经济社会发展战略和规划； 保证职业结构、 学历层次结构和地区结构； 满足人民的学习需求。\n（2） 保证高等教育系统的多样性和统一性， 使教学与科学研究、 生产和服务相结合；\n逐步提高教学质量， 为工业化、 现代化事业和融入国际社会服务。\n（3） 符合国家投资能力和社会资源调动能力； 为人人都有机会参与高等学校建设创造条件。\n（4） 集中投资于各主要任务、 重点高等学校和重点学科、 重点经济区和贫困地区。\n3. 高等学校网络规划包括以下主要内容：\n“一带一路”法律查明     第 1 卷 ·120·\n（1） 高等教育系统结构， 专业培养规模， 学历层次， 高等学校类型；\n（2） 高等学校根据各地区、 地方的经济社会性质和特点进行分布；\n（3） 师资队伍， 教育管理人员；\n（4） 物质、 技术设施。\n4. 高等学校网络规划由政府总理批准。"}},{"id":"VN-H066-A12","no":12,"noLabel":{"zh":"第12条"},"chapter":{"zh":"第一章"},"text":{"zh":"国家对发展高等教育事业的政策\n1. 发展高等教育事业目的是为了培养高层次、 高素质的人力资源， 以满足国家经济社会发展的需求， 保障国防安全。\n2. 增大对高等教育的国家预算投入， 有重点地投资以形成一些高水平的高等学校， 定向研究基本科学、 高科技和的重点经济社会专业， 以达到地区和世界先进水平。\n3. 实现社会化高等教育； 在土地、 税收、 信贷、 干部培训方面为非营利性的私立教育机构和外资高等学校提供优惠政策； 优先批准设立投资数额大的私立高等学校， 保证其依法设立的各项条件； 禁止利用高等教育活动非法牟利。\n4. 将教学与科学技术的研究和应用相结合， 促进高等学校与科研机构和企业之间的合作。\n5. 对具有重大科学技术潜力的高等学校， 国家确定科研任务并保障其科研经费需求。\n6. 机关、 组织、 企业具有接受和促进学生和教师实践、 实习、 实施科学研究和技术转让的权利和责任， 促进提高教学质量的提高。\n7. 制定合适的吸引、 聘用和待遇政策， 以建设和提高教师队伍质量， 重点发展高等学校中具有博士学位、 教授和副教授职称的教师队伍。\n8. 实施针对社会政策享受者、 少数民族、 经济社会条件特别困难地区人民和满足经济社会发展人力资源发展需求的特定专业学习者等对象的优惠政策， 落实高等教育性别平等的政策。"}},{"id":"VN-H066-A13","no":13,"noLabel":{"zh":"第13条"},"chapter":{"zh":"第一章"},"text":{"zh":"高等学校的越南共产党组织、 社会团体和社会组织\n1. 高等学校的越南共产党组织在宪法与法律的框架下， 根据越南共产党章程的规定设立和运行。\n2. 高等学校的社会团体和社会组织按照宪法、 法律、 社会团体和社会组织条例的规定设立和运行。\n3. 高等学校有责任为按本条第 1 款 、第2 款规定设立和运行的党组织、 社会团体和社会组织创造条件。\n·121· 越南社会主义共和国高等教育法第二章  高等学校组织第一节  高等学校的组织结构"}},{"id":"VN-H066-A14","no":14,"noLabel":{"zh":"第14条"},"chapter":{"zh":"第一章"},"text":{"zh":"高等专科学校、 高等本科学校、 独立学院的组织结构\n1. 公立的高等专科学校、 高等本科学校和独立学院的组织结构：\n（1） 学校理事会；\n（2） 高等专科学校、 高等本科学校的校长、 副校长； 独立学院的经理、 副经理；\n（3） 职能部门；\n（4） 系、 教研室； 科学技术组织；\n（5） 教学、 科学技术研究的服务组织； 生产、 经商、 服务机构；\n（6） 分校 （如有） ；\n（7） 科学与培训委员会， 咨询委员会。\n2. 大学的附属高等专科学校、 附属高等本科学校的组织结构遵循大学的组织和运行制度的规定。\n3. 私立的高等专科学校、 高等本科学校具有本条第 1 款第 2 项 、第3 项 、第4 项 、第 5 项 、第6 项和第 7 项规定的组织结构， 并且设有董事会、 检查委员会。\n4. 外资高等学校自主决定其组织结构。"}},{"id":"VN-H066-A15","no":15,"noLabel":{"zh":"第15条"},"chapter":{"zh":"第一章"},"text":{"zh":"大学的组织结构大学的组织结构：\n1. 大学理事会。\n2. 经理、 副经理。\n3. 职能部门。\n4. 附属大学； 附属科学研究院。\n5. 附属高等专科学校； 科学技术研究系、 科学技术研究中心。\n6. 教学、 科学研究与应用的服务组织； 生产、 经商、 服务机构。\n7. 分校 （如有） 。\n8. 科学与培训委员会， 咨询委员会。"}},{"id":"VN-H066-A16","no":16,"noLabel":{"zh":"第16条"},"chapter":{"zh":"第一章"},"text":{"zh":"学校理事会\n1. 学校理事会设立于公立的高等专科学校、 高等本科学校和独立学院。\n2. 学校理事会是学校的管理机构和所有权代表。学校理事会由以下职责和权限：\n“一带一路”法律查明     第 1 卷 ·122·\n（1） 决定学校的发展战略、 规划和计划、 组织与运行制度；\n（2） 决定教学、 科学技术、 国际合作的方向性问题， 保障教育质量；\n（3） 决定学校的组织结构、 投资发展方向；\n（4） 决定高等学校附属机构的设立、 合并、 分立和解散；\n（5） 对学校理事会决议的执行情况和学校活动中民主机制的实施情况进行监督。\n3. 学校理事会的成员\n（1） 校长、 副校长、 党委书记、 工团主席、 胡志明共产主义青年团书记； 系代表、 高等学校的管理机关代表。\n（2） 在教育、 科学、 技术、 生产、 经商岗位工作的成员。\n4. 学校理事会主席由政府授权的有关部门首长任命。\n学校理事会主席的标准规定于本法第 20 条第 2 款。\n5. 学校理事会的任期为 5 年， 由校长的任期而定。\n学校理事会的工作遵循集体原则和多数决定原则。\n6. 学校理事会的设立程序、 成员数量和结构， 学校理事会的职责和权限， 学校理事会的主席和秘书的职责和权限， 以及学校理事会的主席及各成员的任免由学校的章程具体规定。"}},{"id":"VN-H066-A17","no":17,"noLabel":{"zh":"第17条"},"chapter":{"zh":"第一章"},"text":{"zh":"董事会\n1. 董事会设立于私立的高等专科学校、 高等本科学校。\n2. 董事会是学校所有权的唯一代表机构。董事会有以下职责和权限：\n（1） 组织执行股东大会的决议；\n（2） 决定学校的发展战略、 规划和计划、 组织与运行制度；\n（3） 决定教学、 科学技术、 国际合作的方向性问题， 保障教育质量；\n（4） 决定学校的组织、 人事、 财政、 财产和投资发展方向问题；\n（5） 对学校理事会决议的执行情况和学校活动中民主机制的实施情况进行监督。\n3. 董事会的成员：\n（1） 达到规定持股标准的组织代表和个人。\n（2） 校长； 高等学校所在的地方管理机关代表； 党组织和团体组织代表； 教师代表。\n4. 董事会主席由多数决定、 匿名投票的方式选出。\n董事会主席须有大学本科以上学历。\n5. 学校理事会的任期为 5 年。董事会的工作遵循集体原则和多数决定原则。\n6. 董事会的设立程序、 成员数量和结构， 董事会的职责和权限， 董事会的主席和秘书 ·123· 越南社会主义共和国高等教育法的标准、 职责和权限， 以及董事会、 董事会的主席及各成员是否得到认证由学校的组织和运行条例和制度规定。"}},{"id":"VN-H066-A18","no":18,"noLabel":{"zh":"第18条"},"chapter":{"zh":"第一章"},"text":{"zh":"大学理事会\n1. 大学理事会由以下职责和权限：\n（1） 批准大学的发展战略、 规划和计划。\n（2） 决定教学、 科学技术、 国际合作的方向性问题， 保障教育质量。\n（3） 决定大学的组织结构和投资发展方向。\n（4） 决定本法第15 条第 3 款 、第5 款 、第6 款和第 7 款规定的机构的设立、 解散、 合并和分立； 通过关于设立、 解散、 合并和分立本法第15 条第 4 款规定机构的提案。\n（5） 对大学理事会决议的执行情况和学校活动中民主机制的实施情况进行监督。\n2. 大学理事会的成员包括：\n（1） 经理、 副经理； 党委书记、 工团主席、 胡志明共产主义青年团书记； 附属高等专科学校、 附属高等本科学校的校长； 附属科学研究院院长。\n（2） 国家管理机关代表； 在教育、 科学、 技术、 生产、 经商岗位工作的成员。\n3. 大学理事会的任期为 5 年， 由大学经理的任期而定。大学理事会的工作遵循集体原则和多数决定原则。\n4. 大学理事会的设立程序、 成员数量和结构， 大学理事会的职责和权限， 大学理事会的主席和秘书的标准、 职责和权限， 以及大学理事会的主席及各成员的任免由大学的组织和运行制度具体规定。"}},{"id":"VN-H066-A19","no":19,"noLabel":{"zh":"第19条"},"chapter":{"zh":"第一章"},"text":{"zh":"科学与培训委员会\n1. 科学与培训委员会由高等专科学校和高等本科学校的校长、 独立学院和大学的经理决定设立， 为校长、 经理提供建设性的咨询：\n（1） 规定教学和科学技术活动， 制定教师、 研究员、 图书馆和实验室工作人员的招聘标准；\n（2） 制定学校的教师、 研究员队伍的发展计划；\n（3） 制作关于增设培养专业、 实施或取消培养计划的提案； 为科学技术发展、 科学技术活动计划制定方向， 分配实施教学、 科学技术的职责。\n2. 科学与培训委员会包括： 校长； 负责教学、 科学研究活动的副校长； 各教学、 科学研究单位的负责人； 各大领域、 专业具有代表性的权威科学家。\n“一带一路”法律查明     第 1 卷 ·124·"}},{"id":"VN-H066-A20","no":20,"noLabel":{"zh":"第20条"},"chapter":{"zh":"第一章"},"text":{"zh":"校长\n1. 高等专科学校、 高等本科学校的校长， 独立学院、 大学的经理是a 高等学校的法定代表人， 负责高等学校的管理工作。校长由政府授权的有关部门任命或者认证。\n校长的任期为 5 年。校长按任期进行任命或者再次任命， 且最多连任一次。\n2. 校长的标准：\n（1） 具有良好的政治和道德素养， 在科研、 教学领域具有威信， 具有管理能力， 并且具有在高等学校的院系或职能部门 5 年以上的管理工作经验。\n（2） 高等本科学校的校长、 独立学院和大学的经理须有博士学历； 高等专科学校的校长须有硕士及以上学历。\n（3） 身体健康。任命为公立高等学校的校长时的年龄须保证至少能够在任一个任期。\n3. 校长的职责和权限：\n（1） 根据学校理事会、 董事会、 大学理事会的决议颁行高等学校的规章制度。\n（2） 根据学校理事会、 董事会、 大学理事会的决议决定高等学校下属机构的设立、 合并、 分立和解散； 任命、 罢免高等学校下属机构的正、 副级负责人。\n（3） 组织执行学校理事会、 董事会、 大学理事会的决议。\n（4） 制定规划和发展教师、 管理人员队伍的计划。\n（5） 组织实施教学、 科学研究、 国际研究活动， 保障高等教育质量。\n（6） 遵循信息和报告制度， 按规定接受监督与检查。\n（7） 建设和实施基础民主制度； 听取高等学校中个人、 组织、 团体的意见并接受其监督。\n（8） 每年须向学校理事会、 董事会、 大学理事会报告校长及校务委员会的职责履行情况。\n（9） 法律规定的其他职责和权限。\n4. 公立高等学校的校长、 私立高等学校的董事会主席是高等学校的法定代表人， 对高等学校的全部财务管理工作承担法律责任； 实施自主权并依法承担财政公开、 透明的责任； 实施会计和审计的规定。私立高等学校的校长为委托代理人， 在委托范围内行使和履行类似法定代表人的权利和义务。"}},{"id":"VN-H066-A21","no":21,"noLabel":{"zh":"第21条"},"chapter":{"zh":"第一章"},"text":{"zh":"高等学校的分校\n1. 高等学校的分校隶属于高等学校且受其统筹管理。高等学校的分校没有独立的法 a 因本条第 1 款中， “高等专科学校、 高等本科学校的校长” 和 “独立学院、 大学的理经理” 是并列关系， 为方便下文叙述， 统称为 “校长” 。——译者注 ·125· 越南社会主义共和国高等教育法人资格， 设立于与高等学校本部不同的省市， 受其所在地省级人民委员会的管理。\n2. 高等学校的分校根据校长的调动实施任务， 向校长报告分校的运行情况， 向所在地省级人民委员会报告地方授权管理的相关活动情况。\n3. 高等学校分校的设立须符合本法"}},{"id":"VN-H066-A22","no":22,"noLabel":{"zh":"第22条"},"chapter":{"zh":"第二节"},"text":{"zh":"的各项规定， 并由教育与培训部部长决定设立或者批准设立。\n第二节  高等学校的设立、 合并、 分立和解散； 批准、 停止教学活动第 22 条  高等学校的设立或批准设立的条件\n1. 高等学校的设立或者批准设立必须满足下列所有条件：\n（1） 具有已通过的符合经济社会发展规划和高等学校网络规划的设立草案；\n（2） 具有高等学校本部所在地省级人民委员会出具的关于设立高等学校的书面同意和土地租赁证明；\n（3） 具有由政府授权的有关部门出具的关于设立高等学校的财政能力证明；\n（4） 对于外资高等学校， 还须具有政府授权的有关部门出具的投资许可证明。\n2. 自设立或者批准设立的决定生效之日起 4 年后， 如高等学校不被批准实施教学活动， 则设立或者批准设立的决定无效。"}},{"id":"VN-H066-A23","no":23,"noLabel":{"zh":"第23条"},"chapter":{"zh":"第二节"},"text":{"zh":"实施教学活动的批准条件\n1. 高等学校教学活动必须满足下列所有条件才能获得批准：\n（1） 具有设立或者批准设立高等学校的决定。\n（2） 有土地、 设施、 设备、 学生宿舍、 体育设施， 以满足教学的需求； 根据项目的承诺条款， 建造的地点需保证学生、 教师和其他员工的教学活动和安全环境。\n（3） 有培养计划、 教材和教学材料， 按规定进行学习。\n（4） 有数量充足、 结构统一且达到专业和业务标准的专职教师和管理人员队伍。\n（5） 具有规定的充足财政能力以保证高等教育机构的可持续运行和发展。\n（6） 具有高等学校的组织和运行制度。\n2. 自批准教学活动的决定生效之日起 3 年后， 如高等学校不实施教学活动， 则批准教学活动的决定无效。"}},{"id":"VN-H066-A24","no":24,"noLabel":{"zh":"第24条"},"chapter":{"zh":"第二节"},"text":{"zh":"高等学校的合并、 分立高等学校的合并、 分立须符合以下要求：\n1. 符合高等学校网络规划；\n2. 满足经济社会发展的需求；\n“一带一路”法律查明     第 1 卷 ·126·\n3. 保证教师、 职员、 其他员工和学生的权利；\n4. 有助于提高高等教育的质量和效果。"}},{"id":"VN-H066-A25","no":25,"noLabel":{"zh":"第25条"},"chapter":{"zh":"第二节"},"text":{"zh":"停止高等学校的教学活动\n1. 有下列情节之一的， 高等学校将被停止教学活动：\n（1） 为设立或批准设立高校、 批准设立教学活动， 实施有欺诈行为的；\n（2） 不符合本法第23 条第 1 款规定的条件之一的；\n（3） 教学活动的批准人未获得授权的；\n（4） 违法教育法规定被处以停止活动的行政处罚的；\n（5） 法律规定的其他情节。\n2. 停止教学活动的决定要确定停止原因、 停止期限， 并采取措施保护教师、 其他员工和学生的合法权益。停止教学活动的决定必须在大众媒体公布。\n3. 停止期满后， 如果停止原因得到克服， 则授权决定停止的人可决定高等学校继续实施教学活动。"}},{"id":"VN-H066-A26","no":26,"noLabel":{"zh":"第26条"},"chapter":{"zh":"第二节"},"text":{"zh":"高等学校的解散\n1. 有下列情节之一的， 高等学校将被解散：\n（1） 严重违反法律规定的；\n（2） 停止期满后仍不能克服造成其被停止的原因的；\n（3） 设立或批准设立高等学校的决定的活动内容和目标不再符合经济社会发展需求的；\n（4） 高等学校的设立组织、 个人提议解散的；\n（5） 自设立或者批准设立的决定生效之日起 5 年之后， 不能实现项目的承诺条款的。\n2. 解散高等学校的决定要确定解散原因， 并采取措施保护教师、 其他员工和学生的合法权益。解散高等学校的决定必须在大众媒体公布。"}},{"id":"VN-H066-A27","no":27,"noLabel":{"zh":"第27条"},"chapter":{"zh":"第三章"},"text":{"zh":"设立或者批准设立高等学校、 批准教学活动、 停止教学活动以及合并、 分立、 解散高等学校的程序和授权\n1. 高等本科学校、 独立学院、 大学和外资高等学校的设立或者批准设立、 批准其教学活动、 停止其教学活动以及合并、 分立、 解散由政府总理具体规定。\n高等专科学校的设立或者批准设立、 批准其教学活动、 停止其教学活动以及合并、 分立、 解散由教育与培训部部长具体规定。\n2. 政府总理决定设立大学、 独立学院、 公立高等本科学校、 私立高等本科学校和外资高等学校。\n·127· 越南社会主义共和国高等教育法教育与培训部部长决定设立公立高等专科学校、 私立高等专科学校。\n3. 获得授权决定设立或批准设立高等学校的人有权决定该高等学校的合并、 分立、 解散。\n4. 由教育与培训部部长决定批准和停止高等专科学校、 高等本科学校、 独立学院、 具有博士生培养资格的科学研究院和外资高等学校的教学活动。\n第三章  高等学校的职责和权限"}},{"id":"VN-H066-A28","no":28,"noLabel":{"zh":"第28条"},"chapter":{"zh":"第三章"},"text":{"zh":"高等专科学校、 高等本科学校、 独立学院的职责和权限\n1. 制定高等学校的发展战略和计划。\n2. 实施教学、 科学技术、 国际合作活动， 保证高等教育质量。\n3. 根据确立的目标制定培养计划， 确保培养计划和学历层次的连接。\n4. 设立组织机构； 招聘、 管理、 建设和培养教师、 管理人员、 职员、 其他员工队伍。\n5. 管理学生； 保证教师、 职员、 员工、 管理人员和学生的合法权利和利益； 根据社会政策对社会政策享受者、 少数民族、 经济社会条件特别困难地区人民等对象进行资助； 确保教学环境。\n6. 对教学质量进行自我评估并接受教学质量评估。\n7. 使用国家划拨或者出租的土地、 设施； 依法享受税款减免。\n8. 调动、 管理和使用资源； 建设和改善设施， 购置设备。\n9. 与国内外经济、 教育、 文化、 体育、 医疗、 科学研究等领域的组织开展合作。\n10. 遵循信息和报告制度， 按规定接受教育与培训部、 其他相关部委和所在地省级人民委员会的监督与检查。\n11. 法律规定的其他职责与权限。"}},{"id":"VN-H066-A29","no":29,"noLabel":{"zh":"第29条"},"chapter":{"zh":"第三章"},"text":{"zh":"大学的职责和权限\n1. 大学的职责和权限\n（1） 制定大学的发展战略和计划。\n（2） 管理、 运营、 组织大学的教学活动。\n（3） 调动、 管理、 使用资源， 分享大学的资源和设施。\n（4） 遵循信息和报告制度， 按规定接受教育与培训部、 政府检察人员、 其他相关部委和所在地省级人民委员会的监督与检查。\n（5） 在教学、 科学研究、 技术、 财政、 国际关系、 组织机构等方面具有高度的自主权。\n（6） 法律规定的其他职责和权限。\n“一带一路”法律查明     第 1 卷 ·128·\n2. 政府总理颁行国家大学及其附属高等学校的组织和运行制度； 教育与培训部部长颁行地区性大学及其附属高等学校的组织和运行制度。"}},{"id":"VN-H066-A30","no":30,"noLabel":{"zh":"第30条"},"chapter":{"zh":"第三章"},"text":{"zh":"具有博士生培养资格的科学研究院的职责和权限\n1. 根据博士生培养计划履行职责与权限。\n2. 须有系、 办、 处等职能单位， 对博士生进行组织和管理。"}},{"id":"VN-H066-A31","no":31,"noLabel":{"zh":"第31条"},"chapter":{"zh":"第三章"},"text":{"zh":"外资高等学校的职责和权限\n1. 制定和实施教学、 科学研究的目标、 计划和内容； 建设师资队伍， 发展物资设施设备、 教材、 教辅资料、 学习资料； 保证教学质量， 实施高等教育质量评估； 依法组织教学活动， 颁发学历证书和结业证书。\n2. 根据批准设立和批准实施教学活动的决定进行组织和运行。\n3. 公开提供教学质量保证， 公开资源和财政。\n4. 接受教育与培训部的教育管理。根据教育与培训部、 其他相关部委、 政府授权的有关部门和所在地省级人民委员会的要求就外资高等学校的运行情况做报告。\n5. 即使是提前停止或者被迫停止运行的情况下， 也须保障学生、 教师和其他员工的合法权益。\n6. 尊重越南的法律、 风俗习惯。\n7. 其合法权利和利益受越南法律和越南社会主义共和国缔结的国际条约的保护。\n8. 履行法律规定的其他职责和权限。"}},{"id":"VN-H066-A32","no":32,"noLabel":{"zh":"第32条"},"chapter":{"zh":"第四章"},"text":{"zh":"高等学校的自主权\n1. 高等学校在组织与人事、 财政与财产、 教学、 科学技术、 国际合作等方面的主要活动享有自主权， 保证高等教育质量。高等学校根据自身能力、 排名和教育质量评估结果， 享有较高的自主权。\n2. 高等学校不再具有刑事自主权的能力或者行使自主权有违法行为的， 视情节轻重， 依照法律规定处理。\n第四章  教学活动"}},{"id":"VN-H066-A33","no":33,"noLabel":{"zh":"第33条"},"chapter":{"zh":"第四章"},"text":{"zh":"培养专业的开设\n1. 高等学校开设专科、 本科、 硕士生、 博士生各学历层次的专业条件有：\n（1） 登记的培养专业需符合地方、 地区、 国家以及各个领域的经济社会发展对人力资源的需求；\n（2） 具有在数量、 质量、 水平和结构方面有保证的专职教师、 科研人员队伍；\n·129· 越南社会主义共和国高等教育法\n（3） 有确保教学需求的设施、 设备、 图书馆、 教材；\n（4） 制定培养计划， 以保证学生毕业后知识和技能水平， 满足其他学历层次和培养计划的连接教育的要求。\n2. 教育与培训部部长对开设或停止专科、 本科、 硕士生、 博士生学历层次专业的条件、 程序和手续作出决定， 并决定是否批准开设专科、 本科、 硕士生、 博士生学历层次专业或者停止其活动。\n国家大学以及达到国家级标准的高等学校可根据已批准属于本校培养领域的培养专业目录， 在符合规定的条件时可自主开设专科、 本科、 硕士生、 博士生学历层次的专业并对其负责。"}},{"id":"VN-H066-A34","no":34,"noLabel":{"zh":"第34条"},"chapter":{"zh":"第四章"},"text":{"zh":"招生指标和招生组织\n1. 招生指标\n（1） 招生指标是在经济社会的发展需求和人力资源发展规划的基础上确定的， 在教师队伍的数量和质量、 设施设备方面满足相应条件；\n（2） 高等学校自主确定招生指标， 负责公布招生指标、 教学质量和教学质量保障条件；\n（3） 高等学校违反招生指标规定的， 视情节轻重， 依照法律规定处理。\n2. 招生组织\n（1） 招生方式包括： 招生考试、 审核招生、 招生考试与审核招生相结合。\n（2） 高等学校自主决定招生方式并对招生工作负责。\n3. 教育与培训部部长对招生指标作出决定， 并颁行招生制度。"}},{"id":"VN-H066-A35","no":35,"noLabel":{"zh":"第35条"},"chapter":{"zh":"第四章"},"text":{"zh":"修业年限\n1. 实施正规教育的各高等教育学历层次的修业年限规定于 《教育法》 第38 条。\n2. 学分制教育的修业年限是在各培养计划和学历层次规定的累计学分的基础上确定的。\n高等学校的校长对各培养计划和学历层次的累计学分数量作出决定。\n3. 继续教育形式的高等学校各学历层次的修业年限比正规教育形式的修业年限至少长 1 年。"}},{"id":"VN-H066-A36","no":36,"noLabel":{"zh":"第36条"},"chapter":{"zh":"第四章"},"text":{"zh":"高等教育培养计划和教材\n1. 培养计划\n（1） 专科、 本科的培养计划包括： 培养目标、 学生毕业后的知识和技能水平； 各个学科和专业的培养内容和评估方式； 教学水平； 满足其他学历层次和培养计划的连接教育 “一带一路”法律查明     第 1 卷 ·130· 的要求。\n（2） 硕士生、 博士生的培养计划包括： 培养目标、 学员和研究生毕业后知识和技能水平； 知识水平、 硕士生和博士生学历层次的培养课程结构、 学位论文。\n（3） 高等学校可采用外国高等学校经质量评估和认证的培养计划， 以实施各高等教育学历层次的培养。\n（4） 高等学校独立负责制定、 审定、 颁行针对专科、 本科、 硕士生、 博士生的培养计划。\n（5） 外资高等学校独立负责制定和执行越南教育质量评估单位评估通过的培养计划， 保证其不对国防安全、 公共利益造成损害， 不歪曲历史， 对文化、 道德、 淳朴风俗、 越南民族大团结、 世界和平与安全造成不良影响， 且不能传播宗教。\n（6） 继续教育与正规教育两种形式的培养计划内容相同。\n2. 高等教育教材\n（1） 高等教育的教材将各学科和专业培养计划中的知识和技能要求具体化， 以实现各高等教育学历层次的目标。\n（2） 教育与培训部组织编写高等学校在政治理论、 国防安全相关学科教学使用的教材。\n（3） 高等学校的校长根据其组织设立的教材审定委员会的评议， 组织编写、 选择和批准高等教育教学使用的教材。\n（4） 高等学校在使用教材和公布科学研究项目时要遵守知识产权和著作权的相关规定。\n3. 教育与培训部部长规定各高等教育学历层次的学生毕业后需达到的最低知识水平和能力要求， 制定专科、 本科、 硕士生、 博士生等学历层次的培养计划的制定、 审定和颁行规程， 规定外资高等学校的各学历层次培养计划中必修课程， 并对高等教育教学材料和教材的编写或选择、 审定、 批准和使用作出规定。"}},{"id":"VN-H066-A37","no":37,"noLabel":{"zh":"第37条"},"chapter":{"zh":"第四章"},"text":{"zh":"教学的组织与管理\n1. 教学的组织和管理实行学年制或学分制。\n2. 高等学校自主按学年和学期组织和管理教学， 实施各学历层次与培养形式的培养计划和制度。\n3. 可实施联合培养的高等学校在教学环境、 设施、 设备、 图书馆和管理人员等方面达到要求的条件下， 只能以继续教育的形式与高等本科学校、 高等专科学校、 中等专业学校、 省级继续教育中心以及隶属于国家机关、 政治组织、 政治社会组织、 人民武装力量的学校实施专科、 本科学历层次的联合培养。\n4. 教育与培训部部长颁行培养与联合培养制度。\n·131· 越南社会主义共和国高等教育法"}},{"id":"VN-H066-A38","no":38,"noLabel":{"zh":"第38条"},"chapter":{"zh":"第五章"},"text":{"zh":"高等教育学历证书\n1. 高等教育学历证书是指颁发给从某形式的学历层次毕业的学生的高等教育学历证书， 包括专科毕业证书、 本科毕业证书、 硕士学历证书和博士学历证书。\n（1） 学生完成专科培养计划且合格的， 可参加毕业考试或者进行论文答辩， 完成毕业论文， 如达到要求或者修满规定学分， 且符合高等学校设置的标准的， 可获得高等学校校长颁发的专科毕业证书；\n（2） 学生完成本科培养计划且合格的， 可参加毕业考试或者进行论文答辩， 完成毕业论文， 如达到要求或者修满规定学分， 且符合高等学校设置的标准的， 可获得高等学校校长颁发的本科毕业证书；\n（3） 学生完成硕士生培养计划且合格的， 可进行论文答辩， 如达到要求， 可获得高等学校校长颁发的硕士学历证书；\n（4） 研究生完成博士生培养计划且合格的， 可进行论文答辩， 如达到要求， 可获得高等学校校长颁发的博士学历证书。\n2. 高等学校印制并颁发学历证书给学生， 并在本校网站上公布学生学历证书的相关信息。\n3. 教育与培训部部长制定高等教育学历证书的格式， 规定高等教育学历证书的印制、 管理、 颁发、 召回、 注销事宜， 规定越南高等学校与国外高等学校的联合培养关于颁发高等教育学历证书的职责与权限， 规定外资高等学校在越南颁发高等教育学历证书的职责， 负责与各个国家和国际组织签订学历证书相互承认协定， 并规定国外高等学校颁发的学历证书的认证程序、 手续问题。\n4. 教育与培训部部长会同其他部级机关部长、 首长就向一些特殊专业毕业的大学学生颁发实践和应用能力认证证书作出规定。\n第五章  科学技术活动"}},{"id":"VN-H066-A39","no":39,"noLabel":{"zh":"第39条"},"chapter":{"zh":"第五章"},"text":{"zh":"科学技术活动的目标\n1. 提高教师、 研究员、 管理人员、 职员的高等教育质量、 研究和应用科学技术的能力。\n2. 培养和开发学生的科学研究能力， 发现和培养人才， 满足高层次人才的需求。\n3. 为科学与教育的发展创造新的解决方案、 知识和技术， 促进经济社会发展， 保障国防安全。"}},{"id":"VN-H066-A40","no":40,"noLabel":{"zh":"第40条"},"chapter":{"zh":"第五章"},"text":{"zh":"科学技术活动的内容\n1. 进行基础科学、 社会与人文科学， 教育科学、 科学技术方面的研究， 创造新知识和 “一带一路”法律查明     第 1 卷 ·132· 新产品。\n2. 将各项研究成果、 技术转让应用于生活和生产实践。\n3. 设立实验室和研究机构， 为教学与科学研究服务， 建立技术开发基地， 将技术开发与新产品相结合。\n4. 参加募集、 咨询、 评审和履行各项关于科学技术的任务和合同， 以及既定的常规任务。"}},{"id":"VN-H066-A41","no":41,"noLabel":{"zh":"第41条"},"chapter":{"zh":"第五章"},"text":{"zh":"高等学校在科学技术活动中的职责与权限\n1. 制定和实施科学技术的发展计划和战略。\n2. 开展科学技术研究以提高教学质量。\n3. 开展科学研究和技术转让以创造新的知识、 技术和解决方案， 在符合学校的科学技术能力的基础上促进经济社会的发展。\n4. 独立负责签署科学技术合同； 开展各项科学技术任务； 登记参加科学技术任务的选择和履行。\n5. 使用资金、 财产、 知识财产和其他合法收入来开展各项科学技术、 生产、 经商活动。\n6. 设立研发机构、 科学技术服务机构和科学技术企业。\n7. 知识产权得到保护； 有权转让科学技术成果； 公布科学技术成果。\n8. 保护国家和社会的利益； 保护组织、 个人在科学技术活动中的合法权益； 保护法律规定的科学技术秘密。\n9. 法律规定的其他职责和权限。"}},{"id":"VN-H066-A42","no":42,"noLabel":{"zh":"第42条"},"chapter":{"zh":"第六章"},"text":{"zh":"国家对科学技术发展的责任\n1. 政府规定投资发展潜力， 鼓励高等学校开展科学技术活动， 优先发展在科学技术的研究和应用型人才方面具有巨大潜力的高等学校。\n2. 科学与技术部主导会同教育与培训部、 计划与投资部、 财政部制定关于高等学校科学技术的优先投资发展政策。\n3. 教育与培训部主导会同科学与技术部和其他相关部门对高等学校的科学技术活动作出规定。\n第六章  国际合作活动"}},{"id":"VN-H066-A43","no":43,"noLabel":{"zh":"第43条"},"chapter":{"zh":"第六章"},"text":{"zh":"国家合作活动的目标\n1. 提高面向现代化的高等教育质量， 获取地区和世界的先进高等教育。\n2. 为高等学校的稳定发展创造条件， 培养为国家的工业化、 现代化事业服务的高层次人才。\n·133· 越南社会主义共和国高等教育法"}},{"id":"VN-H066-A44","no":44,"noLabel":{"zh":"第44条"},"chapter":{"zh":"第六章"},"text":{"zh":"高等学校的国际合作形式\n1. 联合培养。\n2. 在越南设立外国高等学校的代表处。\n3. 联合开展科学研究和技术转让活动， 组织科学会议和研讨会。\n4. 咨询、 赞助、 投资发展设施、 设备。\n5. 培养和交换教师、 研究院、 研究人员和学生。\n6. 共享图书馆， 交换教学、 科学技术活动信息； 提供培养计划； 交换教学、 科学技术活动的印刷品、 材料和成果。\n7. 参加教育、 科学组织和地区与国际专业会议。\n8. 在国外设立越南高等学校的代表处。\n9. 法律规定的其他合作形式。"}},{"id":"VN-H066-A45","no":45,"noLabel":{"zh":"第45条"},"chapter":{"zh":"第六章"},"text":{"zh":"国内外联合培养\n1. 国内外联合培养是越南高等学校与国外教育机构制定和实施的联合培养计划， 旨在获得学历证书或证书， 但不形成新的法人。\n2. 国内外联合培养计划是外国的计划或者是由双方共同制定的计划。培养计划在越南全部在越南实施或者部分在越南实施， 部分在外国实施。\n3. 国内外联合培养的高等学校要满足教师队伍、 设施设备、 教学计划与内容、 法理资格、 由外国或教育与培训部认证的质量评估证书、 联合培养许可证等条件。\n4. 教育与培训部部长批准专科、 本科、 硕士生、 博士生学历层次的国内外联合培养计划。\n大学经理批准在大学开展的专科、 本科、 硕士生、 博士生学历层次的国内外联合培养计划。\n5. 如国内外联合培养计划被停止招生或者由于不符合本条第 3 款规定的条件被停止活动， 高等学校要保护教师、 学生和其他员工的合法权益； 返还学生的经费， 结算授课劳务费， 保障劳动合同或者集体合同中教师和其他员工的其他权利， 还清税收债务和其他债务 （如有） 。\n6. 高等学校要在本校网站和其他大众媒体上公布国内外联合培养的相关信息。"}},{"id":"VN-H066-A46","no":46,"noLabel":{"zh":"第46条"},"chapter":{"zh":"第六章"},"text":{"zh":"代表处\n1. 外国高等学校的代表处代表外国高等学校。\n2. 代表处有下列职责与权限：\n（1） 通过促进制定高等教育的合作计划和项目， 以推动与越南高等学校的合作；\n“一带一路”法律查明     第 1 卷 ·134·\n（2） 组织高等教育的信息交流、 咨询、 研讨会、 展览等活动， 推广外国的高等学校；\n（3） 监督、 促进与越南高等学校签署的各项高等教育合作协议；\n（4） 不能在越南实施直接营利的高等教育活动， 且不能在越南设立外国高等学校代表处的直属机构。\n3. 在具有下列所有条件的情况下， 外国高等学校可获准在越南设立代表处：\n（1） 具有法人资格；\n（2） 在所在国高等教育教学活动的运行时间在 5 年以上；\n（3） 具有明确的制度、 宗旨和目的；\n（4） 具有符合越南法律规定的在越南设立代表处的组织和运行制度。\n4. 由教育与培训部部长颁发外国高等学校设立代表处许可证。\n5. 有下列情况之一的， 外国高等学校的代表处将被终止活动：\n（1） 许可证过期的；\n（2） 外国高等学校设立的代表处的提议终止活动的；\n（3） 自许可证首次颁发之日起 6 个月内或者办理许可证延期之日起 3 个月以内不实施教学活动的， 许可证将被召回；\n（4） 被发现在申请设立代表处许可证的过程中提供虚假资料的；\n（5） 开展与许可证内容不相符的活动；\n（6） 违法越南法律的其他规定。"}},{"id":"VN-H066-A47","no":47,"noLabel":{"zh":"第47条"},"chapter":{"zh":"第六章"},"text":{"zh":"高等学校在国际合作活动中的职责和权限\n1. 实施本法第 44 条规定的国际合作形式。\n2. 遵守越南法律和越南社会主义共和国缔结的国际条约。\n3. 合法权利和利益受越南法律和越南社会主义共和国缔结的国际条约的保护。"}},{"id":"VN-H066-A48","no":48,"noLabel":{"zh":"第48条"},"chapter":{"zh":"第七章"},"text":{"zh":"国家对国际合作的责任\n1. 政府采取适当的措施落实双方或多方协议， 促进高等学校的国际合作， 以满足国家对经济社会发展的需求， 符合高等教育的发展战略和规划； 加强对国内外联合办学和联合培养的管理。\n2. 政府总理制定投资政策和待遇制度， 以吸引在国外的越南科学家和越南人参与赞助、 教学、 科学研究和技术转让； 政府总理还对本法第44 条 、第45 条和第 46 条规定的关于国际合作的条件、 程序作出具体规定。\n3. 教育与培训部部长规定鼓励高等学校投资和拓展与外国在教学、 教学、 科学研究和技术转让等方面的交流与合作； 对外国高等学校在越南的运行以及对越南高等学校与 ·135· 越南社会主义共和国高等教育法外国高等学校的联合培养的管理工作作出规定。\n第七章  高等教育质量的保障和评估"}},{"id":"VN-H066-A49","no":49,"noLabel":{"zh":"第49条"},"chapter":{"zh":"第七章"},"text":{"zh":"高等教育质量评估的目标、 原则和对象\n1. 高等教育质量评估的目标\n（1） 保障和提高高等教育质量；\n（2） 确定高等学校和培养方案在各阶段高等教育目标的实施情况；\n（3） 作为高等学校向政府授权的有关部门和社会说明其实际教学质量的依据；\n（4） 为学生选择高等学校和培养计划， 以及招聘者的人事招聘提供基础。\n2. 高等教育质量评估的原则\n（1） 独立、 客观、 合法；\n（2） 真实、 公开、 清楚；\n（3） 公平、 强制、 定期。\n3. 高等教育质量评估的对象：\n（1） 高等学校；\n（2） 各高等教育学历层次的培养计划。"}},{"id":"VN-H066-A50","no":50,"noLabel":{"zh":"第50条"},"chapter":{"zh":"第七章"},"text":{"zh":"高等学校对保障高等教育质量的责任\n1. 设立保障高等教育质量的专门机构。\n2. 制定和实施保证高等教育质量的计划。\n3. 自我评价、 改进和提高高等教育质量； 定期登记对培养计划和高等学校进行评估。\n4. 保持和发展保障教学质量的条件， 包括：\n（1） 教师、 管理人员队伍和其他员工；\n（2） 培养计划、 教材、 教学材料；\n（3） 教师、 办公室、 图书馆、 信息技术系统、 实验室、 实习中心、 宿舍和其他服务设施；\n（4） 财政资源。\n5. 在教育与培训部、 高等学校和大众媒体网站上公布关于保障高等教育质量的各项条件、 教学和科学研究成果、 高等教育质量的评估结果。"}},{"id":"VN-H066-A51","no":51,"noLabel":{"zh":"第51条"},"chapter":{"zh":"第七章"},"text":{"zh":"高等学校对高等教育质量评估的职责和权限\n1. 应国家教育管理机关的要求进行教育质量评估。\n2. 实施对高等教育质量评估结果的信息和报告制度。\n3. 有权在教育与培训部认证的教育质量评估机构中选择其中之一， 对高等学校质量 “一带一路”法律查明     第 1 卷 ·136· 和培养计划质量进行评估。\n4. 对高等教育质量评估的组织、 个人的决定、 结论和违法行为， 高等学校可向政府授权的有关部门提起申诉和控告。"}},{"id":"VN-H066-A52","no":52,"noLabel":{"zh":"第52条"},"chapter":{"zh":"第七章"},"text":{"zh":"教育质量评估机构\n1. 教育质量评估机构对高等学校和培养计划是否达到高等教育质量的标准进行评价和认证。\n教育质量评估机构具有法人资格， 对高等教育质量评估活动承担法律责任。\n2. 在提出符合教育质量评估机构网络规划的设立提案时， 可设立新的教育质量评估机构； 在具有设施、 设备、 财政和达到从事高等教育质量评估活动要求的评估人员队伍时， 教育质量评估机构可开展教育质量评估活动。\n3. 教育与培训部部长公布高等学校的国家标准， 规定高等教育质量的评价标准、 培养计划的最低实施要求、 高等教育质量评估的规程和周期， 规定活动原则和从事教育质量评估的组织、 个人的条件、 标准， 规定教育质量评估证明的发放与召回， 决定设立或批准设立高等教育质量评估组织， 批准教育质量评估活动的开展。"}},{"id":"VN-H066-A53","no":53,"noLabel":{"zh":"第53条"},"chapter":{"zh":"第八章"},"text":{"zh":"高等教育质量评估结果的使用高等教育质量的评估结果可作为确定高等教育质量、 高等学校的地位和信誉的依据， 作为高等学校自主负责、 国家对其投资支持和任务分配的依据， 以及作为国家和社会监督高等学校的依据。\n第八章  教师"}},{"id":"VN-H066-A54","no":54,"noLabel":{"zh":"第54条"},"chapter":{"zh":"第八章"},"text":{"zh":"教师\n1. 高等学校教师有清楚的背景、 良好的道德品质， 身体健康需达到职业要求， 且需达到 《教育法》 第77 条第 1 款第 6 项规定的专业和业务水平。\n2. 高等学校教师的职务设助教、 讲师、 副教授、 教授。\n3. 除了教育与培训部部长指定的一些特殊专业外， 高等学校教师要具备硕士及以上学历。\n高等学校校长优先聘任具备硕士及以上学历的人为高等学校教师。\n4. 教育与培训部部长颁行教学业务培养计划， 并规定高等学校教师的培养和聘任。"}},{"id":"VN-H066-A55","no":55,"noLabel":{"zh":"第55条"},"chapter":{"zh":"第八章"},"text":{"zh":"教师的职责和权利\n1. 根据培养计划、 目标进行教学， 充分有效地实施培养计划。\n2. 研究、 发展应用科学和技术转让， 保障教学质量。\n·137· 越南社会主义共和国高等教育法\n3. 定期学习、 培养提高政治理论、 专业、 业务水平， 改进教学方法。\n4. 保持教师的品质、 信誉和名声。\n5. 尊重学生的人格， 公平对待学生， 保护学生的正当权利和利益。\n6. 参与高等学校的管理和监督， 参加党的活动、 集体活动和其他活动。\n7. 依法与其他高等学校、 科学研究机构签署客座教师聘任协议和科学研究合同。\n8. 有权被任命为高等学校的教师， 被授予 “人民教师” “优秀教师” 称号， 依法获得表彰。\n9. 法律规定的其他职责和权利。"}},{"id":"VN-H066-A56","no":56,"noLabel":{"zh":"第56条"},"chapter":{"zh":"第八章"},"text":{"zh":"对教师的政策\n1. 高等学校教师被派遣学习以提高专业和业务水平； 享受优惠的薪资、 岗位津贴、 资历工资和政府规定的其他补助。\n2. 经济社会条件特别困难地区的高等学校教师可享受住宿优惠、 津贴制度和政府规定的其他优惠政策。\n3. 国家有调派高等学校教师到经济社会条件特别困难地区的高等学校任教的政策， 鼓励高等学校教师到经济社会条件特别困难地区的高等学校任教， 并为教师在该地区安心任教创造条件。\n4. 具有博士学位或具有教授、 副教授职称的高等学校教师在达到退休年龄后， 如身体状况允许、 自愿延长工作期限且高等学校有需求， 可延长工作年限。\n5. 高等学校的政策由政府总理具体规定。"}},{"id":"VN-H066-A57","no":57,"noLabel":{"zh":"第57条"},"chapter":{"zh":"第八章"},"text":{"zh":"客座教师和报告员\n1. 关于高等学校的客座教师的条款规定于教育法第 74 条。\n根据客座教师与高等学校校长之间签订的聘用合同， 客座教师享有和履行该合同规定的权利和义务。\n2. 高等学校有权邀请国内外专家、 科学家、 企业家、 艺术家作为客座教授和报告员。\n3. 客座教师和报告员由教育与培训部部长作出具体规定。"}},{"id":"VN-H066-A58","no":58,"noLabel":{"zh":"第58条"},"chapter":{"zh":"第八章"},"text":{"zh":"教师被禁止的行为\n1. 侵犯学生和他人的名誉、 人格和身体权。\n2. 在教学、 科学研究活动中实施欺诈行为。\n3. 利用教师名义和教学活动实施违法行为。\n“一带一路”法律查明     第 1 卷 ·138· 第九章  学生"}},{"id":"VN-H066-A59","no":59,"noLabel":{"zh":"第59条"},"chapter":{"zh":"第八章"},"text":{"zh":"学生学生是指正在高等学校学习和开展科学研究的人， 包括专科、 本科培养计划的大学生， 硕士生培养计划的学员， 博士生培养计划的研究生。"}},{"id":"VN-H066-A60","no":60,"noLabel":{"zh":"第60条"},"chapter":{"zh":"第八章"},"text":{"zh":"学生的责任和权利\n1. 按规定进行学习、 科学研究、 训练。\n2. 尊重高等学校教师、 管理人员、 职员和其他员工。在学习和训练过程中团结互助。\n3. 参与劳动、 社会活动和环境保护活动， 保护安全秩序， 预防和打击不当行为， 预防学习和考试中的作弊行为， 预防和打击犯罪和社会丑恶现象。\n4. 无论性别、 民族、 宗教信仰、 出身， 学生都会得到尊重和平等对待， 获取学习和训练的充足信息。\n5. 享受参与科学技术活动、 文化体育活动和学习所需的便利条件。\n6. 提出意见并参与教育活动和教育质量保障条件的管理和监督。\n7. 学生享受优先政策和社会优惠政策。\n8. 法律规定的其他责任和权利。"}},{"id":"VN-H066-A61","no":61,"noLabel":{"zh":"第61条"},"chapter":{"zh":"第八章"},"text":{"zh":"学生被禁止的行为\n1. 侵犯教师、 教育管理人员、 其他员工、 学生和其他人的人格、 名誉和身体权。\n2. 在学习、 检查、 考试和招生过程中实施欺诈行为。\n3. 在高等学校或者公共场所参与社会丑恶活动和其他违法行为， 对安全秩序造成混乱。\n4. 组织或者参加违法行为。"}},{"id":"VN-H066-A62","no":62,"noLabel":{"zh":"第62条"},"chapter":{"zh":"第八章"},"text":{"zh":"对学生的政策\n1. 根据 《教育法》 第89 条 、第90 条 、第91 条和第 92 条， 大学生享受奖学金与社会资助、 保送制度、 教学信用、 减免公共服务费的政策。\n2. 为符合社会经济、 国防安全发展需求的特殊专业学生免除学费， 优先考虑奖学金和社会资助。\n3. 政府具体制定学生享受的优先政策和社会优惠政策。"}},{"id":"VN-H066-A63","no":63,"noLabel":{"zh":"第63条"},"chapter":{"zh":"第十章"},"text":{"zh":"国家调动的义务工作期限\n1. 大学生如享有国家资助或者越南国家与外国签署协议资助的奖学金和培养费用， 毕业后须服从国家的工作调动且工作期限至少为享受奖学金和培养费用时间的两倍， 如 ·139· 越南社会主义共和国高等教育法果不接受调动则须返还奖学金和培养费用。\n2. 在学生正式毕业后的 12 个月之内， 政府授权的有关部门负责为毕业生分配工作。\n超过上述期限后， 如学生没有收到工作分配， 则不需返还学费和培养费用。\n3. 返还学费和培养费用由政府具体规定。\n第十章  高等学校的财政、 财产"}},{"id":"VN-H066-A64","no":64,"noLabel":{"zh":"第64条"},"chapter":{"zh":"第十章"},"text":{"zh":"高等学校的财政来源高等学校的财政来源包括：\n（1） 国家预算 （如有） ；\n（2） 学费和报名费；\n（3） 联合培养、 科学技术、 生产、 经商和服务活动的收费；\n（4） 来自国内外的个人、 组织的赞助、 援助、 礼品和礼物；\n（5） 来自国内外的个人、 组织的投资；\n（6） 法律规定的其他合法收入来源。"}},{"id":"VN-H066-A65","no":65,"noLabel":{"zh":"第65条"},"chapter":{"zh":"第十章"},"text":{"zh":"学费、 报名费\n1. 学费、 报名费是学生必须向高等学校缴纳的费用， 用于弥补教学支出费用。\n2. 政府规定公立高等学校收取学费、 报名费金额的内容和方法， 规定学费和报名费的收费标准。\n3. 公立高等学校有权在政府规定的学费和报名费框架内， 自主制定和决定学费、 报名费的收费金额。\n4. 私立高等学校、 外资高等学校有权依法自主制定和决定学费、 报名费的收费金额。\n5. 学费、 报名费的收费金额应当和招生通报同时公布。\n6. 实施高质量培养计划的高等学校可收取与教学质量相当的学费。\n教育与培训部部长规定高质量培养计划的确定标准， 负责管理、 监督学费金额是否与教学质量相一致。"}},{"id":"VN-H066-A66","no":66,"noLabel":{"zh":"第66条"},"chapter":{"zh":"第十章"},"text":{"zh":"高等学校的财政管理\n1. 高等学校依法实施财政、 会计、 审计、 税务和财政公开制度。\n2. 使用国家预算的高等学校由国家分配的任务， 以按照国家预算法的规定负责管理和使用国家预算。\n3. 私立高等学校在教学、 科学研究活动中收入与支出的财政差额作如下使用：\n（1） 至少留出25% 用于投资发展高等学校和教育活动， 修建设施， 购置设备， 培训和 “一带一路”法律查明     第 1 卷 ·140· 培养为学生的学习和生活服务的教师、 教育管理人员和其他员工， 或者用于慈善， 履行社会责任。该部分免税。\n（2） 如把剩余部分分发给投资者或者高等学校的员工须根据税法的规定纳税。\n4. 私立高等学校在运行过程中积累的财产和其获得的赞助、 资助、 赠与的财产是不可分配的公共财产， 根据保护和发展的原则进行管理。\n5. 私立高等学校资金的撤回和转让根据政府总理的决定实施， 保证高等学校的稳定和发展。\n6. 政府规定对高等学校的国家预算的分配指标和方法， 并对外资高等学校开展教育活动的财政作出规定。\n7. 教育与培训部、 各政府部门、 部级机关、 省级人民委员会对高等学校财政的管理和使用情况进行检查。"}},{"id":"VN-H066-A67","no":67,"noLabel":{"zh":"第67条"},"chapter":{"zh":"第十一章"},"text":{"zh":"管理和使用高等学校的财产\n1. 根据关于管理和使用国有财产的法律规定， 高等学校管理和使用来源于国家预算的财产； 自主负责管理和使用除国家预算以外的其他来源的财产。\n2. 国家交由私立高等学校管理的财产和土地， 以及高等学校获得的赞助、 资助和赠与的财产， 必须妥善使用， 不能改变其使用目的， 且不能以任何形式转变为私人所有。\n3. 外资高等学校的财产受越南法律和越南社会主义共和国缔结的国际条约的保护。\n4. 教育与培训部、 各政府部门、 部级机关、 省级人民委员会根据政府规定， 对高等学校的国有财产管理和使用情况进行检查。\n第十一章  国家对高等教育的管理"}},{"id":"VN-H066-A68","no":68,"noLabel":{"zh":"第68条"},"chapter":{"zh":"第十一章"},"text":{"zh":"国家对高等教育的管理内容\n1. 制定和指导实施发展高等教育事业的战略、 规划、 计划和政策。\n2. 颁行和组织实施高等教育的规范性法律文件。\n3. 规定培养计划的内容与结构、 学生毕业的最低能力水平和教师标准； 规定高等学校设施设备的标准； 规定教材、 教学材料的编撰、 出版、 印刷和发行； 制定关于考试、 颁发学历证书和结业证书的制度。\n4. 对高等教育的质量保障、 高等教育质量的评价标准、 高等学校的国家标准、 各高等教育学历层次的培养计划标准、 完成培养计划的最低要求、 高等教育评估的规程和周期、 高等教育质量评估进行国家管理。\n5. 对高等教育的组织和运行进行统计并提供信息。\n·141· 越南社会主义共和国高等教育法\n6. 组织高等教育管理机制。\n7. 组织和指导高等学校教师及教育管理人员的培训、 培养、 管理工作。\n8. 调动、 管理、 使用发展高等教育的资源。\n9. 组织、 管理高等学校的研究、 科学技术应用、 生产、 经商活动。\n10. 组织、 管理关于高等教育的国际合作活动。\n11. 对为高等教育事业有着重大贡献的人颁发荣誉称号作出规定。\n12. 检查执法情况， 解决申诉和控告， 严肃处理高等教育的违法行为。"}},{"id":"VN-H066-A69","no":69,"noLabel":{"zh":"第69条"},"chapter":{"zh":"第十一章"},"text":{"zh":"高等教育的国家管理机关\n1. 政府统一管理高等教育事业。\n2. 教育与培训部管理高等教育事业， 并对政府负责。\n3. 各政府部门、 部级机关会同教育与培训部部长根据职权实行对高等教育的国家管理。\n4. 省级人民委员会在职责与权限范围内， 按照政府的分级授权对高等教育进行管理；\n检查地方高等学校教育活动遵守法律的情况； 实现高等教育社会化； 扩大规模， 提高地方高等教育质量和效果。"}},{"id":"VN-H066-A70","no":70,"noLabel":{"zh":"第70条"},"chapter":{"zh":"第十一章"},"text":{"zh":"检查\n1. 对高等教育活动的检查， 包括：\n（1） 检查对高等教育对法律和政策的实施情况；\n（2） 根据职权发现、 阻止和严肃处理高等教育活动的违法行为或建议政府授权的有关部门处理；\n（3） 对政府授权的有关部门解决有关高等教育的申诉和控告进行查实和建议。\n2. 教育与培训部的检察员对高等教育进行行政检查和专业检查。\n3. 教育与培训部部长指示、 引导和组织高等教育的检查工作。各政府部门、 部级机关、 省级人民委员会会同教育与培训部根据政府的分工和分级授权， 对高等教育进行检查。\n4. 高等学校依法进行自查。高等学校的校长为高等学校的检查活动负责。"}},{"id":"VN-H066-A71","no":71,"noLabel":{"zh":"第71条"},"chapter":{"zh":"第十二章"},"text":{"zh":"违法处理任何组织和个人有以下情节之一的， 依据违法程度、 性质处以纪律处罚、 行政处罚；\n对个人还可追究其刑事责任； 如造成严重损失必须依法赔偿 :\n1. 违法设立高等学校或者高等教育活动组织的。\n2. 违反高等学校的组织和运行制度规定的。\n“一带一路”法律查明     第 1 卷 ·142·\n3. 违法出版、 印刷和发行材料的。\n4. 制作假档案， 违反招生、 考试、 学历证书和结业证书发放制度的。\n5. 侵犯教师和教育管理人员的人格、 身体权的； 虐待学生。\n6. 违反关于高等教育质量保障和评估的规定的。\n7. 对高等学校的安全、 秩序造成混乱的。\n8. 造成资金流失， 利用高等教育活动非法收费或者牟取私利的。\n9. 对高等学校的设施造成损害的。\n10. 违反高等教育法的其他违法行为。\n第十二章  施行条款"}},{"id":"VN-H066-A72","no":72,"noLabel":{"zh":"第72条"},"chapter":{"zh":"第十二章"},"text":{"zh":"施行效力本法自 2013 年 1 月 1 日起生效。"}},{"id":"VN-H066-A73","no":73,"noLabel":{"zh":"第73条"},"chapter":{"zh":"第十二章"},"text":{"zh":"细节规定和施行指导政府、 政府授权的有关部门对本法各项条款作出细节规定和施行指导。"}}],"pack":"vn-p03","rebuiltFrom":"原为单条全文，2026-10-24 按条号标记重新切分（拼接无损校验通过）"};
  FT["VN-H067"] = {"id":"VN-H067","coverage":"full","language":"zh","sourceName":"越南官方发布渠道","sourceUrl":"","fetchedAt":"2026-10-04","articleCount":68,"structureMode":"ARTICLE","title":{"zh":"信仰、宗教法","en":"Law on Belief and Religion","orig":null},"level":"law","status":"active","docNumber":"年份不详","issuingBody":"越南官方发布渠道","completenessNote":"文本未能可靠切分为条文（或原件为目录式排版），按整篇收录，未作改写。","country":"VN","countryName":"越南","layer":"intl","articles":[{"id":"VN-H067-A1","no":1,"noLabel":{"zh":"第1条"},"chapter":{"zh":"第一章"},"text":{"zh":"·143· 越南社会主义共和国信仰、宗教法越南社会主义共和国信仰、 宗教法 a 根据 《越南社会主义共和国宪法》 ， 国会颁布 《信仰、 宗教法》 。\n第一章  总则\n调整范围与适用对象\n1. 本法规定信仰自由、 宗教自由、 信仰活动、 宗教活动、 宗教组织以及与信仰活动、 宗教活动相关的机关、 组织和个人的权利和义务。\n2. 本法适用于保障和实现信仰自由和宗教自由的机关、 组织和个人。"}},{"id":"VN-H067-A2","no":2,"noLabel":{"zh":"第2条"},"chapter":{"zh":"第一章"},"text":{"zh":"词语解释本法中， 以下词语解释如下：\n1. 信仰是指人们通过举行与传统风俗习惯密切相关的仪式体现出的信念， 为个人和社会带来精神上的安定。\n2. 信仰活动是指祭拜祖先与神灵、 怀念和尊崇对国家和社会有功人士的活动以及关于历史、 文化和社会公德的具有代表性的民间仪式。\n3. 信仰节日是指按照传统仪式举行的集体信仰活动， 旨在满足社会的精神需要。\n4. 信仰活动场所是指用于开展信仰活动的寺院、 庙宇、 家族祠堂及其他类似场所。\n5. 宗教是人们对崇拜对象、 教义、 教法、 仪式和组织等活动和观念体系的信念。\n6. 信徒是信仰、 跟随某个宗教并得到该宗教组织承认的人。\n7. 修行者是指出家的信徒， 常将教义、 教法和宗教组织的规定作为个人生活方式的人。\n8. 职敕是指由宗教组织册封或者推选出来在宗教组织里任职的人。\n9. 执事是指宗教组织、 直属宗教组织、 持有宗教活动登记证书的组织任命、 选举或者推选的在宗教组织里任职的人。\n10. 宗教实践是宗教信念的表达， 是对教义、 教法和宗教仪式的践行活动。\n* 本文译者： 龚敏， 系北京外国语大学亚非学院博士研究生。\n* “一带一路”法律查明     第 1 卷 ·144·\n11. 宗教活动是指传播宗教、 宗教实践和管理宗教组织等活动。\n12. 宗教组织是指以特定组织结构将某个宗教的信徒、 职敕、 执事、 修行者组织起来并经过国家认证的宗教活动机构。\n13. 直属宗教组织是隶属于宗教组织的组织， 根据宗教组织的宪章、 条例、 规定成立。\n14. 宗教活动场所包括寺庙、 教堂、 祈祷室、 圣室、 圣堂、 宗教组织事务所及其他合法机构。\n15. 合法地点是指组织或个人根据法律规定拥有合法使用权的土地、 房屋和工程设施。\n16. 代表人是指代表某个宗教组织并对本组织开展的信仰活动、 集体宗教实践、 小组或组织的宗教活动承担法律责任的人。"}},{"id":"VN-H067-A3","no":3,"noLabel":{"zh":"第3条"},"chapter":{"zh":"第一章"},"text":{"zh":"国家对保障信仰自由和宗教自由的责任\n1. 国家尊重和保护任何个人的信仰自由和宗教自由， 保障各宗教在法律上的平等。\n2. 国家尊重和保护关于信仰、 宗教、 祭祀祖先的传统、 尊崇对国家和社会的有功人士等活动的文化和美德， 满足人民的精神需求。\n3. 国家保护信仰活动场所、 宗教活动场所及其所属合法财产。"}},{"id":"VN-H067-A4","no":4,"noLabel":{"zh":"第4条"},"chapter":{"zh":"第一章"},"text":{"zh":"越南祖国阵线的责任\n1. 团结有信仰、 信教的同胞和无信仰、 不信教的同胞， 建设全民族大团结， 建设和保卫祖国。\n2. 及时向主管国家机关反映人民对信仰和宗教相关问题的意见、 愿望和建议。\n3. 参与制定关于信仰和宗教的规范法律文本， 并根据法律规定向社会论证与信仰活动宗教相关的规范法律文件以及国家经济社会发展的规划、 计划、 项目和草案。\n4. 参与宣传和动员职敕、 执事、 修行者、 信徒、 有信仰的人、 信教的人、 宗教组织和人民遵守 《信仰、 宗教法》 。\n5. 监督机关、 组织、 民选代表和干部、 公职人员对信仰和宗教相关政策和法律的践行情况。"}},{"id":"VN-H067-A5","no":5,"noLabel":{"zh":"第5条"},"chapter":{"zh":"第二章"},"text":{"zh":"严格禁止的行为\n1. 以信仰、 宗教为由区别对待或歧视。\n2. 强迫、 收买或者妨碍他人跟随或不跟随信仰、 宗教。\n3. 亵渎信仰、 宗教。\n4. 信仰活动、 宗教活动：\n（1） 危害国防安全， 侵犯国家主权， 破坏社会安全与秩序， 污染环境；\n·145· 越南社会主义共和国信仰、宗教法\n（2） 违反社会道德， 侵犯他人的身体权、 健康权、 生命权和财产权， 侵犯他人名誉权和人格尊严；\n（3） 妨碍公民行使权利和履行义务；\n（4） 破坏民族团结， 制造宗教分裂， 在有信仰、 信教的人与无信仰、 不信教的人之间， 以及不同信仰、 宗教的人之间制造分裂；\n（5） 利用信仰活动、 宗教活动牟利。\n第二章  信仰、 宗教自由权"}},{"id":"VN-H067-A6","no":6,"noLabel":{"zh":"第6条"},"chapter":{"zh":"第二章"},"text":{"zh":"个人的信仰、 宗教自由权\n1. 任何个人都有信仰、 宗教自由权， 有权选择信仰或者不信仰宗教。\n2. 任何个人都有权表达对信仰、 宗教的信念， 践行信仰、 宗教仪式， 参加节日， 学习和遵循教义、 宗教法。\n3. 任何个人有权进入宗教活动场所修行， 有权在宗教培训场所、 宗教组织的培训班学习。未成年人进入宗教活动场所修行， 在宗教活动场所学习须获得父母或者监护人的同意。\n4. 职敕、 执事、 修行者有权在宗教活动场所或者其他合法地点举行宗教仪式， 开展讲道、 传教活动。\n5. 被先行羁押的根据先行拘留的相关法律规定， 正在服刑的罪犯以及正接受强制性教养措施、 强制隔离戒毒治疗的人员有权使用宗教书籍， 表达对信仰、 宗教的信念。\n6. 政府对本条第 5 款作出具体规定。"}},{"id":"VN-H067-A7","no":7,"noLabel":{"zh":"第7条"},"chapter":{"zh":"第二章"},"text":{"zh":"宗教组织、 直属宗教组织的权利\n1. 根据宗教组织的宪章、 条例或规定同等内容的规范文本 （以下统称 “宪章” ） 开展宗教活动。\n2. 组织宗教实践活动。\n3. 出版宗教书籍和其他宗教出版物。\n4. 生产、 出口、 进口宗教文化产品、 宗教用品。\n5. 修缮、 升级、 新建宗教活动场所。\n6. 接收国内外组织和个人自愿赠与的合法财产。\n7. 本法和其他相关法律规定的其他权利。"}},{"id":"VN-H067-A8","no":8,"noLabel":{"zh":"第8条"},"chapter":{"zh":"第二章"},"text":{"zh":"在越南合法居住的外国人的信仰和宗教自由权\n1. 国家尊重和保护在越南合法居住的外国人的信仰和宗教自由权。\n“一带一路”法律查明     第 1 卷 ·146·\n2. 在越南合法居住的外国人有权：\n（1） 宗教实践， 参与信仰活动和宗教活动。\n（2） 在合法地点开展集体宗教实践活动。\n（3） 邀请越南籍的职敕、 执事、 修行者举行宗教仪式， 开展讲道活动； 邀请外国籍的职敕、 修行者开展讲道活动。\n（4） 进入宗教活动场所修行， 在宗教培训场所和越南宗教组织的宗教培训班学习。\n（5） 携带符合越南法律规定的宗教实践所需的宗教出版物、 宗教用品。\n3. 在越南合法居住的外国籍职敕、 修行者允许在越南的宗教活动场所或者其他合法地点开展讲道活动。"}},{"id":"VN-H067-A9","no":9,"noLabel":{"zh":"第9条"},"chapter":{"zh":"第三章"},"text":{"zh":"组织、 个人行使信仰和宗教自由权的义务\n1. 参与信仰活动和宗教活动的组织、 个人须遵守宪法、 本法和其他相关法律规定。\n2. 信仰活动场所的职敕、 执事、 修行者、 代表人、 管理委员会有责任引导信徒、 信仰活动和宗教活动参与者遵守法律关于信仰活动、 宗教活动的相关规定。\n第三章  信仰活动"}},{"id":"VN-H067-A10","no":10,"noLabel":{"zh":"第10条"},"chapter":{"zh":"第三章"},"text":{"zh":"信仰活动的组织原则\n1. 信仰活动、 信仰节日必须坚持和弘扬民族的优秀传统文化。\n2. 举办信仰活动、 信仰节日必须保证社会的安全与秩序， 倡导节俭， 保护环境。"}},{"id":"VN-H067-A11","no":11,"noLabel":{"zh":"第11条"},"chapter":{"zh":"第三章"},"text":{"zh":"信仰活动场所的代表人、 管理委员会\n1. 信仰活动场所须有代表人或管理委员会为在信仰活动场所举办的活动承担法律责任。\n2. 信仰活动场所的代表人或管理委员会成员须是常住越南的越南公民， 有完全民事行为能力且受到居民群体的信任。\n3. 信仰活动场所所在地的乡级人民委员会会同同级越南祖国战线组织当地居民选举代表人或者管理委员会成员。根据选举结果和本条第 2 款规定的条件， 乡级人民委员会须自选举之日起 5 日之内将信仰活动场所的管理人或者管理委员会成员选举结果予以公示。\n4. 对于被列入了历史文化名胜遗迹的信仰活动场所， 其代表人的选举或管理委员会的设立适用 《文化遗产法》 相关法律的规定。\n5. 选举家族祠堂的代表人或设立管理委员会不需遵守本条第 3 款的规定。\n·147· 越南社会主义共和国信仰、宗教法"}},{"id":"VN-H067-A12","no":12,"noLabel":{"zh":"第12条"},"chapter":{"zh":"第三章"},"text":{"zh":"登记信仰活动\n1. 除家族祠堂以外， 信仰活动场所的信仰活动必须登记。\n2. 除本法第 14 条规定的情形以外， 信仰活动场所的代表人或者管理委员会必须在信仰活动开展前至少 30 日将登记材料递交给所在地的乡级人民委员会。\n登记材料须详细说明信仰活动的主题、 活动项目、 内容、 规模以及组织的时间和地点。\n乡级人民委员会须在接到符合规定的登记材料之日起 15 日内给出书面批复， 如不予登记应说明理由。\n3. 对已获批准的登记材料中漏报的信仰活动项目， 信仰活动场所的代表人或者管理委员会必须按照本条第 2 款的规定在信仰活动开展 20 日前进行补充登记。"}},{"id":"VN-H067-A13","no":13,"noLabel":{"zh":"第13条"},"chapter":{"zh":"第三章"},"text":{"zh":"举办定期信仰节日\n1. 在定期信仰节日举办前至少 20 日， 信仰活动场所的代表人或者管理委员会必须按照以下规定书面报告给主管国家机关：\n（1） 在乡、 坊、 镇 （以下统称 “乡” ） 范围内举办的信仰节日向节日组织地所在的乡级人民委员会递交书面报告；\n（2） 在同一市区县、 市镇、 省级市或直辖市 （以下统称 “县” ） 的多个乡共同举办的信仰节日向节日组织地所在的县级人民委员会递交书面报告；\n（3） 在同一省或直辖市 （以下统称 “省” ） 的多个县共同举办的信仰节日向节日组织地所在的省级人民委员会递交书面报告。\n2. 报告须详细说明信仰节日名称、 内容、 规模、 组织时间与地点、 组织委员会成员初步名单以及其他保障节日举办期间社会安全、 秩序和保护环境的措施。\n3. 对于被列入了历史文化名胜遗迹的信仰节日， 开展节日活动适用 《文化遗产法》 相关法律的规定。\n4. 本条第 1 款规定的主管国家机关必须保证相关信仰节日按照报告内容举办。"}},{"id":"VN-H067-A14","no":14,"noLabel":{"zh":"第14条"},"chapter":{"zh":"第三章"},"text":{"zh":"举办新的信仰节日、 恢复举办的信仰节日或者有变动的定期信仰节日\n1. 在举办新的信仰节日、 间隔一段时间又恢复举办的信仰节日或者在规模、 内容、 时间、 地点方面有变动的定期信仰节日之前， 信仰活动场所的代表人或者管理委员会必须向所在地省级人民委员会递交登记材料。\n登记材料须详细说明信仰节日名称、 节日内容 （或者变动后的节日内容） 、 规模、 组织时间与地点、 组织委员会成员初步名单以及其他保障节日举办期间社会安全、 秩序和保护环境的措施。\n“一带一路”法律查明     第 1 卷 ·148·\n2. 省级人民委员会须在接到符合规定的登记材料之日起 30 日内给出书面批复， 如不予登记应说明理由。"}},{"id":"VN-H067-A15","no":15,"noLabel":{"zh":"第15条"},"chapter":{"zh":"第四章"},"text":{"zh":"举办信仰节日收款的管理和使用\n1. 信仰活动场所的代表人或管理委员会负责合理、 公开透明地管理和使用举办信仰节日获得的收款。\n2. 在节日结束后 20 日内， 代表人或管理委员会必须向本法第 13 条第 1 款规定的主管国家机关书面报告收款情况及其使用目的。\n第四章  登记集体宗教实践和宗教活动"}},{"id":"VN-H067-A16","no":16,"noLabel":{"zh":"第16条"},"chapter":{"zh":"第四章"},"text":{"zh":"登记集体宗教实践的条件\n1. 在符合下列条件的情况下， 宗教组织可为尚未成立直属宗教组织的地方信徒登记集体宗教实践活动， 持有宗教活动登记证书的组织可为本组织成员进行集体宗教实践登记：\n（1） 有宗教实践的合法地点；\n（2） 宗教实践小组的代表人须是常住越南的越南公民， 具有完全民事行为能力， 非因信仰、 宗教问题正在受到行政处罚， 没有犯罪记录或者不是依据 《刑事诉讼法》 正被定罪的人；\n（3） 宗教实践的内容不属于本法第5 条规定的情形。\n2. 不属于本条第 1 款规定情形的信教人员， 登记集体宗教实践除了须完全符合本条第 1 款规定的条件以外， 还须符合下列条件：\n（1） 有教义、 教法；\n（2） 宗教实践小组的名称不能与其他宗教组织、 持有宗教活动登记证书的组织、 政治组织、 政治社会组织的名称以及名人、 民族英雄的姓名相同。"}},{"id":"VN-H067-A17","no":17,"noLabel":{"zh":"第17条"},"chapter":{"zh":"第四章"},"text":{"zh":"集体宗教实践登记的程序、 手续和审批\n1. 宗教组织、 持有宗教活动登记证书的组织或者本法第 16 条第 2 款规定的宗教小组的代表人向宗教实践地点所在地的乡级人民委员会递交集体宗教实践登记材料。\n2. 登记材料包括：\n（1） 登记文件详细说明登记组织的名称、 宗教名称、 代表人的姓名与居住地、 参加人数以及宗教实践的内容、 地点和时间；\n（2） 证明宗教实践地点是合法地点的证明材料；\n（3） 集体宗教实践小组代表人的个人简历；\n·149· 越南社会主义共和国信仰、宗教法\n（4） 本法第16 条第 2 款规定情形的教义、 教法概要。\n3. 乡级人民委员会须在接到符合规定的登记材料之日起 20 日内给出书面批复， 如不予登记应说明理由。"}},{"id":"VN-H067-A18","no":18,"noLabel":{"zh":"第18条"},"chapter":{"zh":"第四章"},"text":{"zh":"授予宗教活动登记证书的条件被授予宗教活动登记证书的组织须符合下列条件：\n1. 有教义、 教法、 仪式；\n2. 具有合法的宗旨、 目标、 活动规范；\n3. 组织的名称不能与其他宗教组织、 持有宗教活动登记证书的组织、 政治组织、 政治社会组织的名称以及名人、 民族英雄的姓名相同；\n4. 组织的代表人、 领导须是常住越南的越南公民， 具有完全民事行为能力， 非因信仰、 宗教问题正在受到行政处罚， 没有犯罪记录或者不是依据 《刑事诉讼法》 正被定罪的人；\n5. 有设立办事处的合法地点；\n6. 宗教活动的内容不属于本法第 5 条规定的情形。"}},{"id":"VN-H067-A19","no":19,"noLabel":{"zh":"第19条"},"chapter":{"zh":"第四章"},"text":{"zh":"宗教活动登记证书的登记程序、 手续和审批\n1. 符合本法第 18 条规定条件的组织向本条第 3 款规定的主管国家机关递交登记材料。\n2. 登记材料包括：\n（1） 登记文件详细说明登记组织的名称、 宗教名称、 宗旨、 目标、 活动的内容与地点、 在越南的产生背景和发展历程、 组织代表人的姓名、 信仰人数、 组织结构以及初步确定的办事处设立地点；\n（2） 组织的代表人和初步确定的领导人的名单、 个人简历、 司法记录证明以及在参与的宗教活动概要；\n（3） 教义、 教法和仪式概要；\n（4） 组织的活动规范；\n（5） 拥有合法地点作为办事处的证明材料。\n3. 宗教活动登记证书的审批：\n（1） 对在一个省范围内开展活动的组织， 省级人民委员会主管信仰、 宗教事务的专门机关 （以下统称 “省级信仰宗教专门机关” ） 必须在接到符合规定的登记材料之日起60 日内作出是否授予宗教活动登记证书的批复， 如拒绝授予登记证书应说明理由；\n（2） 对在多省开展活动的组织， 主管信仰、 宗教事务的中央国家机关必须在接到符合 “一带一路”法律查明     第 1 卷 ·150· 规定的登记材料之日起 60 日内作出是否授予宗教活动登记证书的批复， 如拒绝授予登记证书应说明理由。"}},{"id":"VN-H067-A20","no":20,"noLabel":{"zh":"第20条"},"chapter":{"zh":"第五章"},"text":{"zh":"关于组织被授予宗教活动登记证书后的安排\n1. 组织被授予宗教活动登记证书后， 可开展下列活动：\n（1） 组织宗教仪式、 宗教实践、 讲道、 讲授教义；\n（2） 任命、 选举、 推选执事；\n（3） 修缮、 改造办事处；\n（4） 参加慈善活动、 人道活动；\n（5） 根据宪章组织大会。\n2. 在开展本条第 1 款规定的活动时， 组织应遵守本法和其他相关法律的规定。\n第五章  宗教组织第一节  宗教组织的认证； 直属宗教组织的设立、 新设分立、 派生分立、 吸收合并、 新设合并"}},{"id":"VN-H067-A21","no":21,"noLabel":{"zh":"第21条"},"chapter":{"zh":"第五章"},"text":{"zh":"宗教组织的认证条件持有宗教活动登记证书的组织在符合下列条件的情况下可以被认证为宗教组织：\n1. 自被授予宗教活动登记证书之日起稳定、 连续活动5 年以上；\n2. 有符合本法第 23 条规定的宪章；\n3. 组织的代表人、 领导须是常住越南的越南公民， 具有完全民事行为能力， 非因信仰、 宗教问题正在受到行政处罚， 没有犯罪记录或者不是依据 《刑事诉讼法》 正被定罪的人；\n4. 有符合宪章规定的组织机构；\n5. 拥有独立于个人、 其他组织的财产， 以组织的财产承担责任；\n6. 以组织的名义独立参与法律关系。"}},{"id":"VN-H067-A22","no":22,"noLabel":{"zh":"第22条"},"chapter":{"zh":"第五章"},"text":{"zh":"宗教组织的申请程序、 手续和审批\n1. 符合本法第 21 条规定的所有条件的组织可向本条第 3 款规定的主管国家机关递交宗教组织认证申请。\n2. 申请材料包括：\n（1） 申请文件详细说明申请认证的组织名称、 对外交流名称 （如有） 、 宗教名称、 组织代表人姓名、 申请时组织的信徒数量与活动范围、 组织结构、 办事处；\n（2） 组织自被授予宗教活动登记证书之日起的活动历程概要；\n·151· 越南社会主义共和国信仰、宗教法\n（3） 组织的代表人和初步确定的领导人的名单、 个人简历、 司法记录证明以及在参与的宗教活动概要；\n（4） 教义、 教法和仪式概要；\n（5） 组织宪章；\n（6） 组织的合法财产登记表；\n（7） 拥有合法地点作为办事处的证明材料。\n3. 宗教组织认证的审批：\n（1） 对在一个省范围内开展活动的组织， 省级人民委员会须在接到符合规定的材料之日起 60 日内作出是否准予认证为宗教组织的批复， 如拒绝认证应说明理由；\n（2） 对在多省开展活动的组织， 主管信仰、 宗教事务的中央国家机关必须在接到符合规定的材料之日起 60 日内作出是否准予认证为宗教组织的批复， 如拒绝认证应说明理由。"}},{"id":"VN-H067-A23","no":23,"noLabel":{"zh":"第23条"},"chapter":{"zh":"第五章"},"text":{"zh":"宗教组织的宪章宗教组织的宪章包括下列基本内容：\n1. 组织的名称；\n2. 活动的宗旨、 目标和活动原则；\n3. 活动范围， 主要办事处；\n4. 财政、 财产；\n5. 法定代表人， 印章；\n6. 宗教组织、 直属宗教组织的职能、 任务、 权限和组织结构；\n7. 宗教组织、 直属宗教组织的领导队伍的任务、 权限；\n8. 关于任命、 选举、 推选、 调动、 撤职、 罢免职敕、 执事和修行者的条件、 标准、 权力和方式；\n9. 解散宗教组织以及设立、 新设分立、 派生分立、 吸收合并、 新设合并、 解散直属宗教组织的条件、 权力和方式；\n10. 会议和大会的组织程序、 决议通过的程序、 修改与补充宪章的程序以及解决组织内部分歧的原则和方式；\n11. 宗教组织和直属宗教组织的关系以及宗教组织与其他相关组织、 个人之间的关系。"}},{"id":"VN-H067-A24","no":24,"noLabel":{"zh":"第24条"},"chapter":{"zh":"第五章"},"text":{"zh":"宪章修改\n1. 宗教组织修改宪章必须向本法第 22 条第 3 款规定的主管国家机关登记。登记文 “一带一路”法律查明     第 1 卷 ·152· 件详细说明宗教组织的名称、 代表人、 内容、 修改理由， 并附上修改后的宪章。\n2. 主管国家机关须在接到符合规定的登记材料之日起 30 日内给出书面批复， 如不予登记应说明理由。\n3. 宗教组织自主管国家机关批准修改之日起根据修改后的宪章开展活动。"}},{"id":"VN-H067-A25","no":25,"noLabel":{"zh":"第25条"},"chapter":{"zh":"第五章"},"text":{"zh":"宗教组织的名称\n1. 宗教组织要有越南语名称。\n2. 宗教组织的名称不能与其他宗教组织、 持有宗教活动登记证书的组织、 政治组织、 政治社会组织的名称以及名人、 民族英雄的姓名相同。\n3. 宗教组织在与其他组织、 个人的关系中使用其名称。\n4. 宗教组织的名称受法律承认和保护。\n5. 宗教组织更改名称须报请本法第 22 条第 3 款规定的主管国家机关批准。\n6. 直属宗教机构更改名称须由宗教组织报请本法第 29 条第 3 款规定的主管国家机关批准。"}},{"id":"VN-H067-A26","no":26,"noLabel":{"zh":"第26条"},"chapter":{"zh":"第五章"},"text":{"zh":"宗教组织办事处的迁移\n1. 迁移宗教组织办事处须报请新办事处所在地的省级人民委员会的批准， 并且书面上报给本法第 22 条第 3 款规定的主管国家机关。\n2. 迁移直属宗教组织的办事处须报请新办事处所在地的省级人民委员会的批准， 并且书面上报给本法第 29 条第 3 款规定的主管国家机关。"}},{"id":"VN-H067-A27","no":27,"noLabel":{"zh":"第27条"},"chapter":{"zh":"第五章"},"text":{"zh":"直属宗教组织的设立、 新设分立、 派生分立、 吸收合并、 新设合并\n1. 宗教组织、 直属宗教组织可设立直属宗教组织； 一个直属宗教组织分立成多个新的直属宗教组织； 直属宗教组织被吸收进另一个直属宗教组织； 多个直属宗教组织合并为一个新的直属宗教组织。\n2. 新设分立以后， 分立前的直属宗教组织消灭， 其权利、 义务由分立后的直属宗教组织承继。\n3. 派生分立以后， 派生分立出去的新直属宗教组织与未派生分立出去的直属宗教组织按照活动目的享有和承担各自的权利和义务。\n4. 吸收合并以后， 被吸收合并的直属宗教组织消失， 其权利和义务由吸收该组织的直属宗教组织承继。\n5. 新设合并以后， 旧的直属宗教组织自新的直属宗教组织成立之日起消失， 其权利和义务由新成立的直属宗教组织承继。\n·153· 越南社会主义共和国信仰、宗教法"}},{"id":"VN-H067-A28","no":28,"noLabel":{"zh":"第28条"},"chapter":{"zh":"第五章"},"text":{"zh":"直属宗教组织的设立、 新设分立、 派生分立、 吸收合并、 新设合并的条件宗教组织、 直属宗教组织进行直属宗教组织的设立、 新设分立、 派生分立、 吸收合并、 新设合并必须满足下列条件：\n1. 宗教组织的宪章有规定关于直属宗教组织的设立、 新设分立、 派生分立、 吸收合并、 新设合并办法；\n2. 设立、 新设分立、 派生分立、 吸收合并、 新设合并前的直属宗教组织的活动不属于本法第 5 条规定的情形；\n3. 有设立办事处的合法地点。"}},{"id":"VN-H067-A29","no":29,"noLabel":{"zh":"第29条"},"chapter":{"zh":"第五章"},"text":{"zh":"直属宗教组织的设立、 新设分立、 派生分立、 吸收合并、 新设合并的申请程序、 手续、 审批\n1. 在进行直属宗教组织的设立、 新设分立、 派生分立、 吸收合并、 新设合并之前， 宗教组织、 直属宗教组织必须向本条第3 款规定的主管国家机关递交申请材料。\n2. 申请材料包括：\n（1） 申请文件详细说明理由、 申请组织名称、 申请设立的直属宗教组织名称， 写明新设分立、 派生分立、 吸收合并、 新设合并前后的组织名称和代表人， 注明在设立之时的活动范围与信徒数量或新设分立、 派生分立、 吸收合并、 新设合并前后的活动范围与信徒数量， 并说明设立、 新设分立、 派生分立、 吸收合并、 新设合并后直属宗教组织的组织结构以及初步确定的办事处设立地点；\n（2） 新设分立、 派生分立、 吸收合并、 新设合并前的直属宗教组织的活动历程概要文件；\n（3） 直属宗教组织的代表人和初步确定的领导人的名单、 个人简历、 司法记录证明以及在参与的宗教活动概要；\n（4） 直属宗教机构的宪章 （如有） ；\n（5） 直属宗教组织的合法财产登记表；\n（6） 拥有合法地点作为办事处的证明材料。\n3. 直属宗教组织的设立、 新设分立、 派生分立、 吸收合并、 新设合并的审批：\n（1） 对在一个省范围内开展活动的直属宗教组织， 省级人民委员会须在接到符合规定的材料之日起 60 日内作出是否准予设立、 新设分立、 派生分立、 吸收合并、 新设合并的批复， 如不批准应说明理由；\n（2） 对在多省开展活动的直属宗教组织， 主管信仰、 宗教事务的中央国家机关必须在接到符合规定的材料之日起 60 日内作出是否准予设立、 新设分立、 派生分立、 吸收合并、 “一带一路”法律查明     第 1 卷 ·154· 新设合并的批复， 如不批准应说明理由。\n4. 在获得主管国家机关的批准之后， 宗教组织、 直属宗教组织将会接到准予设立、 新设分立、 派生分立、 吸收合并、 新设合并直属宗教组织的文件。\n主管国家机关的批准之日起批准文件有效期为一年， 如果宗教组织、 直属宗教组织在一年内不设立、 新设分立、 派生分立、 吸收合并、 新设合并直属宗教组织， 则该文件失效。"}},{"id":"VN-H067-A30","no":30,"noLabel":{"zh":"第30条"},"chapter":{"zh":"第五章"},"text":{"zh":"宗教组织、 直属宗教组织的法人资格\n1. 宗教组织自主管国家机关认证之日起具有非商业性法人资格。\n2. 直属宗教组织在符合本法第 21 条第 5 款规定的情况下， 宗教组织报请本法第 29 条第 3 款规定的主管国家机关为其进行非商业性法人登记。\n3. 政府对直属宗教组织法人登记的程序、 手续作出具体规定。"}},{"id":"VN-H067-A31","no":31,"noLabel":{"zh":"第31条"},"chapter":{"zh":"第二节"},"text":{"zh":"宗教组织、 直属宗教组织的解散\n1. 如产生下列情形之一， 宗教组织、 直属宗教组织解散：\n（1） 宪章规定解散的情形；\n（2） 自主管国家机关认证或批准设立、 新设分立、 派生分立、 吸收合并、 新设合并之日起超过一年未开展宗教活动， 连续一年以上不开展宗教活动；\n（3） 勒令停止一切宗教活动期满尚未能解决造成其停止活动的问题。\n2. 主管国家机关有职责对宗教组织是否有权解散进行认证。\n宗教组织、 直属宗教组织有权解散直属宗教组织。在产生本条第 1 款第 2 项和第 3 项规定的情形时， 本法第 29 条第 3 款规定的主管国家机关有权解散或者要求宗教组织、 直属宗教组织解散直属宗教组织。\n3. 解散之前， 宗教组织、 直属宗教组织必须履行全部债务。宗教组织、 直属宗教组织解散后的财产根据民法规定处理。\n宗教组织、 直属宗教组织须自直属宗教组织解散之日起 20 日内上报给本法第 29 条第 3 款规定的主管国家机关。\n4. 政府对宗教组织、 直属宗教组织的解散程序、 手续作出具体规定。\n第二节  任命、 选举、 推选、 调动、 撤职、 罢免职敕、 执事和修行者"}},{"id":"VN-H067-A32","no":32,"noLabel":{"zh":"第32条"},"chapter":{"zh":"第二节"},"text":{"zh":"任命、 选举、 推选职敕和执事\n1. 宗教组织、 直属宗教组织根据宪章进行任命、 选举、 推选。\n2. 被任命、 选举、 推选的人具有完全民事行为能力， 非因信仰、 宗教问题正在受到行 ·155· 越南社会主义共和国信仰、宗教法政处罚， 没有犯罪记录或者不是依据 《刑事诉讼法》 正被定罪的人。\n3. 具有涉外因素的任命、 选举、 推选适用本法第51 条的规定。"}},{"id":"VN-H067-A33","no":33,"noLabel":{"zh":"第33条"},"chapter":{"zh":"第二节"},"text":{"zh":"职敕的任命、 推选上报\n1. 宗教组织须自任命、 推选之日起 20 日内向主管信仰、 宗教事务的中央国家机关书面上报被任命、 推选为下列职位的宗教教职人员： 越南佛教的和尚、 上座、 尼长、 尼师； 福音组织的牧师； 高台圣教的配师以上的职位； 越南静度居士佛会讲师以上的职位； 其他宗教组织的同级职位。\n2. 对本条第 1 款规定以外的其他职务的任命和推选， 宗教组织须自任命、 推选之日起 20 日内书面上报给职敕居住地和宗教活动开展地所在的省级信仰宗教专门机关。\n3. 上报材料详细说明宗教组织的名称、 姓名、 职位、 活动范围、 宗教活动、 参与的宗教活动概要， 并附上职敕的个人简历、 司法记录证明。\n4. 如被任命和推选的职敕不符合本法第 32 条第 2 款的规定， 主管国家机关应书面要求宗教组织撤销职敕的任命和推选结果。\n在接到撤销任命和推选的文件之日起 20 日内， 宗教组织有责任撤销职敕的任命和推选结果， 并将处理结果上报给本条第1 款和第 2 款规定的主管国家机关。"}},{"id":"VN-H067-A34","no":34,"noLabel":{"zh":"第34条"},"chapter":{"zh":"第二节"},"text":{"zh":"任命、 选举和推选教职人员的登记\n1. 宗教组织在任命、 选举和推选下列执事之前， 须将相关人员的登记材料递交给主管信仰、 宗教事务的中央国家机关：\n（1） 在多省开展活动的宗教组织的领导队伍；\n（2） 在多省开展活动的直属宗教组织的负责人；\n（3） 宗教培训场所的负责人。\n2. 对本条第 1 款规定以外的其他教职人员， 宗教组织、 直属宗教组织须在任命、 选举、 推选之前向执事居住地和宗教活动开展地所在的省级信仰宗教专门机关递交登记材料。\n3. 持有宗教活动登记证书的组织须在任命、 选举、 推选执事之前向本法第 19 条第 3 款规定的主管国家机关递交登记材料。\n4. 登记材料包括：\n（1） 登记材料详细说明拟定任命、 选举、 推选者的姓名及其在任命、 选举、 推选前后的职位、 职务和负责区域；\n（2） 拟定任命、 选举、 推选者的个人简历、 司法记录证明；\n（3） 拟定任命、 选举、 推选者参与的宗教活动概要。\n5. 本条第 1 款 、第2 款 、第3 款规定的主管国家机关必须在接到符合规定的材料之日 “一带一路”法律查明     第 1 卷 ·156· 起 20 日内作出书面批复， 如不予登记应说明理由。\n6. 宗教组织、 直属宗教组织、 持有宗教活动登记证书的组织须自任命、 选举、 推选之日起 20 日内将任命、 选举、 推选的人员名单书面上报给本条第1 款 、第2 款和本法第 19 条第 3 款规定的主管国家机关。\n7. 对本法第 19 条 、第22 条 、第29 条 、第38 条规定的初步确定的宗教领导， 在获得主管国家机关批准之后， 须根据本条第6 款的规定上报任命、 选举、 推选的人员名单。"}},{"id":"VN-H067-A35","no":35,"noLabel":{"zh":"第35条"},"chapter":{"zh":"第二节"},"text":{"zh":"职敕、 执事、 修行者的职位调动\n1. 宗教组织、 直属宗教组织须自调动职敕、 执事、 修行者的职位前至少20 日向调出地和调入地的省级信仰宗教专门机关递交上报材料。\n上报材料详细说明上报组织名称、 调动人员的姓名、 职位、 职务、 调动原因以及其调动前后的活动区域。\n2. 在调动职敕、 执事、 修行者之前， 发现其正被定罪或者尚未消除犯罪记录， 宗教组织、 直属宗教组织应将登记材料递交给调入地的省级人民委员会。\n登记材料详细说明上报组织名称、 调动人员的姓名、 职位、 职务、 调动原因以及其调动前后的活动区域。\n省级人民委员会必须在接到符合规定的登记材料之日起 30 日内作出书面批复， 如不予登记应说明理由。"}},{"id":"VN-H067-A36","no":36,"noLabel":{"zh":"第36条"},"chapter":{"zh":"第三节"},"text":{"zh":"职敕、 执事的撤职、 罢免\n1. 宗教组织、 直属宗教组织根据宪章进行职敕、 执事的撤职、 罢免。\n2. 自职敕、 执事的撤职、 罢免文件出来的20 日以内， 宗教组织、 直属宗教组织必须书面上报给本法第 33 条第 1 款 、第2 款和第 34 条第 1 款 、第2 款规定的主管国家机关。\n上报材料详细说明被撤职、 罢免人员的姓名、 职位、 职务、 被撤职或罢免原因， 并附上宗教组织、 直属宗教组织的撤职、 罢免文件。\n3. 持有宗教活动登记证书的组织须按照本条第 2 款的规定书面上报给本法第 19 条第 3 款规定的主管国家机关。\n第三节  宗教培训场所、 宗教培训班"}},{"id":"VN-H067-A37","no":37,"noLabel":{"zh":"第37条"},"chapter":{"zh":"第三节"},"text":{"zh":"宗教培训场所的设立条件宗教组织设立宗教培训场所须满足下列条件：\n1. 有保证培训活动的物质基础；\n2. 有设立培训场所的合法地点；\n·157· 越南社会主义共和国信仰、宗教法\n3. 制定了培训方案和内容， 且培训方案有开设越南历史和越南法律课程；\n4. 具有满足培训需求的管理人员和教师。"}},{"id":"VN-H067-A38","no":38,"noLabel":{"zh":"第38条"},"chapter":{"zh":"第三节"},"text":{"zh":"设立宗教培训场所的申请程序、 手续和审批\n1. 在设立宗教培训场所之前， 宗教组织须向主管信仰、 宗教事务的中央国家机关递交申请材料。\n2. 申请材料包括：\n（1） 申请设立宗教培训场所的文件须详细说明宗教组织名称、 培训场所名称、 培训场所代表人姓名以及设立培训场所的必要性。\n（2） 培训场所的代表人和初步确定的领导人的名单、 个人简历、 司法记录证明以及在参与的宗教活动概要。\n（3） 培训场所的组织与活动规范草案， 包括以下基本内容： 培训组织名称、 办事处地点、 职能、 任务、 组织结构、 人事架构、 培训层次、 培训类型、 教学方案和内容、 各培训层次的培训方式、 财政与财产。\n（4） 培训场所的招生规范草案。\n（5） 拥有保障培训顺利进行的合法地点和物质基础的相关证明， 省级人民委员会对宗教培训场所设立地点的批准意见。\n3. 主管信仰、 宗教事务的中央国家机关必须在接到符合规定的材料之日起 60 日内作出是否准予设立宗教培训组织的批复， 如不批准应说明理由。\n4. 在主管国家机关批准后， 宗教组织将接到准予设立宗教培训场所的文件。\n主管国家机关的批准之日起批准文件有效期为 3 年， 如果宗教组织在3 年内不设立培训场所， 则该文件失效。\n5. 宗教培训场所不属于国民教育体系。"}},{"id":"VN-H067-A39","no":39,"noLabel":{"zh":"第39条"},"chapter":{"zh":"第三节"},"text":{"zh":"宗教培训场所的活动\n1. 宗教培训组织开始活动前至少 20 日， 宗教培训场所的代表人须向主管信仰、 宗教事务的中央国家机关递交关于宗教培训组织活动的书面材料， 同时附上设立宗教培训场所的批准文件、 组织与活动规范、 招生规范、 领导名单、 保障活动顺利开展的财政资源与物质基础报告。\n2. 宗教培训场所的培训、 招生工作按照已上报的组织与活动规范、 招生规范开展。\n3. 宗教培训组织修改组织与活动规范、 招生规范须向主管信仰、 宗教事务的中央国家机关递交登记材料。登记材料详细说明修改理由和修改内容， 并附上修改后的规范文件。\n主管国家机关必须在接到符合规定的登记材料之日起 45 日内作出书面批复， 如不予 “一带一路”法律查明     第 1 卷 ·158· 登记应说明理由。\n宗教培训场所自主管国家机关批准修改之日起根据修改后的规范开展活动。\n4. 宗教培训场所需自每学年结束后 20 日内向主管信仰、 宗教事务的中央国家机关书面上报年度培训结果。上报材料详细说明宗教培训场所的名称、 培训学年、 毕业学员人数。\n5. 外国学员在越南宗教培训场所学习适用本法第 49 条的规定。"}},{"id":"VN-H067-A40","no":40,"noLabel":{"zh":"第40条"},"chapter":{"zh":"第三节"},"text":{"zh":"越南历史和越南法律主管信仰、 宗教事务的中央国家机关主持、 配合教育与培训部、 司法部等相关部门开展越南历史和越南法律学科的教学引导工作。"}},{"id":"VN-H067-A41","no":41,"noLabel":{"zh":"第41条"},"chapter":{"zh":"第三节"},"text":{"zh":"宗教培训班的开办\n1. 宗教组织、 直属宗教组织开办培训班培养专门从事宗教活动的人须向省级宗教信仰专门机关递交登记材料。登记材料须详细说明培训班名称、 地点、 理由、 学习时间、 内容、 方案、 参加人员、 教师名单。\n省级宗教信仰专门机关必须在接到符合规定的登记材料之日起 30 日内作出书面批复， 如不予登记应说明理由。\n2. 宗教组织、 直属宗教组织开办的宗教培训班不符合本条第 1 款规定的， 必须自开讲前至少 20 日上报给培训班所在地的县级人民委员会。上报材料须详细说明培训班名称、 地点、 理由、 学习时间、 内容、 方案、 参加人员、 教师名单。\n如果开办的宗教培训班有本法第 5 条规定的行为， 县级人民委员会有权书面要求宗教组织、 直属宗教组织不开办或者停止培训班的活动。"}},{"id":"VN-H067-A42","no":42,"noLabel":{"zh":"第42条"},"chapter":{"zh":"第三节"},"text":{"zh":"宗教培训场所的解散\n1. 如产生下列情形之一， 宗教培训场所解散：\n（1） 根据宗教组织的决议；\n（2） 在主管国家机关批准设立之日起超过 3 年宗教培训场所尚未开展培训活动的；\n（3） 勒令停止宗教培训活动期满尚未能解决造成其停止活动的问题。\n2. 宗教组织有权解散宗教培训场所。在产生本条第 1 款第 2 项和第 3 项规定的情形时， 主管信仰、 宗教事务的中央国家机关有权解散或者要求宗教组织解散宗教培训场所。\n宗教组织须自直属宗教培训场所解散之日起 20 日内上报给主管信仰、 宗教事务的中央国家机关。\n3. 政府对宗教培训场所解体的程序、 手续作出具体规定。\n·159· 越南社会主义共和国信仰、宗教法第六章  宗教活动和宗教组织的出版、 教育、 医疗、 社会保障、 慈善、 人道主义活动第一节  宗教活动"}},{"id":"VN-H067-A43","no":43,"noLabel":{"zh":"第43条"},"chapter":{"zh":"第三节"},"text":{"zh":"宗教活动项目的上报\n1. 宗教组织、 直属宗教组织、 持有宗教活动登记证书的组织须自被认证、 被批准设立或被批准取得宗教活动登记证书之日起 30 日内须对年度宗教活动项目按下列规定进行书面上报：\n（1） 在一个乡范围内开展活动的组织上报给乡级人民委员会；\n（2） 多个乡范围内开展活动的组织上报给县级人民委员会；\n（3） 在多个县范围内开展活动的组织上报给省级信仰宗教专门机关；\n（4） 在多个省范围内开展活动的组织上报给主管信仰、 宗教事务的重要国家机关。\n2. 上报材料详细说明组织名称、 宗教活动项目名称以及活动举行的时间、 地点。\n3. 宗教活动项目一年上报一次。对不属于已上报宗教活动项目中的宗教活动， 宗教组织的代表人须自活动开展前至少 20 日根据本条第 1 款和第 2 款的规定进行补充上报。"}},{"id":"VN-H067-A44","no":44,"noLabel":{"zh":"第44条"},"chapter":{"zh":"第三节"},"text":{"zh":"宗教组织、 直属宗教组织的会议\n1. 宗教组织、 直属宗教组织召开年度会议须自会议召开前至少 20 日上报给本法"}},{"id":"VN-H067-A45","no":45,"noLabel":{"zh":"第45条"},"chapter":{"zh":"第三节"},"text":{"zh":"第 3 款规定的主管国家机关。\n上报材料详细说明组织名称、 预计参会成员与人数以及会议的内容、 流程、 时间和召开地点。\n2. 宗教组织、 直属宗教组织召开宗教联合会议、 具有涉外因素的会议须向主管信仰、 宗教事务的中央国家机关递交申请材料。申请材料详细说明组织名称、 召开理由、 预计参会成员与人数以及会议的内容、 流程、 时间和召开地点。\n主管信仰、 宗教的中央国家机关必须在接到符合规定的登记材料之日起 45 日内作出书面批复， 如不予登记应说明理由。\n第 45 条  宗教组织、 直属宗教组织、 持有宗教活动登记证书的组织的大会\n1. 宗教组织、 直属宗教组织、 持有宗教活动登记证书的组织在举行大会前必须向本条第 3 款规定的主管国家机关递交申请材料。\n2. 登记材料包括：\n（1） 登记文件详细说明组织名称、 召开理由、 预计参会成员与人数以及会议的内容、 “一带一路”法律查明     第 1 卷 ·160· 流程、 时间和召开地点；\n（2） 组织的活动总结报告；\n（3） 宪章草案或者宪章修改草案 （如有） 。\n3. 大会的审批：\n（1） 对在一个县范围内开展活动的直属宗教组织申请召开大会， 县级人民委员会须在接到符合规定的材料之日起 25 日内作出书面批复， 如不予批准应说明理由；\n（2） 对在多个县范围内开展活动的宗教组织、 直属宗教组织、 持有宗教活动登记证书的组织申请召开大会， 省级信仰宗教专门机关须在接到符合规定的材料之日起 30 日内作出书面批复， 如不予批准应说明理由；\n（3） 对本条第 3 款第 1 项和第 2 项规定以外的申请组织大会的情形， 省级信仰宗教专门机关须在接到符合规定的材料之日起 45 日内作出书面批复， 如不予批准应说明理由。"}},{"id":"VN-H067-A46","no":46,"noLabel":{"zh":"第46条"},"chapter":{"zh":"第三节"},"text":{"zh":"在宗教活动场所、 合法地点以外的地方举行仪式和讲道活动\n1. 在已登记的宗教活动场所、 合法地点以外的地方举行仪式和讲道活动前， 宗教组织、 直属宗教组织、 持有宗教活动登记证书的组织须向本条第3 款规定的主管国家机关递交申请材料。\n登记材料详细说明申请组织名称、 仪式名称、 主持人以及仪式的内容、 流程、 时间、 召开地点、 参与人员。\n2. 在已登记的负责区域、 宗教活动场所、 合法地点以外的地方讲道前， 职敕、 执事、 修行者须向本条第 3 款规定的主管国家机关递交申请材料。\n申请材料须详细说明申请人姓名、 内容、 理由、 方案、 时间、 地点、 参与人员。\n3. 在宗教活动场所、 合法地点以外的地方举行仪式和讲道活动的审批\n（1） 对在一个县范围内开展的仪式、 讲道活动， 县级人民委员会须在接到符合规定的材料之日起 25 日内作出书面批复， 如不予批准应说明理由；\n（2） 对在多个县范围内开展的仪式、 讲道活动， 仪式、 讲道活动以及举行地的省级信仰宗教专门机关须在接到符合规定的材料之日起 30 日内作出书面批复， 如不予批准应说明理由。\n4. 仪式、 讲道活动以及举行地的主管国家机关有责任协助保障仪式、 讲道活动举行过程中的安全与秩序。\n·161· 越南社会主义共和国信仰、宗教法第二节  具有社会因素的宗教活动"}},{"id":"VN-H067-A47","no":47,"noLabel":{"zh":"第47条"},"chapter":{"zh":"第三节"},"text":{"zh":"在越南合法居住的外国人的集体宗教实践\n1. 在越南合法居住的外国人参与宗教活动场所或其他合法地点的集体宗教实践， 须向宗教活动场所或者集体宗教实践活动计划开展地所在的省级人民委员会递交申请材料。\n2. 申请材料包括：\n（1） 申请文件详细说明代表人的姓名、 国籍和宗教， 说明参与集体宗教实践的理由、 时间、 内容以及参与人数、 宗教活动场所或集体宗教实践活动计划开展地；\n（2） 经核实的外国人在越南合法居住的证明材料复印件；\n（3） 宗教活动场所代表人的批准书或者有开展集体宗教实践活动的合法地点的证明材料。\n3. 省级人民委员会须在接到符合规定的材料之日起 30 日内作出书面批复， 如不予批准应说明理由。"}},{"id":"VN-H067-A48","no":48,"noLabel":{"zh":"第48条"},"chapter":{"zh":"第三节"},"text":{"zh":"外国组织和个人在越南参与宗教活动、 宗教国际关系活动\n1. 宗教组织、 直属宗教组织在邀请外国组织和个人到越南参与宗教活动、 宗教国际关系活动前须向本条第 3 款规定的主管国家机关递交申请材料。\n2. 申请材料包括：\n（1） 申请文件详细说明邀请组织的名称、 受邀的组织名称与个人姓名、 活动的目标与内容、 受邀人员名单、 初步确定的流程、 时间和举行地点；\n（2） 外国组织和个人参与的主要宗教活动的简要介绍；\n（3） 受邀人员的宗教活动职称证明文件。\n3. 外国组织和个人在越南开展宗教活动、 宗教国际关系活动的审批：\n（1） 邀请外国组织和个人到越南参与在一个省范围内举办的宗教活动， 省级人民委员会须在接到符合规定的材料之日起 30 日内作出书面批复， 如不批准应说明理由；\n（2） 邀请外国组织和个人到越南参与在多个省范围内举办的宗教活动或者宗教国际关系活动， 主管信仰、 宗教事务的中央国家机关须在接到符合规定的材料之日起 45 日内作出书面批复， 如不批准应说明理由。\n4. 持有宗教活动登记证书的组织邀请外国籍的职敕、 修行者来讲道须按本条第 2 款和第 3 款规定向主管国家机关递交申请材料。\n5. 外国集体宗教实践小组邀请外国籍的职敕、 修行者来讲道须向主管信仰、 宗教事务 “一带一路”法律查明     第 1 卷 ·162· 的中央国家机关递交符合本条第 2 款规定的申请材料。\n主管信仰、 宗教事务的中央国家机关须在接到符合规定的材料之日起 45 日内作出书面批复， 如不批准应说明理由。\n6. 在讲道过程中， 外国籍的职敕、 修行者须尊重越南宗教组织、 直属宗教组织、 持有宗教活动登记证书的组织的规定， 遵守越南法律规定。"}},{"id":"VN-H067-A49","no":49,"noLabel":{"zh":"第49条"},"chapter":{"zh":"第三节"},"text":{"zh":"外国人在越南宗教培训场所学习\n1. 在越南宗教培训场所学习的外国人须是在越南合法居住的人， 遵守越南法律， 自愿登记学习并经培训场所将申请材料递交给主管信仰、 宗教事务的中央国家机关。\n2. 申请材料包括：\n（1） 申请文件详细说明宗教培训场所的名称、 登记学习人员的姓名与国籍、 学年、 学习时间；\n（2） 经公证的登记学习人员户口的越南语译本；\n（3） 主管信仰、 宗教事务的中央国家机关须在接到符合规定的材料之日起 45 日内作出书面批复， 如不批准应说明理由。"}},{"id":"VN-H067-A50","no":50,"noLabel":{"zh":"第50条"},"chapter":{"zh":"第三节"},"text":{"zh":"赴外国参加宗教活动、 宗教培训活动\n1. 宗教组织、 直属宗教组织在派职敕、 执事、 修行者、 信徒赴国外参加宗教活动、 宗教培训活动前须向主管信仰、 宗教事务的中央国家机关递交登记材料。\n2. 登记材料包括：\n（1） 申请文件详细说明组织名称以及国外宗教活动、 宗教培训活动举行的目标、 方案、 时间、 地点；\n（2） 外国宗教组织发出的关于宗教活动、 宗教培训活动的邀请函或接收函。\n3. 主管信仰、 宗教事务的中央国家机关须在接到符合规定的材料之日起 45 日内作出书面批复， 如不批准应说明理由。"}},{"id":"VN-H067-A51","no":51,"noLabel":{"zh":"第51条"},"chapter":{"zh":"第三节"},"text":{"zh":"具有涉外因素的册封、 任命、 选举、 推选\n1. 具有涉外因素的册封、 任命、 选举、 推选包括下列情形：\n（1） 越南宗教组织册封或推选在越南合法居住的外国人担任宗教职位；\n（2） 外国宗教组织册封、 任命、 选举、 推选常住越南的越南公民担任宗教职位。\n2. 被册封、 任命、 选举、 推选的人须符合本法第32 条第 2 款规定的条件。对越南宗教组织申请册封或推选的在越南合法居住的外国人， 还需符合下列条件：\n（1） 在越南的宗教培训场所接受宗教培训；\n（2） 遵守越南法律。\n·163· 越南社会主义共和国信仰、宗教法\n3. 本条第 1 款规定的具有涉外因素的册封、 任命、 选举、 推选须得到主管信仰、 宗教事务的中央国家机关的批准。\n4. 对获得外国宗教组织册封、 任命、 选举、 推选在国外担任宗教职位的越南公民回国担任职敕、 执事， 对其直接管理的宗教组织、 直属宗教组织必须向负责信仰、 宗教事务的中央国家机关登记。\n5. 政府对本条规定的具有涉外因素的册封、 任命、 选举、 推选的程序、 批准手续和登记作出具体规定。"}},{"id":"VN-H067-A52","no":52,"noLabel":{"zh":"第52条"},"chapter":{"zh":"第三节"},"text":{"zh":"宗教组织、 直属宗教组织、 职敕、 执事、 修行者、 信徒的国际关系活动\n1. 宗教组织、 直属宗教组织、 职敕、 执事、 修行者、 信徒根据符合越南法律规定的宗教组织宪章开展国际关系活动。\n2. 开展国际关系活动时， 宗教组织、 直属宗教组织、 职敕、 执事、 修行者、 信徒必须遵守越南法律和其他相关法律。"}},{"id":"VN-H067-A53","no":53,"noLabel":{"zh":"第53条"},"chapter":{"zh":"第三节"},"text":{"zh":"加入外国宗教组织\n1. 在加入外国宗教组织前， 宗教组织须向主管信仰、 宗教事物的中央国家机关递交申请材料。\n2. 申请材料包括：\n（1） 申请文件详细说明宗教组织名称、 加入的目的和时间以及外国组织的名称、 宪章、 宗旨、 活动目标、 主要办事处；\n（2） 外国宗教组织的接收函或者邀请函。\n3. 主管信仰、 宗教事务的中央国家机关须在接到符合规定的材料之日起 60 日内作出书面批复， 如不批准应说明理由。\n4. 如分立出外国宗教组织， 宗教组织须自分立之日起 20 日内书面上报给主管信仰、 宗教事务的中央国家机关。\n上报材料详细说明宗教组织的名称、 已加入的外国宗教组织名称、 分立理由、 分立时间。\n第三节  出版、 教育、 医疗、 社会保障、 慈善、 人道主义领域的活动"}},{"id":"VN-H067-A54","no":54,"noLabel":{"zh":"第54条"},"chapter":{"zh":"第三节"},"text":{"zh":"出版、 生产、 出口、 进口文化产品可根据出颁法和其他法律规定出版宗教书籍和关于信仰、 宗教的其他出版物， 生产、 出口、 进口关于信仰、 宗教的文化产品、 宗教物品。"}},{"id":"VN-H067-A55","no":55,"noLabel":{"zh":"第55条"},"chapter":{"zh":"第三节"},"text":{"zh":"教育、 医疗、 社会保障、 慈善、 人道主义活动可根据相关法律规定参与教育、 培训、 医疗、 社会保障、 慈善、 人道主义活动。\n“一带一路”法律查明     第 1 卷 ·164· 第七章  信仰活动场所、 宗教组织的财产"}},{"id":"VN-H067-A56","no":56,"noLabel":{"zh":"第56条"},"chapter":{"zh":"第三节"},"text":{"zh":"信仰活动场所、 宗教组织财产的管理和使用\n1. 信仰活动场所、 宗教组织的财产包括组织成员缴纳的资金以及组织、 个人或其他形式捐赠的合法财产。\n2. 信仰活动场所、 宗教组织的财产要根据法律规定合理的管理和使用。\n3. 信仰活动场所、 宗教组织根据风俗习惯成立， 由组织成员共同出资、 捐资， 获取到旨在满足组织成员的信仰宗教需求的公共捐赠或其他合法资金， 这些资金属于组织的共同财产。\n4. 财产的变动、 转让、 赠与、 出租、 抵押、 以土地使用权出资适用相关法律规定。\n5. 政府对宗教组织、 直属宗教组织接收和管理国外组织与个人的资助， 以及信仰活动场所、 宗教组织、 直属宗教组织的捐赠事宜作出具体规定。"}},{"id":"VN-H067-A57","no":57,"noLabel":{"zh":"第57条"},"chapter":{"zh":"第三节"},"text":{"zh":"信仰活动场所和宗教活动场所的土地信仰活动场所和宗教活动场所的土地根据土地法的规定进行管理。"}},{"id":"VN-H067-A58","no":58,"noLabel":{"zh":"第58条"},"chapter":{"zh":"第三节"},"text":{"zh":"修缮、 升级、 新建信仰活动设施、 宗教活动设施\n1. 修缮、 升级、 新建信仰活动设施、 宗教活动设施须遵守 《建筑法》 的规定。\n2. 修缮、 升级、 新建信仰活动场所和宗教活动场所的附属设施参照适用 《建筑法》 关于在城市、 社区中心、 保护区、 历史文化革命遗址区建造工程、 居民房的相关规定。\n3. 信仰活动场所、 宗教活动场所的修缮、 修复被主管国家机关列入历史文化名胜遗迹， 修缮、 升级、 新建信仰活动场所和宗教活动场所的附属设施须遵守 《文化遗产法》 和 《建筑法》 的规定。"}},{"id":"VN-H067-A59","no":59,"noLabel":{"zh":"第59条"},"chapter":{"zh":"第八章"},"text":{"zh":"迁移信仰建筑、 宗教建筑为国防、 安全、 经济社会发展目的， 为了国家和社会利益， 可根据 《土地法》 和 《建筑法》 的规定迁移信仰建筑、 宗教建筑。\n第八章  信仰、 宗教领域的国家管理和犯罪处罚第一节  信仰、 宗教领域的国家管理"}},{"id":"VN-H067-A60","no":60,"noLabel":{"zh":"第60条"},"chapter":{"zh":"第八章"},"text":{"zh":"信仰、 宗教的国家管理内容\n1. 制定信仰、 宗教的相关政策， 颁布关于信仰、 宗教的法律规范文件；\n2. 规定信仰、 宗教事务的国家管理机关；\n·165· 越南社会主义共和国信仰、宗教法\n3. 组织落实信仰、 宗教的相关政策和法律；\n4. 普及、 教育关于信仰、 宗教的法律；\n5. 开展关于信仰、 宗教领域的研究， 培养从事信仰、 宗教工作的干部、 公职人员；\n6. 监察、 检查和解决信仰、 宗教领域的投诉、 控告和违法处理；\n7. 信仰、 宗教领域的国际关系活动。"}},{"id":"VN-H067-A61","no":61,"noLabel":{"zh":"第61条"},"chapter":{"zh":"第八章"},"text":{"zh":"信仰、 宗教领域的国家管理责任\n1. 政府统一管理全国范围内的宗教信仰事务。\n2. 主管宗教信仰事务的中央国家机关对信仰宗教事务进行国家管理， 对政府负责。\n3. 部委、 部级机关、 各级人民委员会在其任务、 权限范围内对信仰宗教事务进行国家管理。\n对未设立乡、 镇行政单位的县， 县级人民委员会同时承担本法规定的乡级人民委员会的任务、 权限。"}},{"id":"VN-H067-A62","no":62,"noLabel":{"zh":"第62条"},"chapter":{"zh":"第八章"},"text":{"zh":"对信仰宗教事务的专业监察\n1. 对信仰宗教事务的专业监察是主管国家机关对于机关、 组织、 个人执行信仰、 宗教相关法律的监察活动。\n主管信仰宗教事务的主管国家机关负责指导、 组织开展全国范围内信仰宗教事务的专业监察。\n2. 信仰宗教事务的专业监察进行以下任务：\n（1） 监察各级人民委员会对信仰、 宗教相关的政策、 法律的执行情况；\n（2） 监察疑似违反 《信仰、 宗教法》 的事务。"}},{"id":"VN-H067-A63","no":63,"noLabel":{"zh":"第63条"},"chapter":{"zh":"第二节"},"text":{"zh":"关于信仰宗教问题的投诉、 控告、 起诉\n1. 信仰活动场所、 宗教组织、 直属宗教组织的代表人和管理委员会、 职敕、 执事、 修行者、 信徒和其他有权利和义务关系的组织与个人有权投诉， 有权提起行政诉讼和民事诉讼， 要求通过法院解决民事纠纷， 依法保护自己的合法权利和利益。\n2. 个人有权控告违反 《信仰、 宗教法》 的行为。关于违反 《信仰、 宗教法》 控告的处理适用 《控告法》 的规定。\n第二节  信仰、 宗教领域的违法处理"}},{"id":"VN-H067-A64","no":64,"noLabel":{"zh":"第64条"},"chapter":{"zh":"第二节"},"text":{"zh":"信仰、 宗教的违法处理\n1. 组织、 个人有违反 《信仰、 宗教法》 的行为或者利用信仰、 宗教进行违法活动， 根据情节、 违法程度处以行政处罚或追究其刑事责任， 如造成损害须依法赔偿。\n“一带一路”法律查明     第 1 卷 ·166·\n2. 根据本法和 《行政处罚法》 ， 政府对信仰宗教领域的行政违法行为、 处罚形式、 处罚程度、 行政违法判决的补救措施、 处罚的审批、 具体的处罚程度、 行政违法行为记录的审批、 行政处罚措施的适用制度作出规定。"}},{"id":"VN-H067-A65","no":65,"noLabel":{"zh":"第65条"},"chapter":{"zh":"第九章"},"text":{"zh":"对干部和公务人员执行公务时违反 《信仰、 宗教法》 的处罚干部和公务人员执行公务时违反 《信仰、 宗教法》 ， 根据情节、 违法程度依法处以纪律处罚或追究其刑事责任， 具体违法行为包括：\n1. 利用职务、 权限之便而做出违法本法和其他相关法律规定的行为；\n2. 因玩忽职守而引起违反 《信仰、 宗教法》 行为；\n3. 违反对信仰活动、 宗教活动的国家管理中关于行政程序、 手续的规定。\n第九章  施行条款"}},{"id":"VN-H067-A66","no":66,"noLabel":{"zh":"第66条"},"chapter":{"zh":"第九章"},"text":{"zh":"施行效力\n1. 本法自 2018 年 1 月 1 日起生效。\n2.21/2004/UBTVQH11 号 《信仰、 宗教法令》 自本法生效时废止。"}},{"id":"VN-H067-A67","no":67,"noLabel":{"zh":"第67条"},"chapter":{"zh":"第九章"},"text":{"zh":"过渡条款\n1. 在本法生效之前已经批准登记的集体宗教实践、 已持有宗教活动登记证书的组织、 已认证的宗教组织不需根据本法第 17 条 、第19 条和第 22 条的规定重新登记和认证。\n2. 在本法生效之前已经进行设立、 新设分立、 派生分立、 吸收合并、 新设合并的直属宗教组织以及已登记的宗教协会、 修行组织不需根据本法第 29 条和第 38 条重新申请和登记。\n3. 在本法生效之前已持有宗教活动登记证书的组织， 其被认证为宗教组织的时限适用本法第 21 条第 1 款规定， 自被授予宗教活动登记证书之日起算。\n4. 在本法生效之前已被认证的宗教组织在本法生效之日起变更为非商业性法人。各宗教组织须在最近的一次大会上根据第 23 条的规定修改宪章， 并根据本法第 24 条的规定进行修改宪章的登记。\n5. 在本法生效之日起 30 日内， 在本法生效之前已认证的宗教组织、 已设立的直属宗教组织、 已持有宗教活动登记证书的组织须按照本法第 43 条第 1 款和第 2 款的规定向主管国家机关上报年度宗教活动项目。\n6. 在本法生效之日起 30 日内， 在本法生效之前已上报年度信仰活动的信仰活动场所须按本法第 12 条第 2 款规定进行信仰活动登记。\n·167· 越南社会主义共和国信仰、宗教法"}},{"id":"VN-H067-A68","no":68,"noLabel":{"zh":"第68条"},"chapter":{"zh":"第九章"},"text":{"zh":"具体规定政府对本法各项条款作出具体规定。\n本法由越南社会主义共和国第十四届国会第二次会议于 2016 年 11 月 18 日通过。\n国会主席  阮氏金银"}}],"pack":"vn-p03","rebuiltFrom":"原为单条全文，2026-10-24 按条号标记重新切分（拼接无损校验通过）"};
  FT["VN-H068"] = {"id":"VN-H068","coverage":"full","language":"zh","sourceName":"越南官方发布渠道","sourceUrl":"","fetchedAt":"2026-10-04","articleCount":10,"structureMode":"ARTICLE","title":{"zh":"个人信息保护条例","en":"Decree on Personal Data Protection","orig":null},"level":"law","status":"active","docNumber":"年份不详","issuingBody":"越南官方发布渠道","completenessNote":"全文，共 11 条；取自《东盟法律分类》归档中的 PDF 原件，逐字未改写。","country":"VN","countryName":"越南","layer":"intl","articles":[{"id":"VN-H068-A2","no":2,"noLabel":{"zh":"第 2 条"},"heading":{"en":"描述违反个人数据保护规定的情况"},"text":{"zh":"时间：\n地点：\n行为：\n团体、个人、个人数据类型及相关数据数量：\n危害后果：\n已采取措施："}},{"id":"VN-H068-A4","no":4,"noLabel":{"zh":"第 4 条"},"heading":{"en":"承诺"},"text":{"zh":"（机构、组织、商业行业名称）特此承诺：对所提供的信息和随附文件的准确性和合法性承担法律负责。\n(注明企业名称、名称及印章) 表格编号 04 越南社会主义共和国独立-自由-幸福日 月 年个人信息处理影响评估档案的通知尊敬的：公安部（网络安全与预防高科技犯罪局） 为实施个人信息安全保护条例公安部个人信息处理影响评估档案，内容如下："}},{"id":"VN-H068-A1","no":1,"noLabel":{"zh":"第 1 条"},"heading":{"en":"有关组织、企业的信息"},"text":{"zh":"企业名称：\n企业营业执照登记住所地：\n企业经常经营地：\n决定成立时间/工商登记成立时间/实际开始经营时间/工商登记编号：\n签发者：签发于月年联系电话：网站：\n负责保护个人信息人员：\n姓名：\n职务：\n联系电话（固定电话和手机）：\n电子邮件："},"partIndex":2},{"id":"VN-H068-A2-d2","no":2,"noLabel":{"zh":"第 2 条"},"heading":{"zh":"评估将个人信息跨境传输的影响"},"text":{"zh":"个人信息处理影响评估档案 1） 2）"},"dupIndex":2,"partIndex":2},{"id":"VN-H068-A3","no":3,"noLabel":{"zh":"第 3 条"},"heading":{"en":"承诺"},"text":{"zh":"（机构、组织、企业名称）特此承诺：对个人数据处理影响评估记录及随附文件的准确性和合法性承担法律责任。\n（签名、注明全名、盖章） 表格编号 05 越南社会主义共和国独立-自由-幸福日 月 年更新档案内容的通知尊敬的：公安部（网络安全与预防高科技犯罪局） 为实施个人信息安全保护条例公安部个人信息处理影响评估档案，内容如下："},"partIndex":2},{"id":"VN-H068-A1-d2","no":1,"noLabel":{"zh":"第 1 条"},"heading":{"en":"有关组织、企业的信息"},"text":{"zh":"企业名称：\n企业营业执照登记住所地：\n企业经常经营地：\n决定成立时间/工商登记成立时间/实际开始经营时间/工商登记编号：\n签发者：签发于月年联系电话：\n网站：\n负责保护个人信息人员：\n姓名：\n职务：\n联系电话（固定电话和手机）：\n电子邮件："},"dupIndex":2,"partIndex":2},{"id":"VN-H068-A2-d3","no":2,"noLabel":{"zh":"第 2 条"},"heading":{"zh":"评估将个人信息跨境传输的影响"},"text":{"zh":"概要及内容变更更新内容：\n更新理由："},"dupIndex":3,"partIndex":2},{"id":"VN-H068-A3-d2","no":3,"noLabel":{"zh":"第 3 条"},"heading":{"en":"附件"},"text":{"zh":"1）\n法通网 法通网 法通网 法通网 法通网 法通网 法通网\n法通网 法通网 法通网 法通网 法通网 法通网 法通网\n法通网 法通网 法通网 法通网 法通网 法通网 法通网\n法通网 法通网 法通网 法通网 法通网 法通网 法通网\n法通网 法通网 法通网 法通网 法通网 法通网 法通网\n法通网 法通网 法通网 法通网 法通网 法通网 法通网\n法通网 法通网 法通网 法通网 法通网 法通网 法通网\n法通网 法通网 法通网 法通网 法通网 法通网 法通网\n法通网 法通网 法通网 法通网 法通网 法通网 法通网\n31\n2）"},"dupIndex":2,"partIndex":2},{"id":"VN-H068-A4-d2","no":4,"noLabel":{"zh":"第 4 条"},"heading":{"en":"承诺"},"text":{"zh":"（机关、组织、商业）郑重承诺：对变更内容及随附文件的准确性和合法性承担法律责任。\n（签名、注明全名、印章） 表格编号 06 越南社会主义共和国独立-自由-幸福日 月 年个人信息跨境转移影响评估档案尊敬的：公安部（网络安全与预防高科技犯罪局） 为实施个人信息安全保护条例公安部个人信息跨境转移影响评估档案，内容如下："},"dupIndex":2,"partIndex":2},{"id":"VN-H068-A2-d4","no":2,"noLabel":{"zh":"第 2 条"},"heading":{"en":"评估将个人信息跨境传输的影响"},"text":{"zh":"1） 2）\n3、承诺 （机关、组织、商业）郑重承诺：对个人信息跨境传输影响评估档案及随附文件的准确性和合法性承担法律责任。\n（签字、写明全名、印章）"},"dupIndex":4,"partIndex":2}],"pack":"vn-p03"};
  FT["VN-H069"] = {"id":"VN-H069","coverage":"full","language":"zh","sourceName":"越南官方发布渠道","sourceUrl":"","fetchedAt":"2026-10-04","articleCount":43,"structureMode":"ARTICLE","title":{"zh":"网络安全法","en":"Law on Cybersecurity 2018","orig":null},"level":"law","status":"active","docNumber":"年份不详","issuingBody":"越南官方发布渠道","completenessNote":"文本未能可靠切分为条文（或原件为目录式排版），按整篇收录，未作改写。","country":"VN","countryName":"越南","layer":"intl","articles":[{"id":"VN-H069-A1","no":1,"noLabel":{"zh":"第1条"},"chapter":{"zh":"第一章"},"text":{"zh":"·39· 越南社会主义共和国网络安全法越南社会主义共和国 网络安全法国会根据 《越南社会主义共和国宪法》 颁布 《网络安全法》 。\n第一章  总 则\n调整范围本法规定了在网络空间维护国家安全、 保障社会治安的活动以及有关机构、 组织、 个人的责任。"}},{"id":"VN-H069-A2","no":2,"noLabel":{"zh":"第2条"},"chapter":{"zh":"第一章"},"text":{"zh":"词语解释在本法中， 下列词语解释如下：\n1. 网络安全， 是网络空间活动不危害国家安全、 社会治安和机构、 组织、 个人合法权益的保障。\n2. 网络安全保护， 是指防范、 发现、 阻止、 处理侵犯网络安全的行为。\n3. 网络空间， 是信息技术基础设施的连接网络， 包括电信网络、 互联网、 计算机网络、 信息系统、 信息处理和控制系统、 数据库； 是人们进行不受空间和时间限制的社会行为的地方。\n4. 国家网络空间， 是由政府建立、 管理和监督的网络空间。\n5. 国家网络空间基础设施， 是指在国家网络空间创建、 传输、 收集、 处理、 存储和交换信息的物理、 技术设施系统， 包括：\n（1） 传输系统， 包括国内传输系统、 国际连接传输系统、 卫星系统以及电信网络服务、 互联网服务、 网络空间增值服务供应商的传输系统。\n（2） 核心服务系统， 包括国家信息分流和导航系统、 国家域名解析系统 （DNS）、 国 家认证系统 （PKI/CA） 和电信网络服务、 互联网服务、 网络空间增值服务供应商的互联网链接、 访问服务供应系统。\n（3） 信息技术服务和应用， 包括在线服务， 连接重要机构、 组织、 经济和金融集团的 *  译者： 陶文文， 北京外国语大学亚洲学院博士生。\n* “一带一路”法律查明     第 3 卷 ·40· 管理和调度服务网络的信息技术应用， 国家数据库。\n在线服务包括电子政务、 电子商务、 网站、 在线论坛、 社交网络、 博客。\n（4） 智慧城市的信息技术基础设施、 物联网、 虚拟系统、 云计算、 大数据系统、 快速数据系统和人工智能系统。\n6. 国际网络连接端口， 是指越南与其他国家、 地区之间进行网络信号传输和接收的地方。\n7. 网络犯罪， 是利用网络空间、 信息技术或电子手段实施 《刑法》 所规定的犯罪行为。\n8. 网络攻击， 是利用网络空间、 信息技术或电子手段破坏、 中断电信网络、 互联网、 计算机网络， 信息系统、 信息处理和控制系统、 数据库、 电子手段运行的行为。\n9. 网络恐怖主义， 是利用网络空间、 信息技术或电子手段进行恐怖主义、 恐怖主义融资的行为。\n10. 网络间谍行为， 是故意绕过警告、 访问码、 密码、 防火墙， 利用他人的管理权限或其他方式， 非法侵占、 收集电信网络、 互联网、 计算机网络、 信息系统、 信息管理和控制系统、 数据库和机构、 组织、 个人电子手段上的信息和信息资源的行为。\n11. 数字账户， 是用于认证、 验证、 授权使用网络空间应用程序和服务的信息。\n12. 网络安全威胁危机， 是网络空间出现侵犯国家安全、 严重危害社会治安以及机构、 组织、 个人合法权益的威胁信号的情况。\n13. 网络安全事故， 是在网络空间发生的侵犯国家安全、 社会治安以及机构、 组织、 个人合法权益的突发事件。\n14. 网络安全危险情况， 是在网络空间发生的严重侵犯国家安全和对社会治安以及机构、 组织、 个人合法权益造成特别严重危害的事件。"}},{"id":"VN-H069-A3","no":3,"noLabel":{"zh":"第3条"},"chapter":{"zh":"第一章"},"text":{"zh":"国家网络安全政策\n1. 优先保护国防、 安全、 经济社会发展、 科学技术、 对外网络的安全。\n2. 建设健康的网络空间， 不危害国家安全、 社会治安， 不损害机构、 组织、 个人的合法权益。\n3. 优先打造网络安全保护专职力量； 增强网络安全保护力量， 提高组织、 个人参与网络安全保护的能力； 优先投资科技研发， 保障网络安全。\n4. 鼓励组织、 个人参与网络安全污保护、 处理网络安全威胁危机， 并为组织、 个人参与网络安全保护、 处理网络安全威胁危机创造条件； 研发网络安全保护技术、 产品、 服务和应用程序； 配合职能部门进行网络安全保护。\n5. 加强网络安全国际合作。\n·41· 越南社会主义共和国网络安全法"}},{"id":"VN-H069-A4","no":4,"noLabel":{"zh":"第4条"},"chapter":{"zh":"第一章"},"text":{"zh":"网络安全保护原则\n1. 遵守宪法和法律， 保障国家利益以及机构、 组织、 个人的合法权益。\n2. 由越南共产党领导、 国家统一管理， 调动政治系统和全民的综合力量， 发挥网络安全保护专职力量的核心作用。\n3. 将保护网络安全和国家安全重要信息系统的任务与发展经济社会、 保障人权和公民权以及为机构、 组织、 个人的网络空间活动创造条件的任务紧密结合起来。\n4. 积极防范、 发现、 制止、 打击、 阻止一切利用网络空间侵犯国家安全、 社会治安以及机构、 组织、 个人合法权益的活动， 随时做好制止网络安全威胁危机的准备。\n5. 开展国家网络基础设施的网络安全保护活动， 采取措施保护国家安全重要信息系统。\n6. 国家安全重要信息系统在投入运行和使用前， 应当审核、 认定其满足网络安全条件； 在使用过程中， 应当经常检查和监督网络安全并及时应对、 解决网络安全事故。\n7. 必须及时、 严正处理一切违反网络安全法律的行为。"}},{"id":"VN-H069-A5","no":5,"noLabel":{"zh":"第5条"},"chapter":{"zh":"第一章"},"text":{"zh":"网络安全保护措施\n1. 网络安全保护措施包括：\n（1） 网络安全评估。\n（2） 网络安全条件评估。\n（3） 网络安全检查。\n（4） 网络安全监控。\n（5） 应对、 解决网络安全事故。\n（6） 网络安全保护斗争。\n（7） 阻止和要求暂停、 停止提供网络信息， 依法停止、 暂停建立、 提供、 使用电信网络、 互联网和生产、 使用无线电发射机、 收发机的活动。\n（8） 要求删除、 访问删除网络空间中侵犯国家安全、 社会治安以及机构、 组织、 个人合法权益的非法信息或虚假信息。\n（9） 收集与侵犯国家安全、 社会治安以及机构、 组织和个人网络合法权益活动有关的电子数据。\n（10） 封锁、 限制信息系统的运行； 依法停止、 暂停信息系统运行， 或要求信息系统停止运行、 撤销域名。\n（11） 根据 《刑事诉讼法》 的规定立案、 调查、 起诉和审判。\n（12） 国家安全法、 行政处罚法所规定的其他措施。\n“一带一路”法律查明     第 3 卷 ·42·\n2. 采取网络安全保护措施的程序和手续由政府规定， 但本条第 1 款 第（11）项 、第\n（12） 项规定的措施除外。"}},{"id":"VN-H069-A6","no":6,"noLabel":{"zh":"第6条"},"chapter":{"zh":"第一章"},"text":{"zh":"国家网络空间保护国家采取措施保护国家网络空间， 防范、 处理在网络空间侵害国家安全、 社会治安以及机构、 组织、 个人合法权益的行为。"}},{"id":"VN-H069-A7","no":7,"noLabel":{"zh":"第7条"},"chapter":{"zh":"第一章"},"text":{"zh":"网络安全国际合作\n1. 网络安全国际合作在尊重独立、 主权和领土完整、 互不干涉内政、 平等互利的基础上开展。\n2. 网络安全国际合作的内容包括：\n（1） 研究和分析网络安全趋势；\n（2） 建立促进越南组织、 个人与外国组织、 个人以及国际组织在网络安全活动方面的合作机制和政策；\n（3） 分享信息和经验， 提供网络安全保护的培训、 设备和技术支持；\n（4） 防范、 打击网络犯罪和侵犯网络安全的行为， 防止网络安全威胁危机；\n（5） 网络安全人力资源的咨询、 培训和开发；\n（6） 组织有关网络安全的国际会议、 研讨会和论坛；\n（7） 签署和实施有关网络安全的国际条约和国际协议；\n（8） 实施有关网络安全的国际合作项目和方案；\n（9） 其他与网络安全有关的国际合作活动。\n3. 公安部向政府负责， 主持并配合开展网络安全国际合作， 但国防部的国际合作活动除外。\n国防部向政府负责， 在其管理范围内开展网络安全国际合作。\n外交部有责任配合公安部、 国防部进行网络安全国际合作活动。\n涉及多个部委职责的网络安全国际合作的情形由政府决定。\n4. 其他部委和地方在开展网络安全国际合作活动前， 必须有公安部的书面参加意见， 但国防部的国际合作活动除外。"}},{"id":"VN-H069-A8","no":8,"noLabel":{"zh":"第8条"},"chapter":{"zh":"第一章"},"text":{"zh":"网络安全禁止行为\n1. 禁止利用网络空间进行下列行为：\n（1） 本法第18 条第 1 款规定的行为；\n（2） 组织、 运作、 勾结、 教唆、 贿赂、 欺骗、 引诱、 培训、 训练人员反对越南社会主义共和国的；\n·43· 越南社会主义共和国网络安全法\n（3） 歪曲历史、 否认革命成就、 破坏民族大团结、 冒犯宗教、 歧视性别和种族的；\n（4） 发布不实信息引起群众恐慌， 损害经济社会活动， 妨碍国家机构或公务人员的活动， 侵犯其他机构、 组织、 个人合法权益的；\n（5） 进行卖淫、 社会弊端、 人口贩卖活动， 发布淫秽、 颓废、 犯罪信息， 破坏民族淳风美俗、 社会公德、 社会健康的；\n（6） 教唆、 引诱、 煽动他人犯罪的。\n2. 进行网络攻击、 网络恐怖主义、 网络间谍、 网络犯罪， 造成国家安全重要信息系统发生事故、 中断、 停滞、 瘫痪、 故障和被攻击、 被入侵、 被侵占控制权、 被破坏。\n3. 生产、 启用工具、 手段、 软件或用行动阻碍、 扰乱电信网络、 互联网、 计算机网络、 信息系统、 信息处理和控制系统、 电子手段的运行， 传播损害电信网络、 互联网、 计算机网络、 信息系统、 信息处理和控制系统、 电子手段运行的计算机程序， 非法入侵他人的电信网络、 计算机网络、 信息系统、 信息处理和控制系统、 数据库和电子手段。\n4. 对抗或者阻碍网络安全保护专职力量的活动， 非法攻击、 解除网络安全保护措施使其失效。\n5. 利用或滥用网络安全保护活动侵犯国家主权、 利益、 安全、 社会治安以及机构、 组织、 个人的合法权益。\n6. 其他违反本法规定的行为。"}},{"id":"VN-H069-A9","no":9,"noLabel":{"zh":"第9条"},"chapter":{"zh":"第二章"},"text":{"zh":"网络安全违法行为的处理有违反本法规定行为的， 根据违法行为的性质和情节轻重， 依法予以纪律处分、 行政处罚或者追究刑事责任， 如造成损失的则依法赔偿。\n第二章  国家安全重要信息系统的网络安全保护"}},{"id":"VN-H069-A10","no":10,"noLabel":{"zh":"第10条"},"chapter":{"zh":"第二章"},"text":{"zh":"国家安全重要信息系统\n1. 国家安全重要信息系统是指发生事故、 入侵、 侵占控制权、 故障、 中断、 停止、 瘫痪、 攻击或破坏时将严重侵害网络安全的信息系统。\n2. 国家安全重要信息系统包括：\n（1） 军事、 安全、 外交和机要信息系统；\n（2） 存储和处理国家机密信息的信息系统；\n（3） 用于存储、 保存具有特别重要价值的实物、 材料的信息系统；\n（4） 用于保存对人类和生态环境特别危险的物资和物质的信息系统；\n（5） 用于保存、 制造、 管理对国家安全特别重要的物质基础的信息系统；\n“一带一路”法律查明     第 3 卷 ·44·\n（6） 为中央机构、 组织的活动提供服务的重要信息系统；\n（7） 属于能源、 金融、 银行、 电信、 交通运输、 自然资源与环境、 化工、 医疗、 文化和新闻领域的国家信息系统；\n（8） 国家安全重要相关工程、 国家安全重要目标中的自动化控制和监测系统。\n3. 政府总理颁布和修改、 补充国家安全重要信息系统名录。\n4. 政府规定公安部、 国防部、 信息通信部、 政府机要局、 各职能部委在审定、 评估、 检查、 监督、 应对和解决国家安全重要信息系统事故时进行配合。"}},{"id":"VN-H069-A11","no":11,"noLabel":{"zh":"第11条"},"chapter":{"zh":"第二章"},"text":{"zh":"国家安全重要信息系统的网络安全审定\n1. 网络安全审定， 是指对与网络安全有关的内容进行审查和评估， 为建立或升级信息系统的决定提供依据的活动。\n2. 国家安全重要信息系统的网络安全审定对象包括：\n（1） 信息系统投资建设项目审批前的前期可行性研究报告、 设计施工档案；\n（2） 审批前的信息系统升级项目。\n3. 国家安全重要信息系统的网络安全审定内容包括：\n（1） 设计应当遵守网络安全的法规和条件；\n（2） 符合保护、 应对和解决事故的方案以及网络安全保护的人员安排。\n4. 国家安全重要信息系统的网络安全审定权限规定如下：\n（1） 公安部网络安全保护专职力量对国家安全重要信息系统进行网络安全审定， 但本款第 （2）项 、 第（3） 项规定的情况除外；\n（2） 国防部网络安全保护专职力量对军事信息系统进行网络安全审定；\n（3） 政府机要局对其下属的机要信息系统进行网络安全审定。"}},{"id":"VN-H069-A12","no":12,"noLabel":{"zh":"第12条"},"chapter":{"zh":"第二章"},"text":{"zh":"国家安全重要信息系统的网络安全条件评估\n1. 网络安全条件评估， 是指在信息系统投入运行和使用前， 审查其是否满足网络安全条件的活动。\n2. 国家安全重要信息系统应当满足下列条件：\n（1） 具备保护网络安全的规定、 规程和方案， 系统运行、 管理人员；\n（2） 能够保障系统组件的设备、 硬件、 软件的网络安全；\n（3） 具备监控和保护网络安全的技术措施， 自动控制和监控系统、 物联网、 虚拟系统、 云计算、 大数据系统、 快速数据系统、 人工智能系统的保护措施；\n（4） 具备物理安全的保护措施， 包括特殊隔离、 防数据泄露、 防接收、 出入监管。\n·45· 越南社会主义共和国网络安全法\n3. 国家安全重要信息系统的网络安全条件评估权限规定如下：\n（1） 公安部网络安全保护专职力量对国家安全重要信息系统的网络安全条件进行评估、 认定， 但本款第 （2）项 、 第（3） 项规定的情况除外；\n（2） 国防部网络安全保护专职力量对军事信息系统的网络安全条件进行评估、 认定；\n（3） 政府机要局对其下属的机要信息系统的网络安全条件进行评估、 认定。\n4. 国家安全重要信息系统经认定满足网络安全条件后， 方可投入运行和使用。\n5. 政府对本条第 2 款作详细规定。"}},{"id":"VN-H069-A13","no":13,"noLabel":{"zh":"第13条"},"chapter":{"zh":"第二章"},"text":{"zh":"国家安全重要信息系统的网络安全检查\n1. 网络安全检查， 是指确定信息系统、 信息系统基础设施或信息系统中存储、 处理和传输的信息的网络安全现状， 以预防、 发现、 处理网络安全威胁危机， 并提出保障信息系统正常运行的方案、 措施的活动。\n2. 国家安全重要信息系统的网络安全检查应当在下列情况下进行：\n（1） 在信息系统中启用电子手段和网络信息安全服务时；\n（2） 当信息系统的现状发生变化时；\n（3） 年度定期检查；\n（4） 发生网络安全事故或侵犯网络安全行为时的突发检查， 应国家对网络安全的管理要求， 网络安全保护专职力量建议排除保密漏洞和缺口的期限届满时。\n3. 国家安全重要信息系统的网络安全检查对象包括：\n（1） 信息系统中使用的硬件、 软件和数字化设备系统；\n（2） 网络安全保护的规定和措施；\n（3） 信息系统中存储、 处理和传输的信息；\n（4） 信息系统主管对网络安全事故的应对和解决方案；\n（5） 保护国家机密和防范、 打击国家机密经技术渠道泄露、 遗失的措施；\n（6） 从事网络安全保护的人员。\n4. 国家安全重要信息系统主管在本条第 2 款 第（1）项 、第（2）项 、第（3） 项规定的情况下， 有责任对其管理的信息系统的网络安全进行检查； 每年10 月前将检查结果以书面形式通知公安部网络安全保护专职力量， 或将对军事信息系统的检查结果通知国防部网络安全保护专职力量。\n5. 对国家安全重要信息系统的网络安全突发检查， 规定如下：\n（1） 在检查前发生网络安全事故、 侵犯网络安全行为的， 网络安全保护专职力量应至少提前 12 小时以书面形式告知信息系统主管； 国家对网络安全有管理要求， 或网络安全 “一带一路”法律查明     第 3 卷 ·46· 保护专职力量建议排除保密漏洞和缺口的期限届满时， 应至少提前 72 小时以书面形式告知信息系统主管。\n（2） 网络安全保护专职力量应在自检查完成之日起 30 日内通报检查结果， 发现保密漏洞和缺口的， 则应向信息系统主管提出要求， 或应信息系统主管建议指导或参与解决。\n（3） 公安部网络安全保护专职力量对国家安全重要信息系统进行突发检查， 但由国防部管理的军事信息系统、 政府机要局下属的机要信息系统及其为保护国家机密提供的密码产品除外。\n国防部网络安全保护专职力量对军事信息系统进行网络安全突发检查。\n政府机要局对其下属的机要信息系统及其为保护国家机密所提供的密码产品进行网络安全突发检查。\n（4） 国家安全重要信息系统主管有责任配合网络安全保护专职力量进行网络安全突发检查。\n6. 网络安全检查结果依法保密。"}},{"id":"VN-H069-A14","no":14,"noLabel":{"zh":"第14条"},"chapter":{"zh":"第二章"},"text":{"zh":"国家安全重要信息系统的网络安全监管\n1. 网络安全监管， 是指收集和分析情况， 确定网络安全威胁、 网络安全事故、 保密漏洞和缺口、 恶意代码、 恶意硬件等情况， 以进行警报、 解决和处理的活动。\n2. 国家安全重要信息系统主管主持、 配合职权网络安全保护专职力量对管理范围内的信息系统进行经常性的网络安全监管； 建立网络安全威胁、 网络安全事故、 保密漏洞和缺口、 恶意代码、 恶意硬件的自我预警和预警接收机制， 并提出紧急应对和解决方案。\n3. 网络安全保护专职力量对其管理的国家重要安全信息系统进行网络安全监管； 对国家安全重要信息系统发生的网络安全威胁危机、 网络安全事故、 保密漏洞和缺口、 恶意代码、 恶意硬件进行警报并配合信息系统主管解决、 处理风险。"}},{"id":"VN-H069-A15","no":15,"noLabel":{"zh":"第15条"},"chapter":{"zh":"第三章"},"text":{"zh":"国家安全重要信息系统网络安全事故的应对和解决\n1. 国家安全重要信息系统网络安全事故的应对和解决活动包括：\n（1） 发现和确定网络安全事故；\n（2） 保护现场， 收集证据；\n（3） 封锁、 控制网络安全事故的发生范围， 限制网络安全事故造成的损失；\n（4） 确定救急目标、 对象和范围；\n（5） 核实、 分析、 评估网络安全事故并进行分类；\n（6） 制定网络安全事故的应对和解决方案；\n（7） 核实原因， 追溯根源；\n·47· 越南社会主义共和国网络安全法\n（8） 依法查处。\n2. 国家安全重要信息系统主管为其管理的信息系统制定网络安全事故的应对和解决方案； 在网络安全事故发生时实施方案并及时向职权网络安全保护专职力量报告。\n3. 国家安全重要信息系统网络安全事故的应对和解决， 应按如下规定调度：\n（1） 公安部网络安全保护专职力量主持、 调度对国家安全重要信息系统网络安全事故的应对和解决， 但本款第 （2）项 、第（3） 项规定的情况除外； 应要求参加应对和解决国家安全重要信息系统的网络安全事故； 发现网络攻击、 网络安全事故时通知信息系统主管。\n（2） 国防部网络安全保护专职力量主持、 调度对军事信息系统网络安全事故的应对和解决。\n（3） 政府机要局主持、 调度对其下属机要信息系统网络安全事故的应对和解决。\n4. 机构、 组织和个人有责任应主持、 调配单位的要求， 参与应对和解决国家安全重要信息系统的网络安全事故。\n第三章  侵犯网络安全行为的预防和处理"}},{"id":"VN-H069-A16","no":16,"noLabel":{"zh":"第16条"},"chapter":{"zh":"第三章"},"text":{"zh":"预防和处理含有反越南社会主义共和国宣传， 煽动骚乱、 破坏安全、 扰乱公共秩序， 侮辱、 诬蔑， 违反经济管理秩序内容的网络空间信息\n1. 含有反越南社会主义共和国宣传内容的网络空间信息包括：\n（1） 宣传歪曲、 诽谤人民政府的；\n（2） 心理战， 煽动不同民族、 宗教和各国人民之间的侵略、 分裂和仇恨战争的；\n（3） 冒犯民族、 国旗、 国徽、 国歌、 伟人、 领袖、 名人和民族英雄的。\n2. 含有煽动骚乱、 破坏安全、 扰乱公共秩序的网络空间信息包括：\n（1） 号召、 动员、 教唆、 威胁、 分裂、 进行武装活动或使用暴力反对人民政府的；\n（2） 号召、 动员、 教唆、 威胁、 引诱群众聚众闹事， 反抗公务人员、 阻挠机构和组织活动， 造成治安不稳定的。\n3. 含有侮辱、 污蔑内容的网络空间信息包括：\n（1） 严重侵犯他人名誉、 信誉和人格的；\n（2） 侵犯其他机构、 组织和个人的名誉、 信誉、 人格或损害其合法权益的伪造、 虚假信息。\n4. 含有违反经济管理秩序内容的网络空间信息包括：\n（1） 关于产品、 货物、 货币、 债券、 证券、 公债、 支票和其他有价票据的伪造、 虚假 “一带一路”法律查明     第 3 卷 ·48· 信息；\n（2） 金融、 银行、 电子商务、 电子支付、 货币交易、 融资、 多层次营销、 证券等领域的伪造、 虚假信息。\n5. 含有引起群众恐慌， 损害经济社会活动， 妨碍国家机构或公务人员的活动， 侵犯其他机构、 组织和个人合法权益的网络空间信息。\n6. 信息系统主管有责任应网络安全保护专职力量的要求， 采取管理和技术措施预防、 发现、 阻止、 删除在其管理范围内含有本条第1 款 、第2 款 、第3 款 、第4 款 、第5 款规定内容的信息。\n7. 网络安全保护专职力量和职权机构采取本法第 5 条第 1 款 第（7）项 、第（8）项 、 第（10） 项规定的措施处理含有本条第1 款 、第2 款 、第3 款 、第4 款 、第5 款规定内容的网络空间信息。\n8. 电信网络、 互联网服务、 网络空间增值服务的供应商和信息系统主管， 有责任配合职能机构处理含有本条第 1 款 、第2 款 、第3 款 、第4 款 、第5 款规定内容的网络空间信息。\n9. 组织和个人在网络空间编撰、 发布、 散布含有本条第 1 款 、第2 款 、第3 款 、第4 款 、第5 款规定内容的信息的， 应当按网络安全保护专职力量要求清除信息， 并依法承担责任。"}},{"id":"VN-H069-A17","no":17,"noLabel":{"zh":"第17条"},"chapter":{"zh":"第三章"},"text":{"zh":"防范和打击网络间谍， 保护属于国家机密、 工作机密、 商业机密、 个人隐私、 家庭和私人生活隐私的网络空间信息\n1. 网络间谍行为， 侵犯网络空间的国家机密、 工作机密、 商业机密、 个人隐私、 家庭和私人生活隐私的行为， 包括：\n（1） 侵占、 交易、 扣留、 故意泄露国家机密、 工作机密、 商业机密、 个人隐私、 家庭和私人生活隐私信息， 影响机构、 组织和个人的名誉、 信誉、 人格和合法权益的；\n（2） 故意删除、 损坏、 遗失、 更改在网络空间上传输和存储的国家机密、 工作机密、 商业机密、 个人隐私、 家庭和私人生活隐私信息的；\n（3） 故意更改、 取消或停用为保护国家机密、 工作机密、 商业机密、 个人隐私、 家庭和私人生活隐私信息而制定和使用的技术措施的；\n（4） 违反法律规定在网络空间上传国家机密、 工作机密、 商业机密、 个人隐私、 家庭和私人生活隐私信息的；\n（5） 故意对谈话内容进行非法窃听、 录音和录像的；\n（6） 故意侵犯国家机密、 工作机密、 商业机密、 个人隐私、 家庭和私人生活隐私的其他行为。\n·49· 越南社会主义共和国网络安全法\n2. 信息系统主管具有以下职责：\n（1） 检查网络安全， 发现、 清除恶意代码和恶意硬件， 解决保密漏洞和缺口； 发现、 阻止、 处理非法入侵活动或威胁网络安全的其他危机。\n（2） 开展管理和技术措施， 预防、 发现和制止在信息系统上进行网络间谍、 侵犯国家机密、 工作机密、 商业机密、 个人隐私、 家庭和私人生活隐私的行为， 并及时删除与该行为有关的信息。\n（3） 配合、 执行网络安全保护专职力量对防范、 打击网络间谍、 保护信息系统上的国家机密、 工作机密、 商业机密、 个人隐私、 家庭和私人生活隐私信息的要求。\n3. 编写、 储存国家机密信息、 文件的机构， 有责任根据国家机密保护法的规定， 保护在计算机和其他设备上编写、 存储或在网络空间交换的国家机密。\n4. 除本条第 5 款 、第6 款的规定外， 公安部具有以下职责：\n（1） 对国家安全重要信息系统进行网络安全检查， 发现、 清除恶意代码和恶意硬件， 修复保密漏洞和缺口， 发现、 阻止和处理非法入侵活动；\n（2） 通信设备、 产品、 服务和数字设备、 电子设备在国家安全重要信息系统中启用前， 应当对其进行网络安全检查；\n（3） 对国家安全重要信息系统进行网络安全监管， 发现和处理非法收集国家机密信息的活动；\n（4） 发现和处理在网络空间非法发布、 存储和交换国家机密信息和文件的行为；\n（5） 根据职能和分配的任务参加研究、 生产存储和传输国家机密信息、 文件的产品和网络空间信息编码产品；\n（6） 监察、 检查国家机构对网络空间国家机密的保护工作和国家安全重要信息系统主管的网络安全保护工作；\n（7） 根据本法第30 条第 2 款的规定， 组织培训、 训练， 以提高网络安全保护专职力量对于保护网络空间国家机密、 防范和打击网络攻击、 保护网络安全的意识和知识。\n5. 国防部有责任执行本条第 4 款 第（1）项 、第（2）项 、第（3）项 、第（4）项 、第（5） 项 、第 （6） 项对军事信息系统规定的内容。\n6. 政府机要局有责任组织执行法律规定， 对在网络空间上存储、 传输的国家机密信息进行密码保护。"}},{"id":"VN-H069-A18","no":18,"noLabel":{"zh":"第18条"},"chapter":{"zh":"第三章"},"text":{"zh":"防范和打击利用网络空间、 信息技术和电子手段违反国家安全法、 社会治安法的行为\n1. 利用网络空间、 信息技术、 电子手段违反国家安全法、 社会治安法的行为包括：\n“一带一路”法律查明     第 3 卷 ·50·\n（1） 在网络空间发布、 散布含有本法第16 条第 1 款 、第2 款 、第3 款 、第4 款 、第5 款规定的内容和第 17 条规定行为的信息的；\n（2） 侵占网络空间财产， 通过互联网组织赌博、 参与赌博， 盗窃互联网国际电信费用， 侵犯网络空间版权和知识产权的；\n（3） 伪造机构、 组织和个人网站， 非法伪造、 流通、 窃取、 交易、 收集、 交换他人信用卡、 银行账户信息， 非法发行、 提供、 使用支付手段的；\n（4） 宣传、 推广、 销售法律规定的禁用商品和服务的；\n（5） 引导他人实施违法行为的；\n（6） 利用网络空间、 信息技术或电子手段违反国家安全法律、 社会治安的其他行为。\n2. 网络安全保护专职力量有责任防范和打击利用网络空间、 信息技术和电子手段违反国家安全法、 社会治安法的行为。"}},{"id":"VN-H069-A19","no":19,"noLabel":{"zh":"第19条"},"chapter":{"zh":"第三章"},"text":{"zh":"防范和打击网络攻击\n1. 网络攻击行为及其相关行为包括：\n（1） 散布危害电信网络、 互联网、 计算机网络、 信息系统、 信息处理和控制系统、 数据库和电子手段的计算机程序的；\n（2） 非法阻碍、 扰乱、 中断、 终止、 阻止电信网络、 互联网、 计算机网络、 信息系统、 信息处理和控制系统、 电子手段的数据传输， 致其故障的；\n（3） 入侵、 破坏、 侵占在电信网络、 互联网、 计算机网络、 信息处理和控制系统、 数据库、 电子手段上存储和传输的数据的；\n（4） 入侵、 制造或开发保密漏洞、 缺口和系统服务以侵占信息、 获取非法利益的；\n（5） 生产、 买卖、 交换、 赠送具有对电信网络、 互联网、 计算机网络、 信息系统、 信息处理和控制系统、 数据库和电子手段进行网络攻击性能的工具、 设备和软件， 以用于非法目的的；\n（6） 影响电信网络、 互联网、 计算机网络、 信息系统、 信息处理和控制系统、 数据库和电子手段正常运行的其他行为。\n2. 信息系统主管有责任对其管理的信息系统采取技术措施， 防范和阻止本条第 1 款第（1）项 、 第（2）项 、 第（3）项 、 第（4）项 、 第（6） 项规定的行为。\n3. 发生侵犯或威胁侵犯国家主权、 利益和安全， 严重破坏社会治安的网络攻击时， 网络安全保护专职力量应当主持、 配合信息系统主管、 有关组织和个人， 采取措施确定网络攻击来源、 收集证据； 要求电信网络、 互联网和网络空间增值服务供应商拦截、 过滤信息， 制止、 排除网络攻击， 并充分地、 及时地提供相关信息和文件。\n·51· 越南社会主义共和国网络安全法\n4. 防范和打击网络攻击的责任规定如下：\n（1） 公安部主持、 配合有关部委预防、 发现、 处理本条第1 款所规定的侵犯或威胁侵犯国家主权、 利益和安全， 对全国社会治安造成严重危害的行为， 但本款第 （2）项 、第\n（3） 项规定的情况除外；\n（2） 国防部主持、 配合有关部委预防、 发现和处理本条第1 款对军事信息系统规定的行为；\n（3） 政府机要局主持、 配合有关部委预防、 发现和处理本条第1 款对政府机要局信息系统规定的行为。"}},{"id":"VN-H069-A20","no":20,"noLabel":{"zh":"第20条"},"chapter":{"zh":"第三章"},"text":{"zh":"预防和打击网络恐怖主义\n1. 国家职权机构有责任依照本法、 《网络信息安全法》 第29 条、 反恐怖主义法律的规定采取措施处理网络恐怖主义。\n2. 信息系统主管应当经常核查、 检查其管理的信息系统， 以消除网络恐怖主义危机。\n3. 机构、 组织和个人发现网络恐怖主义迹象和行为时， 应当及时通知网络安全保护专职力量。通知信息接收机构有责任充分接收有关网络恐怖主义的信息， 并及时通知网络安全保护专职力量。\n4. 公安部主持、 配合有关部委， 预防、 打击网络恐怖主义， 采取措施取缔网络恐怖主义源头， 处理网络恐怖主义， 最大限度地降低其对信息系统造成的后果， 但本条第5 款、 第 6 款规定的情况除外。\n5. 国防部主持、 配合有关部委， 预防、 打击网络恐怖主义， 采取措施处理针对军事信息系统的网络恐怖主义。\n6. 政府机要局主持、 配合有关部委， 预防和打击网络恐怖主义， 采取措施处理针对其下属机密信息系统的网络恐怖主义。"}},{"id":"VN-H069-A21","no":21,"noLabel":{"zh":"第21条"},"chapter":{"zh":"第三章"},"text":{"zh":"网络安全危险情况的防范和处理\n1. 网络安全的危险情况包括：\n（1） 网络空间出现煽动性信息， 存在引发骚乱、 扰乱治安及恐怖主义的风险；\n（2） 攻击国家安全重要信息系统；\n（3） 大规模、 高强度攻击多个信息系统；\n（4） 意图破坏国家安全重要项目和重要目标的网络攻击；\n（5） 严重侵犯国家主权、 利益和安全， 严重损害社会治安以及机构、 组织、 个人合法权益的网络攻击。\n“一带一路”法律查明     第 3 卷 ·52·\n2. 防范网络安全危险情况的责任规定如下：\n（1） 网络安全保护专职力量配合国家安全重要信息系统主管开展专业技术解决方案， 以预防、 发现和处理网络安全危险情况；\n（2） 电信、 互联网、 信息技术企业和电信网络、 互联网、 网络空间上增值服务供应商以及有关机构、 组织、 个人， 有责任配合公安部网络安全保护专职力量预防、 发现和处理网络安全危险情况。\n3. 处理网络安全危险情况的措施包括：\n（1） 立即开展网络安全的防范和紧急应对方案， 阻止、 消除或减轻网络安全危险情况造成的损害；\n（2） 通知有关机构、 组织和个人；\n（3） 收集相关信息， 持续跟踪、 监管网络安全的危险情况；\n（4） 分析和评估信息， 预测网络安全危险情况造成损害的可能性、 影响范围和程度；\n（5） 停止提供具体区域的网络信息或断开国际网络连接端口；\n（6） 部署力量和手段制止、 消除网络安全危险情况；\n（7） 国家安全法规定的其他措施。\n4. 处理网络安全危险情况的规定如下：\n（1） 发现网络安全危险情况时， 机构、 组织和个人应当及时通知网络安全保护专职力量， 并立即采取本条第3 款 第（1）项 、 第（2） 项规定的措施。\n（2） 政府总理审查、 决定， 或授权公安部部长审查、 决定、 处理全国或各地或具体目标的网络安全危险情况。\n政府总理审查、 决定， 或授权国防部部长审查、 决定和处理军事信息系统和政府机要局下属的机密信息系统的网络安全危险情况。\n（3） 网络安全保护专职力量主持、 配合有关机构、 组织和个人采取本条第3 款规定的措施处理网络安全危险情况。\n（4） 有关机构、 组织和个人有责任配合网络安全保护专职力量采取措施阻止和处理网络安全危险情况。"}},{"id":"VN-H069-A22","no":22,"noLabel":{"zh":"第22条"},"chapter":{"zh":"第四章"},"text":{"zh":"网络安全保护斗争\n1. 网络安全保护斗争， 是指网络安全保护专职力量在网络空间开展维护国家安全、 社会治安的有组织的活动。\n2. 网络安全保护斗争的内容包括：\n（1） 掌握国家安全保护活动的相关情况；\n·53· 越南社会主义共和国网络安全法\n（2） 防范和打击对国家安全重要信息系统的攻击， 保护其稳定运行；\n（3） 取缔、 限制利用网络空间危害国家安全或严重危害社会治安的活动；\n（4） 为保护国家安全、 保障社会治安， 主动进攻、 停用网络空间目标。\n3. 公安部主持、 配合有关部委实行网络安全保护斗争。\n第四章  网络安全保护活动"}},{"id":"VN-H069-A23","no":23,"noLabel":{"zh":"第23条"},"chapter":{"zh":"第四章"},"text":{"zh":"在中央和地方国家机构、 政治组织开展网络安全保护活动\n1. 开展网络安全保护活动的内容包括：\n（1） 建立和完善使用内部计算机网络和连接互联网的计算机网络的规章制度， 信息系统网络安全的保障方案， 网络安全事故的应对和解决方案；\n（2） 采用和开展方案、 措施和技术， 保护管理范围内的信息系统和在信息系统中存储、 编写、 传输的信息和文件的网络安全；\n（3） 为干部、 公务员、 事业单位人员、 劳动者组织网络安全知识培训， 提高网络安全保护专职力量的网络安全保护能力；\n（4） 保护公共服务供应， 提供、 交换、 收集机构、 组织和个人信息， 内部和与其他机构共享信息等活动， 以及政府规定的其他活动的网络安全；\n（5） 投资、 建设符合保障信息系统网络安全保护活动开展条件的物质基础设施；\n（6） 检查信息系统的网络安全， 防范和打击网络安全违法行为， 应对和排除网络安全事故。\n2. 机构、 组织负责人有责任在其管理范围内开展网络安全保护活动。"}},{"id":"VN-H069-A24","no":24,"noLabel":{"zh":"第24条"},"chapter":{"zh":"第四章"},"text":{"zh":"国家安全重要信息系统名录以外的机构、 组织的信息系统的网络安全检查\n1. 在以下情况下， 对未列入国家安全重要信息系统名录的机构、 组织的信息系统进行网络安全检查：\n（1） 存在侵犯国家安全或严重危害社会治安等违反网络安全法的行为的；\n（2） 应信息系统主管的建议。\n2. 网络安全检查的对象包括：\n（1） 信息系统中使用的硬件、 软件和数字设备系统；\n（2） 信息系统中存储、 处理和传输的信息；\n（3） 保护国家机密和防范、 打击通过技术手段泄露和遗失国家机密的措施。\n3. 信息系统主管在发现其管理的信息系统存在网络安全违法行为时， 有责任通知公 “一带一路”法律查明     第 3 卷 ·54· 安部网络安全保护专职力量。\n4. 公安部网络安全保护专职力量对本条第 1 款规定的机构、 组织的信息系统进行网络安全检查。\n5. 网络安全保护专职力量在进行检查前， 应至少提前12 小时以书面形式通知信息系统主管。\n网络安全保护专职力量应当在自检查完成之日起 30 日内通报检查结果， 如发现保密漏洞和缺口， 则应当向信息系统主管提出要求， 应信息系统主管的建议指导或参与整改。\n6. 网络安全检查结果依法保密。\n7. 本条规定的网络安全检查的程序和手续， 由政府规定。"}},{"id":"VN-H069-A25","no":25,"noLabel":{"zh":"第25条"},"chapter":{"zh":"第四章"},"text":{"zh":"国家网络空间基础设施和国际网络接口的网络安全保护\n1. 国家网络空间基础设施和国际网络接口的网络安全保护， 应当确保网络安全保护要求与经济社会发展要求的紧密结合； 鼓励在越南境内设立国际接口； 鼓励组织、 个人参与投资建设国家网络空间基础设施。\n2. 管理和开发国家网络空间基础设施、 国际网络接口的机构、 组织和个人具有以下职责：\n（1） 保护其管理的网络安全； 接受国家职权机构对网络安全保护的管理、 监督、 检查， 并执行其要求。\n（2） 根据建议， 为国家职权机构执行网络安全保护任务创造条件并采取必要的专业措施。"}},{"id":"VN-H069-A26","no":26,"noLabel":{"zh":"第26条"},"chapter":{"zh":"第四章"},"text":{"zh":"保障网络空间的信息安全\n1. 机构、 组织和个人的网站、 电子门户或社交网络官网不得提供、 发布和传播含有本法第 16 条第 1 款 、第2 款 、第3 款 、第4 款 、第5 款规定内容及其他含有侵犯国家安全内容的信息。\n2. 在越南提供电信网络、 互联网、 网络空间增值服务的国内外企业具有以下责任：\n（1） 在用户注册数字账户时验证信息； 对用户信息和账户保密； 应书面要求， 向公安部网络安全保护专职力量提供用户信息， 为查处网络安全违法行为服务。\n（2） 自公安部网络安全保护专职力量或信息通信部职权机构提出要求起 24 小时内， 制止共享和删除本法第 16 条第 1 款 、第2 款 、第3 款 、第4 款 、第5 款规定的服务信息或由机构、 组织直接管理的信息系统， 保存系统日志， 为在政府规定的时间内查处网络安全违法行为提供服务。\n（3） 应公安部网络安全保护专职力量或信息通信部职权机构要求， 不向或停止向在 ·55· 越南社会主义共和国网络安全法网络空间上发布含有本法第 16 条第 1 款 、第2 款 、第3 款 、第4 款 、第5 款内容信息的组织、 个人提供电信网络、 互联网服务和增值业务。\n3. 在越南网络空间提供电信网络、 互联网、 网络空间增值服务的国内外企业， 应当在政府规定的时间内， 将其所收集、 开发、 分析、 处理的个人信息数据、 用户关系数据、 越南用户创建数据存储在越南。\n本条所规定的外国企业必须在越南设立分支机构或代表处。\n4. 政府对本条第 3 款作详细规定。"}},{"id":"VN-H069-A27","no":27,"noLabel":{"zh":"第27条"},"chapter":{"zh":"第四章"},"text":{"zh":"网络安全的研究与发展\n1. 网络安全的研究、 发展内容包括：\n（1） 建立网络安全保护的软件和设备系统；\n（2） 验证网络安全保护的软件和设备是否符合标准以及限制保密漏洞、 缺口和恶意软件的方法；\n（3） 检查所提供的硬件和软件是否正确执行功能的方法；\n（4） 保护国家机密、 工作机密、 商业机密、 个人隐私、 家庭和私人生活隐私的方法， 网络空间信息传输保密能力；\n（5） 确定网络空间传输的信息的来源；\n（6） 解决威胁网络安全的危机；\n（7） 建立网络靶场和网络安全试验环境；\n（8） 提高网络安全意识和技能的技术举措；\n（9） 网络安全预报；\n（10） 研究网络安全理论的实践和发展。\n2. 有关机构、 组织和个人有权研究和发展网络安全。"}},{"id":"VN-H069-A28","no":28,"noLabel":{"zh":"第28条"},"chapter":{"zh":"第四章"},"text":{"zh":"提高网络安全的自主能力\n1. 国家鼓励和创造条件， 以提高机构、 组织和个人的网络安全自主能力， 提高生产、 检查、 评估和鉴定数字设备、 网络服务、 网络应用的能力。\n2. 政府应采取以下措施， 提高机构、 组织和个人在网络安全方面的自主能力：\n（1） 促进技术、 产品、 服务、 应用的转让、 研究、 掌握和发展， 保护网络安全；\n（2） 推进与网络安全相关的新技术和先进技术的应用；\n（3） 组织网络安全人员的培训、 提升和使用；\n（4） 强化经营环境， 改善竞争条件， 帮助企业研究、 生产保护网络安全的产品、 服务和应用。\n“一带一路”法律查明     第 3 卷 ·56·"}},{"id":"VN-H069-A29","no":29,"noLabel":{"zh":"第29条"},"chapter":{"zh":"第五章"},"text":{"zh":"网络空间的未成年人保护\n1. 参与网络空间活动的未成年人有权受到保护， 享有获取信息、 参与社会和娱乐消遣活动、 保守个人生活隐私的权利及其他权利。\n2. 信息系统主管和电信网络、 互联网、 网络空间增值服务供应商， 有责任监管信息系统和企业业务的信息内容， 以免伤害未成年人、 侵害未成年人及其权利； 禁止共享并且删除含有伤害未成年人、 侵害未成年人及其权利内容的信息； 及时通报并配合公安部网络安全保护专职力量进行处理。\n3. 参与网络空间活动的机构、 组织和个人有责任根据本法及未成年人法的规定， 配合职权机构保障未成年人在网络空间的权利， 禁止含有危害未成年人内容的信息。\n4. 机构、 组织、 家长、 教师、 监护人和其他有关人员有责任按照未成年人法的规定， 保障未成年人权利， 保护参与网络空间活动的未成年人。\n5. 网络安全保护专职力量和职能机构有责任采取措施， 以防范、 发现、 制止和严正处理利用网络空间危害未成年人、 侵犯未成年人及其权利的行为。\n第五章  保障网络安全保护活动"}},{"id":"VN-H069-A30","no":30,"noLabel":{"zh":"第30条"},"chapter":{"zh":"第五章"},"text":{"zh":"网络安全保护专职力量\n1. 网络安全保护专职力量由公安部、 国防部部署。\n2. 在直接管理国家安全重要信息系统的部委、 省级人民委员会、 机构和组织中部署网络安全保护专职力量。\n3. 可以调动组织、 个人参与网络安全保护。"}},{"id":"VN-H069-A31","no":31,"noLabel":{"zh":"第31条"},"chapter":{"zh":"第五章"},"text":{"zh":"网络安全保护的人员保障\n1. 具备网络安全、 网络信息安全、 信息技术知识的越南公民是网络安全保护的基础和主要人力资源。\n2. 国家具有建设和发展网络安全保护人力资源的项目和计划。\n3. 发生网络安全、 网络恐怖主义、 网络攻击、 网络安全事故或威胁网络安全危机等危险情况时， 国家职权机构有权决定调动网络安全保护人员。\n调动网络安全保护人员的权限、 职责、 程序和手续应按 《国家安全法》 《国防法》 《人民公安法》 及其他有关法律的规定执行。"}},{"id":"VN-H069-A32","no":32,"noLabel":{"zh":"第32条"},"chapter":{"zh":"第五章"},"text":{"zh":"网络安全保护专职力量的招募、 培训和发展\n1. 满足道德素养、 健康和网络安全、 网络信息安全、 信息技术水平和知识的标准且有意向的越南公民， 可被招募加入网络安全保护专职力量。\n·57· 越南社会主义共和国网络安全法\n2. 优先培养和发展高质量网络安全保护专职力量。\n3. 优先发展符合国际标准的网络安全培训机构， 鼓励国家领域和私人领域、 国内和国外之间进行网络安全的联合与合作。"}},{"id":"VN-H069-A33","no":33,"noLabel":{"zh":"第33条"},"chapter":{"zh":"第五章"},"text":{"zh":"网络安全知识和业务的教育和培养\n1. 网络安全知识的教育和培养内容应当按照国防安全教育法的规定， 纳入学校国防安全教育课程和国防安全知识培养项目。\n2. 公安部主持、 配合有关部委， 为网络安全保护专职力量和参与网络安全保护的公务员、 事业单位人员、 劳动者组织网络安全业务培训。\n国防部、 政府机要局为其管理对象组织网络安全业务培训。"}},{"id":"VN-H069-A34","no":34,"noLabel":{"zh":"第34条"},"chapter":{"zh":"第五章"},"text":{"zh":"网络安全知识的普及\n1. 国家具有在全国范围内普及网络安全知识、 鼓励国家机构、 私人组织和个人协调开展网络安全意识教育和提升项目的政策。\n2. 部委、 机构和组织有责任为其干部、 公务员、 事业单位人员、 劳动者制定和开展普及网络安全知识的活动。\n3. 省级人民委员会有责任为地方机构、 组织和个人制定和开展普及网络安全知识、 提高网络安全意识的活动。"}},{"id":"VN-H069-A35","no":35,"noLabel":{"zh":"第35条"},"chapter":{"zh":"第六章"},"text":{"zh":"网络安全保护的经费\n1. 国家机构、 政治组织的网络安全保护经费由国家财政预算承担， 列入国家年度财政预算计划。国家财政预算经费的管理和使用遵守国家财政预算法律的规定。\n2. 在本条第 1 款规定以外的机构、 组织的信息系统网络安全保护经费， 由该机构、 组织自行承担。\n第六章  机构、 组织、 个人的责任"}},{"id":"VN-H069-A36","no":36,"noLabel":{"zh":"第36条"},"chapter":{"zh":"第六章"},"text":{"zh":"公安部的职责公安部对政府负责， 对网络安全实行国家管理， 除属国防部和政府机要局负责的事项外， 公安部具有下列任务和权限：\n1. 颁布或向有国家职权颁布机构呈报网络安全法律法规， 并指导执行。\n2. 制定和提出网络安全保护的战略、 主张、 政策、 计划和方案。\n3. 防范和打击利用网络空间侵犯国家主权、 利益和安全、 社会治安的活动， 防范和打击网络犯罪。\n4. 保障网络空间的信息安全； 建立数字账户注册信息认证机制； 警告网络安全威胁 “一带一路”法律查明     第 3 卷 ·58· 危机， 分享网络安全信息。\n5. 在国家管理内容涉及多个部委的管理范围的情况下， 商议、 提议政府和政府总理审查、 决定实施保护网络安全、 防范和处理侵犯网络安全行为的措施中的分配和协调事宜。\n6. 组织防范和打击网络攻击的演习， 应对和解决国家安全重要信息系统网络安全事故的演习。\n7. 检查、 清查、 解决投诉和控告， 处理网络安全违法行为。"}},{"id":"VN-H069-A37","no":37,"noLabel":{"zh":"第37条"},"chapter":{"zh":"第六章"},"text":{"zh":"国防部的职责国防部对政府负责， 在其管理范围内执行网络安全国家管理工作， 且具有下列任务和权限：\n1. 颁布或向国家职权颁布机构呈报网络安全法律法规， 并在其管理范围内指导执行；\n2. 制定、 提出其管理范围内的网络安全保护战略、 路线、 政策、 计划和方案；\n3. 防范和打击在其管理范围内利用网络空间侵犯国家安全的活动；\n4. 配合公安部组织防范与打击网络攻击、 应对与解决国家安全重要信息系统网络安全事故的演习， 开展网络安全保护工作；\n5. 在其管理范围内， 检查、 清查、 解决投诉和控告， 处理网络安全违法行为。"}},{"id":"VN-H069-A38","no":38,"noLabel":{"zh":"第38条"},"chapter":{"zh":"第六章"},"text":{"zh":"信息通信部的职责\n1. 配合公安部、 国防部保护网络安全。\n2. 配合有关机构组织宣传， 驳斥含有本法第16 条第 1 款规定的反越南社会主义共和国的信息。\n3. 要求电信网络、 互联网、 网络空间增值服务供应商和信息系统主管删除企业、 机构、 组织直接管理的服务和信息系统中含有违反网络安全法内容的信息。"}},{"id":"VN-H069-A39","no":39,"noLabel":{"zh":"第39条"},"chapter":{"zh":"第六章"},"text":{"zh":"政府机要局的职责\n1. 商议和提议国防部部长颁布， 或向职权颁布机构呈报网络安全保护密码的法律法规、 项目和计划， 并在其管理范围内组织执行。\n2. 保护政府机要局下属的机要信息系统和本法规定其提供的密码产品的网络安全。\n3. 对密码科技的研究以及密码产品的生产、 使用和供应实行统一管理， 以保护网络空间上存储、 交换的国家机密信息。"}},{"id":"VN-H069-A40","no":40,"noLabel":{"zh":"第40条"},"chapter":{"zh":"第六章"},"text":{"zh":"各部委和省级人民委员会的职责各部委、 省级人民委员会在其职权范围内， 有责任对其管理的信息和信息系统执行网络安全保护工作； 配合公安部执行各部委和地方网络安全的国家管理工作。\n·59· 越南社会主义共和国网络安全法"}},{"id":"VN-H069-A41","no":41,"noLabel":{"zh":"第41条"},"chapter":{"zh":"第六章"},"text":{"zh":"网络空间服务供应商的责任\n1. 在越南提供网络空间服务的供应商负有以下责任：\n（1） 对其提供的网络空间服务在使用过程中出现的网络安全失效可能性进行警告， 并指导执行防范措施。\n（2） 制定网络安全事故的应急方案和解决办法， 立即处理保密漏洞和缺口、 恶意代码、 网络攻击、 网络入侵和其他安全风险； 发生网络安全事故时， 立即开展相应的应急方案和应对措施， 同时按本法规定通知网络安全保护专职力量。\n（3） 采取技术解决办法和其他必要措施， 保障信息收集过程的安全， 防止数据暴露、 泄露、 损坏或丢失的风险； 如发生或存在用户信息暴露、 泄露、 损坏或丢失的事故， 应当立即提出应对办法， 同时按本法规定通知用户并向网络安全保护专职力量报告。\n（4） 配合并为网络安全保护专职力量进行网络安全保护创造条件。\n2. 在越南提供电信网络、 互联网和网络空间增值服务的供应商有责任遵守本法本条第 1 款和第 26 条第 1 款 、第2 款 、第3 款的规定。"}},{"id":"VN-H069-A42","no":42,"noLabel":{"zh":"第42条"},"chapter":{"zh":"第七章"},"text":{"zh":"使用网络空间的机构、 组织和个人的责任\n1. 遵守网络安全法律的规定。\n2. 及时向职权机构和网络安全保护专职力量提供与网络安全保护、 网络安全威胁风险和侵犯网络安全行为有关的信息。\n3. 执行职权机构对网络安全保护的要求和指示； 为机构、 组织和责任人创造条件， 协助其执行网络安全保护措施。\n第七章  条款施行"}},{"id":"VN-H069-A43","no":43,"noLabel":{"zh":"第43条"},"chapter":{"zh":"第七章"},"text":{"zh":"施行效力\n1. 本法自 2019 年 1 月 1 日起生效。\n2. 运行中、 使用中的信息系统被列入国家安全重要信息系统名录的， 自本法生效之日起 12 个月内， 信息系统主管有责任保障其满足网络安全条件， 网络安全保护专职力量依照本法第 12 条的规定评估网络安全条件； 如需延期则由政府总理决定， 但不超过 12 个月。\n3. 运行中、 使用中的信息系统被补入国家安全重要信息系统名录的， 自补充之日起 12 个月内， 信息系统主管有责任保障其满足网络安全条件， 网络安全保护专职力量依照本法第 12 条的规定评估网络安全条件； 如需延期则由政府总理决定， 但不超过12 个月。\n本法已于 2018 年 6 月 12 日由越南社会主义共和国第十四届国会第 5 次会议通过。"}}],"pack":"vn-p03","rebuiltFrom":"原为单条全文，2026-10-24 按条号标记重新切分（拼接无损校验通过）"};
  FT["VN-H070"] = {"id":"VN-H070","coverage":"full","language":"zh","sourceName":"越南官方发布渠道","sourceUrl":"","fetchedAt":"2026-10-04","articleCount":77,"structureMode":"ARTICLE","title":{"zh":"户籍法","en":"Law on Civil Status","orig":null},"level":"law","status":"active","docNumber":"年份不详","issuingBody":"越南官方发布渠道","completenessNote":"文本未能可靠切分为条文（或原件为目录式排版），按整篇收录，未作改写。","country":"VN","countryName":"越南","layer":"intl","articles":[{"id":"VN-H070-A1","no":1,"noLabel":{"zh":"第1条"},"chapter":{"zh":"第一章"},"text":{"zh":"·3· 根据 《越南社会主义共和国宪法》 ， 国会颁布 《越南社会主义共和国户籍法》 。\n第一章  总则\n适用范围\n1. 本法对户籍工作作出规定： 户籍登记的权利、 义务、 原则、 权限和手续， 户籍数据库和国家户籍管理。\n2. 处理国籍和收养事宜的权限和手续， 除本法另有规定外， 应符合 《越南国籍法》 和 《收养法》 的规定。"}},{"id":"VN-H070-A2","no":2,"noLabel":{"zh":"第2条"},"chapter":{"zh":"第一章"},"text":{"zh":"户籍和户籍登记\n1. 户籍是指本法"}},{"id":"VN-H070-A3","no":3,"noLabel":{"zh":"第3条"},"chapter":{"zh":"第一章"},"text":{"zh":"规定的用以确定该人从出生到死亡时身份信息的总称。\n2. 户籍登记是指国家权力机构确认或记录个人户籍状况， 为国家保护个人权利、 利益， 实现居民管理奠定法理基础。\n第三条  户籍登记内容\n1. 在户口册中登记下列户籍信息：\n（a） 出生；\n（b） 婚姻状况；\n（c） 监护情况；\n（d） 收养关系；\n（đ） 户籍变更、 更正， 民族重新确认， 补充户籍信息；\n（e） 死亡。\n2. 根据权力机构的规定在户籍册中登记个人户籍变更信息：\n（a） 国籍变更；\n（b） 确认亲子关系；\n* 译者： 杜雪淼， 北京外国语大学亚洲学院助教。\n* “一带一路”法律查明     第 3 卷 ·4· （c） 重新确认性别；\n（d） 收养和终止收养；\n（đ） 离婚， 取消非法婚姻， 公开婚姻；\n（e） 承认监护人；\n（g） 宣告失踪、 死亡或限制民事行为能力。\n3. 将越南公民在国外权力机构登记的出生、 结婚、 离婚、 取消婚姻、 监护关系、 亲子关系、 收养关系、 户籍变更、 死亡等信息记录到户籍册中。\n4. 依照法律规定在户籍册中确认或登记其他户籍信息。"}},{"id":"VN-H070-A4","no":4,"noLabel":{"zh":"第4条"},"chapter":{"zh":"第一章"},"text":{"zh":"词语解释本法中的一些词语解释如下：\n1. 户籍登记机构为乡、 坊、 镇人民委员会 （以下简称 “乡级人民委员会” ） ， 县、 郡、 镇、 省辖市人民委员会和与之相当的行政单位 （以下简称 “县级人民委员会” ） ， 越南的国外外交代表机构和领事代表机构 （以下简称 “代表机构” ） 。\n2. 户籍数据库是指登记和留存在户籍册和电子户籍数据库中的个人户籍信息集合。\n3. 户籍册是指编制完成后保存在户籍登记机构中用以确认或记录本法第 3 条规定的户籍信息的纸册。\n4. 电子户籍数据库是指户籍登记工作信息化而形成的部门数据库。\n5. 户籍数据库管理机构包括法律赋予权限的户籍登记机构、 司法部、 外交部和其他机构。\n6. 出生证是指在进行出生登记时由国家权力机构颁发给个人的文件， 其内容包括本法第 14 条第 1 款所规定的个人基本信息。\n7. 结婚证是指在结婚登记时国家权力机构颁发给男女双方的文件， 其内容包括本法第 17 条第 2 款所规定的基本信息。\n8. 在进行出生登记时， 根据父母的协商结果或习惯， 个人的籍贯在出生时跟随父亲或母亲的籍贯记录在出生证中。\n9. 户籍摘录是指国家权力机构颁发的用以证明在户籍登记机构登记的个人户籍信息的文本， 该文本在户籍信息登记后颁发， 其副本包括由户籍数据库印发的户籍摘录副本和经原件证实过的户籍摘录副本。\n10. 户籍变更是指个人按照民法规定以正当理由请求国家权力机构在已登记的出生信息中变更个人或父母的户籍信息。\n11. 民族重新确认是指国家权力机构按照民法规定登记重新确认过的个人民族信息。\n·5·\n12. 户籍更正是指在户籍登记有误的情况下， 国家权力机构修正户籍信息。\n13. 户籍补充是指国家权力机构更新在个人登记时遗漏的户籍信息。"}},{"id":"VN-H070-A5","no":5,"noLabel":{"zh":"第5条"},"chapter":{"zh":"第一章"},"text":{"zh":"户籍登记原则\n1. 尊重和保障个人权利。\n2. 个人所有的户籍信息必须登记完整、 及时、 真实、 客观和准确， 遇到不符合法律规定的户籍登记条件的情况， 户籍登记机构负责人可以文件为证拒绝办理登记， 并说明理由。\n3. 对于本法没有规定处理期限的户籍事宜可以当日办理。若在接受档案 15 小时后不能及时解决， 则在次工作日内给予答复。\n4. 每项户籍信息只能在本法规定的具有权限的户籍登记机构登记。\n个人可以在常住地、 暂住地或目前所在地的户籍登记机构进行户籍登记。个人不在常住地登记的情况下， 已经登记过个人户籍的县级人民委员会、 乡级人民委员会、 地方代表机构有责任向个人常住地的乡级人民委员会上报户籍登记情况。\n5. 登记入户籍册的所有户籍信息必须及时更新完善到电子户籍数据库中。\n6. 户籍数据库中的出生、 结婚、 离婚、 死亡、 户籍变更、 更正及补充、 性别、 民族等个人信息是全国人口数据库中的首要信息。\n7. 保证户籍登记过程公开、 明白。"}},{"id":"VN-H070-A6","no":6,"noLabel":{"zh":"第6条"},"chapter":{"zh":"第一章"},"text":{"zh":"个人户籍登记的权利和义务\n1. 越南公民、 在越南常住的无国籍人士有权利和义务进行户籍登记。\n除越南作为成员国而签署的国际条约另有规定的情形外， 此规定也适用于常住在越南的外国公民。\n2. 结婚、 确认收养关系时， 各方必须亲自到户籍登记机构办理。\n对于其他的户籍登记事宜或者户籍摘录副本颁发， 本人可以亲自或委托他人办理。\n司法部部长对委托他人办理作具体规定。\n3. 未成年人、 已成年而丧失民事行为能力的人依法通过代表人进行户籍登记或申请户籍摘录副本。"}},{"id":"VN-H070-A7","no":7,"noLabel":{"zh":"第7条"},"chapter":{"zh":"第一章"},"text":{"zh":"户籍登记权限\n1. 乡级人民委员会在下列情形中进行户籍登记：\n（a） 必须就本法第3 条第 1 款 第（a）项 、第（b）项 、第（c）项 、第（d） 项和第 （e）项规定的事项为居住在国内的越南公民登记户籍。\n（b） 为未满14 岁者办理户籍变更、 更正， 为居住在国内的越南公民补充户籍信息。\n“一带一路”法律查明     第 3 卷 ·6· （c） 按照本法第3 条第 2 款和第 4 款中的规定办理户籍。\n（d） 出生在越南的孩子， 其父母一方是常住边界地区的越南公民， 另一方是常住边界地区的越南邻国公民， 为其办理出生登记； 常住于边界地区的越南公民和常住于边界地区的越南邻国公民结婚、 确认收养关系， 为其办理登记； 为长期居住在越南的外国公民办理死亡登记。\n2. 除本条第 1 款 第（d） 项中规定的情形外， 县级人民委员会在下列情形中进行户籍登记：\n（a） 本法第3 条第 1 款规定的户籍登记事宜涉及国外因素；\n（b）年 满14 周岁以上且居住在国内的越南公民， 为其办理户籍变更、 更正登记， 确定民族信息；\n（c） 依据本法第3 条第 3 款的规定办理户籍事宜。\n3. 代表机构依据本法第 3 条为居住在国内的越南公民办理户籍事宜。\n4. 政府依据本条第 1 款 第（d） 项的规定办理出生、 结婚、 收养关系确认、 死亡等登记手续。"}},{"id":"VN-H070-A8","no":8,"noLabel":{"zh":"第8条"},"chapter":{"zh":"第一章"},"text":{"zh":"保证户籍登记的权利和义务\n1. 国家有相关政策、 措施为个人办理户籍登记的权利和义务创造条件。\n2. 国家为户籍登记和管理工作提供财政、 物质、 人力和信息技术发展投资支持。"}},{"id":"VN-H070-A9","no":9,"noLabel":{"zh":"第9条"},"chapter":{"zh":"第一章"},"text":{"zh":"户籍登记申请及其接受方法\n1. 当办理户籍登记和申请户籍摘录副本时， 个人需亲自向户籍登记机构提交档案， 或通过邮政、 在线户籍登记系统寄到户籍登记机构。\n2. 当办理户籍登记手续、 从户籍数据库中印发户籍摘录副本时， 除通过邮政寄到户籍登记机构须附带身份证复印件外， 个人需向户籍登记机构出示身份证。\n3. 对于有办理期限规定的户籍登记事宜， 档案接受者必须写下接受证明； 档案不齐全、 不合格的， 必须按文件规定指导其进行户籍补充、 完善， 指导文件必须内容完整、 说明补充证明。\n若个人所提交的档案不符合户籍登记机构的要求， 接受人应指导其到权力机构提交档案。"}},{"id":"VN-H070-A10","no":10,"noLabel":{"zh":"第10条"},"chapter":{"zh":"第一章"},"text":{"zh":"对国外证明的领事合法化除越南是国际条约的签署国而免除领事合法化外， 由国外权力机构颁发、 公证或确认的用以在越南办理户籍登记的证明必须依照法律规定领事合法化。\n·7·"}},{"id":"VN-H070-A11","no":11,"noLabel":{"zh":"第11条"},"chapter":{"zh":"第一章"},"text":{"zh":"户籍办理手续费\n1. 下列情形免除户籍登记手续费：\n（a） 为家庭成员有功于革命事业者、 家庭贫困者、 残疾人办理户籍登记；\n（b） 为居住在国内的越南公民按期登记出生、 死亡、 监护和婚姻状况信息。\n2. 个人要求登记除本条第 1 款规定以外的户籍信息和申请户籍摘录副本时须交付手续费。\n财政部对收费权限、 收付费额度、 管理制度和手续费使用作具体规定。"}},{"id":"VN-H070-A12","no":12,"noLabel":{"zh":"第12条"},"chapter":{"zh":"第二章"},"text":{"zh":"禁止行为\n1. 严禁个人进行以下行为：\n（a） 在户籍登记时， 提供与事实不符的信息和材料， 作假证明或使用假证明、 他人的证明；\n（b） 强迫、 威胁、 阻碍他人办理户籍登记；\n（c） 非法干涉户籍登记工作；\n（d） 作不符合事实的担保和证明以办理户籍登记；\n（đ） 弄虚作假， 篡改户籍证明或者户籍数据库中的信息；\n（e） 贿赂、 收买、 答允物质或精神利益以办理户籍登记；\n（g） 以任何形式牟利， 享受国家优待政策而利用户籍登记， 或逃避户籍登记义务；\n（h） 个人有权按照 《婚姻家庭法》 的规定为本人或亲人办理户籍登记；\n（i） 非法登录户籍数据库， 盗取、 破坏户籍数据库中的信息。\n2. 违反本条第 1 款 第（a）项 、第（d）项 、第（đ）项、第（g） 项的规定而颁发的户籍证明没有价值， 必须收回和销毁。\n3. 个人在实施本条第 1 款规定的行为时， 依据法律规定视违反性质和程度处以行政处罚或追究刑事责任。\n违反本条第 1 款规定的干部和公务员， 除处以上述处罚外， 还须按照干部和公务员的法律规定处以纪律处分。\n第二章  乡级人民委员会的户籍登记第一节  出生登记"}},{"id":"VN-H070-A13","no":13,"noLabel":{"zh":"第13条"},"chapter":{"zh":"第二章"},"text":{"zh":"出生登记权限在父母亲一方居住地的乡级人民委员会办理出生登记。\n“一带一路”法律查明     第 3 卷 ·8·"}},{"id":"VN-H070-A14","no":14,"noLabel":{"zh":"第14条"},"chapter":{"zh":"第二章"},"text":{"zh":"出生登记内容\n1. 出生登记内容包括：\n（a） 被登记出生者的个人信息： 姓、 垫字、 名、 性别、 出生年月日、 出生地、 籍贯、 民族、 国籍；\n（b） 被登记出生者的父母信息： 姓、 垫字、 名、 性别、 出生年份、 民族、 国籍、 居住地；\n（c） 被登记出生者的身份证号。\n2. 被登记出生者国籍、 民族、 姓氏的确定依据 《越南国籍法》 和 《民法》 的规定进行。\n3. 本条第 1 款规定的出生登记内容是个人的基本户籍信息， 被记录到户籍册、 出生证、 电子户籍数据库和全国人口数据库中， 与出生信息有关的个人档案和证明必须与本人的出生登记信息相符合。\n政府对被登记出生者身份证号的颁发作出规定。"}},{"id":"VN-H070-A15","no":15,"noLabel":{"zh":"第15条"},"chapter":{"zh":"第二章"},"text":{"zh":"出生登记责任\n1. 自婴儿出生起 60 天内， 父亲或母亲有责任为其办理出生登记； 若父亲或母亲不能为其办理出生登记， 养育孩子的爷爷、 奶奶或其他亲人、 个人、 组织有责任为其办理出生登记。\n2. 司法 – 户籍办理人员应在规定期限内检查、 督促地方婴儿的出生登记事宜， 必要情况下可办理流动出生登记。"}},{"id":"VN-H070-A16","no":16,"noLabel":{"zh":"第16条"},"chapter":{"zh":"第二章"},"text":{"zh":"出生登记手续\n1. 办理出生登记者需向户籍登记机构提交固定模板的表单和出生证明， 没有出生证明就提交出生作证人开具的文本， 若没有作证人就必须有出生保证书； 给弃婴办理出生登记必须有权力机构开具的弃婴确认证明； 为由代孕产下的婴儿办理出生登记必须有按照法律规定开具的代孕证明。\n2. 按照本条第 1 款的规定收齐证明后， 若出生信息完整、 符合规定， 司法– 户籍办理人员依照本法第 14 条第 1 款的规定将出生信息登记到户籍册、 电子户籍数据库和全国人口数据库中以获取身份证号。\n司法 – 户籍工作人员与办理出生登记者共同在户籍册上签字， 乡级人民委员会主席为被登记出生者颁发出生证。\n3. 政府对为弃婴、 尚未确认父母的婴儿、 由代孕产下的婴儿办理出生登记和为弃婴、 尚未确认父母的婴儿确定籍贯等事宜作出具体规定。\n·9· 第二节  结婚登记"}},{"id":"VN-H070-A17","no":17,"noLabel":{"zh":"第17条"},"chapter":{"zh":"第二章"},"text":{"zh":"结婚登记权限和结婚证内容\n1. 男女双方中一方居住所在地的乡级人民委员会办理结婚登记。\n2. 结婚证必须具备下列信息：\n（a） 姓、 垫字、 名、 出生年月日、 民族、 国籍、 居住地、 男女双方的身份证信息；\n（b） 登记结婚的年月日；\n（c） 男女双方的签字或手印， 户籍登记机构的确认。"}},{"id":"VN-H070-A18","no":18,"noLabel":{"zh":"第18条"},"chapter":{"zh":"第三节"},"text":{"zh":"结婚登记手续\n1. 男女双方按照规定模板向户籍登记机构提交结婚登记表， 结婚登记时两人需在场。\n2. 按照本条第 1 款的规定收齐证明后， 若满足 《婚姻家庭法》 规定的结婚条件， 司法 – 户籍办理人员把结婚信息记入户籍册， 并与男女双方在上面签字。男女双方共同在结婚证上签字， 司法– 户籍办理人员通知乡级人民委员会主席向男女双方颁发结婚证。\n需要核对男女双方结婚条件的情况， 办理期限不超过 5 个工作日。\n第三节  监护人登记"}},{"id":"VN-H070-A19","no":19,"noLabel":{"zh":"第19条"},"chapter":{"zh":"第三节"},"text":{"zh":"监护登记和终止监护的权限被监护人或监护人居住地的乡级人民委员会办理监护登记。\n办理监护登记的乡级人民委员会办理终止监护。"}},{"id":"VN-H070-A20","no":20,"noLabel":{"zh":"第20条"},"chapter":{"zh":"第三节"},"text":{"zh":"指定监护登记手续\n1. 申请监护登记者依照 《民法》 规定向户籍登记机构提交固定模板的监护登记表和指定监护人申请。\n2. 依据本条第 1 款， 自收齐证明之日起3 个工作日内， 若根据法律规定符合条件， 由司法 – 户籍工作人员将其记入户籍册， 并与监护登记人共同在上面签字， 上报乡级人民委员会主席为其颁发摘录。"}},{"id":"VN-H070-A21","no":21,"noLabel":{"zh":"第21条"},"chapter":{"zh":"第三节"},"text":{"zh":"当然监护登记\n1. 申请监护登记人依照 《民法》 规定向户籍登记机构提交固定模板的监护登记表和当然监护条件证明表。当多人同时满足当然监护人的条件时， 需另提交指定一个当然监护人的协议。\n2. 当然监护人的登记程序依照本法第 20 条第 2 款的规定进行。"}},{"id":"VN-H070-A22","no":22,"noLabel":{"zh":"第22条"},"chapter":{"zh":"第三节"},"text":{"zh":"终止监护登记\n1. 申请登记终止监护者依照 《民法》 规定向户籍登记机构提交固定模板的监护登记 “一带一路”法律查明     第 3 卷 ·10· 表和终止监护证明。\n2. 依据本条第 1 款的规定， 自收齐证明之日起 2 个工作日内， 若终止监护符合法律规定的条件， 则司法– 户籍工作人员将其登记到户籍册中， 并与终止监护登记人一同在上面签字， 上报乡级人民委员会主席为其颁发摘录。"}},{"id":"VN-H070-A23","no":23,"noLabel":{"zh":"第23条"},"chapter":{"zh":"第四节"},"text":{"zh":"变更监护登记当依照 《民法》 申请变更监护人， 另有他人符合监护人的条件时， 各方首先办理终止监护手续， 然后根据本节中的规定登记新的监护人。\n第四节  收养关系登记"}},{"id":"VN-H070-A24","no":24,"noLabel":{"zh":"第24条"},"chapter":{"zh":"第四节"},"text":{"zh":"登记收养关系权限\n1. 申请登记收养关系者需向户籍登记机构提交固定模板的表单和父子或母子关系证明， 登记时， 各方的子女都必须在场。\n2. 依据本条第 1 款的规定， 自收齐证明之日起 3 个工作日内， 若收养关系正当且无争议， 司法– 户籍办理人员将其记入户籍册， 并与登记人一同在上面签字， 上报乡级人民委员会主席为其颁发摘录。\n必须出示证明的情况， 延长期限不超过5 个工作日。"}},{"id":"VN-H070-A25","no":25,"noLabel":{"zh":"第25条"},"chapter":{"zh":"第四节"},"text":{"zh":"（缺） 第五节  户籍变更、 更正、 补充登记"}},{"id":"VN-H070-A26","no":26,"noLabel":{"zh":"第26条"},"chapter":{"zh":"第四节"},"text":{"zh":"户籍变更范围\n1. 按照民法规定有相关依据时， 在已登记的出生信息中变更个人的姓、 垫字和名。\n2. 按照收养法规定被收养时， 在已登记的出生信息中变更父母信息。"}},{"id":"VN-H070-A27","no":27,"noLabel":{"zh":"第27条"},"chapter":{"zh":"第四节"},"text":{"zh":"户籍变更、 更正、 补充登记权限此前登记户籍或个人居住地的乡级人民委员会有权为未满 14 岁者变更、 更正户籍， 为在国内居住的越南公民补充户籍。"}},{"id":"VN-H070-A28","no":28,"noLabel":{"zh":"第28条"},"chapter":{"zh":"第四节"},"text":{"zh":"户籍变更、 更正登记手续\n1. 申请户籍变更、 更正登记者向户籍登记机构提交固定模板的表单和相关证明。\n2. 依据本条第 1 款的规定， 自收齐证明之日起3 个工作日内， 若户籍变更、 更正有据可依， 符合民法和相关法律的规定， 则司法– 户籍工作人员将其记入户籍册， 并与申请登记人一同在上面签字， 上报乡级人民委员会主席为其颁发摘录。\n若户籍变更、 更正与出生证、 结婚证相关联， 则司法– 户籍工作人员将其一并记入出生证、 结婚证。\n·11·\n3. 若不在此前登记户籍地登记户籍变更、 更正， 乡级人民委员会必须以证明和户籍摘录副本上报此前户籍登记地的人民委员会将其记入户籍册。\n若此前的户籍登记地是代表机构， 乡级人民委员会必须以证明和户籍摘录副本上报外交部， 让其转达代表机构将信息记入户籍册。"}},{"id":"VN-H070-A29","no":29,"noLabel":{"zh":"第29条"},"chapter":{"zh":"第六节"},"text":{"zh":"户籍补充手续\n1. 申请户籍补充者向户籍登记机构提交固定模板的表单和相关证明。\n2. 依据本条第 1 款的规定， 收齐证明后， 若户籍补充申请正当， 则司法– 户籍工作人员将补充内容记入户籍册的相应章节， 并与申请人一同在上面签字， 上报乡级人民委员会主席为其颁发摘录。\n若需将户籍补充信息记入出生证、 结婚证， 司法– 户籍工作人员可将其记入相应位置并在上面盖章。\n第六节  按照权力机构的判决和规定在户籍册中登记户籍变更信息"}},{"id":"VN-H070-A30","no":30,"noLabel":{"zh":"第30条"},"chapter":{"zh":"第六节"},"text":{"zh":"户籍变更的通报责任\n1. 依照本法第 3 条第 2 款的规定， 自户籍变更的判决和决定具有法律效力之日起 5 个工作日内， 人民法庭、 国家权力机构有责任以文件附带判决摘录、 规定副本的形式通报个人户籍登记地的人民委员会将其记入户籍册； 若户籍登记地是代表机构， 则上报外交部， 让其转告代表机构将其记入户籍册。\n2. 国籍变更通报依照国籍法的规定进行。"}},{"id":"VN-H070-A31","no":31,"noLabel":{"zh":"第31条"},"chapter":{"zh":"第七节"},"text":{"zh":"依照国家权力机构的判决和规定在户籍册中记录户籍变更的手续依照本法第 30 条的规定， 接到通报后， 司法– 户籍工作人员按照人民法庭、 国家权力机构的判决和规定将变更内容登记到户籍册中。\n第七节  死亡登记"}},{"id":"VN-H070-A32","no":32,"noLabel":{"zh":"第32条"},"chapter":{"zh":"第七节"},"text":{"zh":"死亡登记权限死者最后居住地的乡级人民委员会办理死亡登记。不确定死者最后居住地的情况， 由死者死亡地或尸体发现地的乡级人民委员会办理死亡登记。"}},{"id":"VN-H070-A33","no":33,"noLabel":{"zh":"第33条"},"chapter":{"zh":"第七节"},"text":{"zh":"死亡登记期限和责任\n1. 自死亡之日起 15 日内， 死者的妻子、 丈夫或孩子、 父母、 其他亲人有责任为其登记死亡； 若死者没有亲人， 由相关机构、 组织、 个人的代表为其登记死亡。\n2. 司法 – 户籍工作人员时常检查死亡登记情况督促为死者登记死亡。若不能确定死亡登记责任人， 由司法– 户籍工作人员为其登记死亡。\n“一带一路”法律查明     第 3 卷 ·12·"}},{"id":"VN-H070-A34","no":34,"noLabel":{"zh":"第34条"},"chapter":{"zh":"第三章"},"text":{"zh":"死亡登记手续\n1. 死亡登记责任人向户籍登记机构提交固定模板的表单和死亡通知书或代替死亡通知书的其他证明。\n2. 依照本条第 1 款的规定， 收齐证明后， 若死亡登记申请属实， 司法– 户籍工作人员将死亡登记内容记入户籍册， 与申请死亡登记者一同在上面签字， 上报乡级人民委员会主席为其颁发摘录。\n司法 – 户籍工作人员在电子户籍数据库中锁定死者的户籍信息。\n第三章  县级人民委员会的户籍登记第一节  出生登记"}},{"id":"VN-H070-A35","no":35,"noLabel":{"zh":"第35条"},"chapter":{"zh":"第三章"},"text":{"zh":"出生登记权限在下列情形中， 父母亲一方居住地的县级人民委员会为新生儿办理出生登记：\n1. 新生儿在越南出生：\n（a） 父母一方是越南公民， 另一方是外国人或无国籍人士；\n（b） 父母一方是居住在国内的越南公民， 另一方是定居在国外的越南公民；\n（c） 父母是定居在国外的越南公民；\n（d） 父母是外国人或无国籍人士。\n2. 新生儿出生在国外， 且没有返回越南居住地办理出生登记：\n（a） 父母都是越南公民；\n（b） 父母一方是越南公民。"}},{"id":"VN-H070-A36","no":36,"noLabel":{"zh":"第36条"},"chapter":{"zh":"第二节"},"text":{"zh":"出生登记手续\n1. 依据本法第 16 条第 1 款的规定， 申请出生登记者向户籍登记机构提交证明， 父母一方或双方是外国人则必须提交关于孩子国籍选择的协议。\n若父母为孩子选择外国国籍， 协议必须经过属于外国公民一方的外国国家权力机构认证。\n2. 依照本条第 1 款的规定， 收齐证明后， 若出生登记信息完整、 符合规定， 户籍工作人员按照本法第 14 条的规定将出生信息记入户籍册； 依照本法第 14 条第 1 款 第（c）项的规定， 若新生儿是外国国籍则不将其出生信息记入户籍册。\n户籍工作人员与申请出生登记者一同在户籍册上签字， 司法办上报县级人民委员会主席为其颁发出生证。\n·13·\n3. 政府对本法第 35 条第 2 款中的出生登记手续作出规定。\n第二节  结婚登记"}},{"id":"VN-H070-A37","no":37,"noLabel":{"zh":"第37条"},"chapter":{"zh":"第二节"},"text":{"zh":"结婚登记权限\n1. 越南公民居住地的县级人民委员会办理以下结婚登记： 越南公民与外国人结婚、 居住在国内的越南公民与定居在国外的越南公民结婚、 定居在国外的越南公民之间结婚、 同时具有外国国籍的越南公民与越南公民或外国人结婚。\n2. 居住在越南的外国人在越南申请结婚登记， 由一方居住地的县级人民委员会办理结婚登记。"}},{"id":"VN-H070-A38","no":38,"noLabel":{"zh":"第38条"},"chapter":{"zh":"第三节"},"text":{"zh":"结婚登记手续\n1. 男女双方向户籍登记机构提交固定模板的表单和越南或国外权威医疗机构开具的本人没有患精神疾病而导致无认识能力和行为能力的确认证明。\n外国人、 定居在国外的越南公民必须另附婚姻状况证明、 护照副本或代替护照的有效证明。\n2. 依照本条第 1 款的规定， 自收齐证明之日起 15 日内， 户籍工作人员有确认责任。\n根据法律规定， 若满足结婚条件， 由司法办报告县级人民委员会办理。\n3. 办理结婚登记时， 男女双方必须到人民委员会驻地现场， 户籍工作人员询问男女双方意见， 若双方自愿结婚则将结婚信息记入户籍册， 并与男女双方在上面签字。男女双方一同在结婚证上签字。\n县级人民委员会主席为男女双方颁发结婚证。\n4. 政府对以下事宜作了规定： 在结婚登记档案中补充证明； 在办理结婚登记时询问和确认结婚目的； 为保障各方的权利和利益， 给在国外权力机构与外国人登记结婚的越南公民颁发婚姻状况证明。\n第三节  监护登记"}},{"id":"VN-H070-A39","no":39,"noLabel":{"zh":"第39条"},"chapter":{"zh":"第三节"},"text":{"zh":"监护登记和终止监护权限被监护人或监护人居住地的县级人民委员会为一同居住在越南的越南公民和外国人办理监护登记。\n办理监护登记的县级人民委员会办理终止监护。"}},{"id":"VN-H070-A40","no":40,"noLabel":{"zh":"第40条"},"chapter":{"zh":"第三节"},"text":{"zh":"指定监护登记手续\n1. 申请监护登记者依照 《民法》 规定向户籍登记机构提交固定模板的监护登记表和指定监护人申请。\n“一带一路”法律查明     第 3 卷 ·14·\n2. 依据本条第 1 款的规定， 自收齐证明之日起 5 个工作日内， 户籍工作人员进行确认， 若根据法律规定符合条件， 则将其记入户籍册， 并与监护登记人共同在上面签字， 司法办上报县级人民委员会主席为申请人颁发摘录。"}},{"id":"VN-H070-A41","no":41,"noLabel":{"zh":"第41条"},"chapter":{"zh":"第三节"},"text":{"zh":"当然监护登记共同居住在越南的越南公民和外国人之间的当然监护登记手续适用本法第 21 条的规定。"}},{"id":"VN-H070-A42","no":42,"noLabel":{"zh":"第42条"},"chapter":{"zh":"第四节"},"text":{"zh":"监护终止、 变更登记手续越南公民和外国人之间的监护终止、 变更登记手续适用本法第 22 条和第 23 条的规定。\n第四节  收养关系登记"}},{"id":"VN-H070-A43","no":43,"noLabel":{"zh":"第43条"},"chapter":{"zh":"第四节"},"text":{"zh":"收养关系登记权限被收养者居住地的县级人民委员会办理以下收养登记： 越南公民与外国人之间的收养关系、 居住在国内的越南公民与定居在国外的越南公民之间的收养关系、 定居在国外的越南公民之间的收养关系、 同时具有外国国籍的越南公民与越南公民或外国人之间的收养关系、 一方或双方常住在越南的外国人之间的收养关系。"}},{"id":"VN-H070-A44","no":44,"noLabel":{"zh":"第44条"},"chapter":{"zh":"第五节"},"text":{"zh":"收养关系登记手续\n1. 申请登记收养关系者向户籍登记机构提交固定模板的表单和能证明父子或母子关系的证明、 物品或其他证据。登记越南公民与外国人之间或外国人之间的收养关系必须附加能够证明身份的护照副本或能够代替护照的有效证件。\n2. 依照本条第 1 款的规定， 自收齐证明之日起 15 日内， 户籍工作人员进行确认， 将收养关系在县级人民委员会驻地连续公示 7 天， 同时把文件发到被收养者常住地的乡级人民委员会， 提议其在乡级人民委员会驻地连续公示 7 天。\n3. 司法办上报和提议县级人民委员会主席对登记收养关系作出规定， 若满足条件， 由县级人民委员会主席办理。\n4. 登记收养关系时， 各方都必须在场， 户籍工作人员将收养关系信息登记到户籍册中， 与各方一同在上面签字， 县级人民委员会主席为各方颁发摘录。\n第五节  户籍变更、 更正、 补充与民族重新确认"}},{"id":"VN-H070-A45","no":45,"noLabel":{"zh":"第45条"},"chapter":{"zh":"第五节"},"text":{"zh":"户籍变更范围户籍变更范围适用本法第 26 条的规定。\n·15·"}},{"id":"VN-H070-A46","no":46,"noLabel":{"zh":"第46条"},"chapter":{"zh":"第五节"},"text":{"zh":"户籍变更、 更正、 补充与民族重新确认办理权限\n1. 对于已经在越南权力机构登记过户籍的外国人， 此前户籍登记地或本人居住地的县级人民委员会有权办理户籍变更、 更正和补充业务。\n2. 定居在国外的越南人此前登记户籍的县级人民委员会有权办理户籍变更、 更正、 补充与民族重新确认。\n3. 个人居住地或此前登记户籍的县级人民委员会有权为满 14 岁及以上居住在国内的越南公民办理户籍变更、 更正， 同时具有民族重新确认办理权限。"}},{"id":"VN-H070-A47","no":47,"noLabel":{"zh":"第47条"},"chapter":{"zh":"第六节"},"text":{"zh":"户籍变更、 更正、 补充与民族重新确认办理手续\n1. 户籍变更、 更正办理手续适用本法第28 条的规定。\n申请民族确认必须依照法律规定提交证明， 办理手续依照本法第 28 条的规定进行。\n2. 补充户籍信息的办理手续适用本法第 29 条的规定。\n第六节  在户籍册中登记国外权力机构为越南公民办理的户籍信息"}},{"id":"VN-H070-A48","no":48,"noLabel":{"zh":"第48条"},"chapter":{"zh":"第六节"},"text":{"zh":"在户籍册中登记国外权力机构为越南公民办理的户籍信息的权限\n1. 越南公民居住地的县级人民委员会将国外权力机构办理的出生、 结婚、 监护关系、 收养关系、 户籍变更登记到户籍册中。\n2. 此前的结婚登记地或被备注地的县级人民委员会在户籍册中登记个人在国外办理的离婚、 取消婚姻业务。\n3. 依照本法第 33 条第 1 款的规定， 死亡登记责任人居住地的县级人民委员会在户籍册中登记国外权力机构办理的个人离婚、 取消婚姻业务。"}},{"id":"VN-H070-A49","no":49,"noLabel":{"zh":"第49条"},"chapter":{"zh":"第六节"},"text":{"zh":"在户籍册中登记出生、 监护关系、 收养关系、 亲子关系、 户籍变更、 死亡的手续\n1. 申请在户籍册中登记出生、 监护关系、 收养关系、 亲子关系、 户籍变更、 死亡等信息， 必须向户籍登记机构提交固定模板的表单以及能够说明这些事宜已在国外权力机构办理的证明副本。\n2. 依照本条第 1 款的规定， 收齐证明后， 户籍工作人员进行检查， 若符合规定， 则将这些信息登记到户籍册中， 司法办上报县级人民委员会主席为申请人颁发摘录。\n需必须确认的情况， 处理期限不超过3 个工作日。"}},{"id":"VN-H070-A50","no":50,"noLabel":{"zh":"第50条"},"chapter":{"zh":"第七节"},"text":{"zh":"在户籍册中登记结婚、 离婚和取消婚姻的手续\n1. 申请在户籍册中登记结婚、 离婚和取消婚姻等信息， 必须向户籍登记机构提交固定模板的表单以及能够说明这些事宜已在国外权力机构办理的证明副本。\n“一带一路”法律查明     第 3 卷 ·16·\n2. 依照本条第 1 款的规定， 自收齐档案之日起 12 日内， 若满足法律规定的条件， 户籍工作人员将这些信息登记到户籍册中， 司法办上报县级人民委员会主席为申请人颁发摘录。\n3. 政府对各机构实施本条例的程序、 手续和时间作了具体规定。\n第七节  死亡登记"}},{"id":"VN-H070-A51","no":51,"noLabel":{"zh":"第51条"},"chapter":{"zh":"第七节"},"text":{"zh":"死亡登记权限\n1. 死者最后居住地的县级人民委员会为定居在越南国内的外国人或越南公民办理死亡登记。\n2. 依照本条第 1 款的规定， 不确定死者最后居住地的情况， 由死者死亡地或尸体发现地的县级人民委员会办理死亡登记。"}},{"id":"VN-H070-A52","no":52,"noLabel":{"zh":"第52条"},"chapter":{"zh":"第四章"},"text":{"zh":"死亡登记手续\n1. 死亡登记申请人向户籍登记机构提交固定模板的表单和死亡通知书或代替死亡通知书的其他证明。\n2. 依照本条第 1 款的规定， 收齐证明后， 若死亡登记申请属实， 司法– 户籍工作人员在户籍册中登记死亡信息， 与死亡登记申请人一同在上面签字， 司法办上报县级人民委员会主席为其颁发摘录。\n需要确认的情况， 处理期限不超过3 个工作日。\n3. 登记死亡后， 县级人民委员会必须以文件附带户籍摘录的形式上报外交部， 外交部再通报死者公民身份所属国的权力机构。\n若死者是定居在国外的越南公民， 则户籍工作人员在电子户籍数据库中锁定死者的户籍信息。\n第四章  代表机构户籍登记"}},{"id":"VN-H070-A53","no":53,"noLabel":{"zh":"第53条"},"chapter":{"zh":"第四章"},"text":{"zh":"居住在国外的越南公民登记户籍\n1. 依照本法第 3 条的规定， 若登记事宜不违反接收国的法律和越南作为成员国签署的国际条约， 代表机构为居住在国外的越南公民办理户籍登记。\n2. 根据本法的规定， 外交部配合司法部， 为居住在国外的越南公民将登记户籍的权限、 手续以及申请户籍摘录等事宜传达到代表机构。"}},{"id":"VN-H070-A54","no":54,"noLabel":{"zh":"第54条"},"chapter":{"zh":"第四章"},"text":{"zh":"代表机构的户籍工作人员\n1. 指定参赞、 领事的代表机构为居住在国外的越南公民办理户籍登记。\n·17·\n2. 负责户籍工作的参赞、 领事除了要符合其职位的条件和要求外， 在办理户籍登记业务前， 还必须进行户籍登记的业务培训。"}},{"id":"VN-H070-A55","no":55,"noLabel":{"zh":"第55条"},"chapter":{"zh":"第四章"},"text":{"zh":"外交部编制户籍册外交部编制户籍册以完整记录、 更新、 统一管理居住在国外的越南公民在代表机构登记的户籍信息， 及作为颁发户籍摘录副本的根据。"}},{"id":"VN-H070-A56","no":56,"noLabel":{"zh":"第56条"},"chapter":{"zh":"第五章"},"text":{"zh":"代表机构的上报责任为居住在国外的越南公民登记户籍后， 代表机构有责任以文件附带户籍摘录副本的形式上报外交部将其登记到户籍册中， 及时更新电子户籍数据库中的信息。\n第五章  户籍数据库、 颁发户籍摘录第一节  户籍数据库"}},{"id":"VN-H070-A57","no":57,"noLabel":{"zh":"第57条"},"chapter":{"zh":"第五章"},"text":{"zh":"户籍数据库\n1. 户籍数据库是国家财产， 保存了所有人的户籍信息， 是保障个人合法权利和利益的基础， 为信息查询、 管理， 制定国家社会经济发展政策提供服务。\n2. 户籍数据库包括户籍册和电子户籍数据库， 是颁发户籍摘录的根据。"}},{"id":"VN-H070-A58","no":58,"noLabel":{"zh":"第58条"},"chapter":{"zh":"第五章"},"text":{"zh":"户籍册\n1. 户籍册是在电子户籍数据库中编辑、 更新、 调整个人户籍信息的法理根据。\n每种户籍信息必须登记到一份册子中， 每一页都必须盖上骑缝章； 依照法律规定， 户籍册被永久保存。\n2. 封锁户籍册在每年的最后一天进行， 封锁时必须清楚记录已登记户籍的总页数和信息总量， 由户籍登记机构负责人签字、 盖章。\n在登记户籍时提交的证明、 物品或其他证据必须按照相关保存法律的规定进行保存管理。\n3. 户籍登记机构有责任保存管理户籍册、 证明、 物品或其他与户籍登记相关的证据。"}},{"id":"VN-H070-A59","no":59,"noLabel":{"zh":"第59条"},"chapter":{"zh":"第五章"},"text":{"zh":"电子户籍数据库\n1. 编制电子户籍数据库以保存、 更新、 管理、 查询户籍信息， 服务在线户籍登记需求， 为全国人口数据库提供、 传送个人的基本户籍信息。\n2. 政府对以下事宜作出规定： 各部门、 各部级机构与各级人民委员会在管理、 使用电子户籍数据库时相互配合， 在线登记户籍的手续、 程序， 电子户籍数据库与全国人口数据库之间的信息对接、 交换。\n“一带一路”法律查明     第 3 卷 ·18·"}},{"id":"VN-H070-A60","no":60,"noLabel":{"zh":"第60条"},"chapter":{"zh":"第五章"},"text":{"zh":"更新、 调整电子户籍数据库中的个人户籍信息\n1. 个人户籍信息登记到户籍册中后， 必须及时、 完整、 准确地登记到电子户籍数据库中； 户籍登记机构对电子户籍数据库中更新的所有户籍信息负责。\n2. 若电子户籍数据库、 全国人口数据库中的信息与户籍册中的信息有出入， 必须作出调整以符合户籍册中的信息。"}},{"id":"VN-H070-A61","no":61,"noLabel":{"zh":"第61条"},"chapter":{"zh":"第二节"},"text":{"zh":"户籍数据库管理与使用原则\n1. 根据法律规定， 户籍数据库被秘密保存管理以保障其安全性， 只有具有权限的机构、 组织和个人才能接触和使用。\n2. 户籍数据库的管理机构有责任对户籍数据库中的个人信息保密。\n第二节  颁发户籍摘录"}},{"id":"VN-H070-A62","no":62,"noLabel":{"zh":"第62条"},"chapter":{"zh":"第二节"},"text":{"zh":"登记户籍时颁发户籍摘录原件\n1. 登记户籍时， 除了出生登记和结婚登记， 户籍登记机构为户籍登记申请人颁发 1 本户籍摘录原件。\n2. 户籍摘录原件能够以副本证实。"}},{"id":"VN-H070-A63","no":63,"noLabel":{"zh":"第63条"},"chapter":{"zh":"第二节"},"text":{"zh":"为已登记的户籍信息颁发户籍摘录副本流动人口有权要求户籍数据库的管理机构为已登记的户籍信息颁发户籍摘录副本。"}},{"id":"VN-H070-A64","no":64,"noLabel":{"zh":"第64条"},"chapter":{"zh":"第六章"},"text":{"zh":"颁发户籍摘录副本手续\n1. 本人直接申请颁发户籍摘录副本或通过代表人向户籍数据库的管理机构提交固定模板的表单。\n若拥有权限的机构、 组织提议颁发个人户籍摘录副本， 需向户籍数据库的管理机构提交理由清晰的申请文件。\n2. 在接到申请后， 若满足条件， 由户籍数据库的管理机构为申请人颁发户籍摘录副本。\n第六章  国家对户籍及户籍工作人员的管理责任第一节  国家的户籍管理责任"}},{"id":"VN-H070-A65","no":65,"noLabel":{"zh":"第65条"},"chapter":{"zh":"第六章"},"text":{"zh":"政府责任\n1. 政府统一管理国家户籍， 司法部协助政府管理国家户籍。\n2. 国家户籍的管理内容包括：\n（a） 颁布或呈递给权力机构户籍登记和管理的法律规范文本， 并组织实施；\n·19· （b） 在登记和管理户籍的过程中运用信息技术， 建立和管理电子户籍数据库；\n（c） 清查投诉、 告发事件， 处理在登记和管理户籍过程中的违法行为；\n（d） 户籍统计；\n（đ） 户籍国际合作。"}},{"id":"VN-H070-A66","no":66,"noLabel":{"zh":"第66条"},"chapter":{"zh":"第六章"},"text":{"zh":"司法部的责任司法部管理国家户籍， 具有以下任务和权限：\n1. 对国内的户籍工作人员进行登记， 管理工作的规定、 指导、 培训。\n2. 颁发、 指导使用和管理户籍册、 出生证、 结婚证、 户籍摘录和其他户籍样表， 对流动人口登记出生、 结婚、 死亡的条件和程序作出具体规定。\n3. 建立和统一管理电子户籍数据库， 指导地方机构管理、 使用户籍登记与管理软件、 电子户籍数据库， 为全国人口数据库提供个人的基本户籍信息。\n4. 每年综合户籍情况， 分析、 评价、 统计后报告给政府。"}},{"id":"VN-H070-A67","no":67,"noLabel":{"zh":"第67条"},"chapter":{"zh":"第六章"},"text":{"zh":"外交部的责任\n1. 外交部与司法部配合进行代表机构的国家户籍管理工作， 具有以下任务和权力：\n（a） 规定、 指导、 清查各代表机构的户籍登记和管理工作；\n（b） 为参赞、 领事组织户籍业务培训；\n（c） 编制户籍册以管理在代表机构登记的越南公民户籍信息；\n（d） 更新、 使用电子户籍数据库， 依照法律规定颁发户籍摘录副本；\n（đ） 按照政府规定， 综合户籍情况， 统计代表机构的户籍信息， 上报司法部。\n2. 代表机构对居住在国外的越南公民进行国家户籍管理， 具有以下任务和权限：\n（a） 按照相关户籍法律、 领事法律和国际条约的规定， 为居住在国外的越南公民办理户籍登记。\n（b） 为参赞和领事分配在代表机构的户籍登记和管理任务。\n（c） 按照规定管理、 使用户籍册和户籍样表。\n（d） 按照规定管理、 更新和使用电子户籍数据库， 颁发户籍摘录副本。\n（đ） 向外交部上报户籍登记内容， 以便更新到户籍数据库中。\n（e） 按照规定综合户籍情况， 进行户籍统计， 上报外交部。\n（g） 保存与户籍登记相关的证明、 物品或其他证据。\n（h） 按照权限处理投诉、 告发事件以及在户籍工作中出现的违法行为。\n依照本条第 2 款 第（a）项 、 第（c）项 、 第（d）项 、 第（đ）项、第 （e）项 、 第（g） 项的规定， 负责户籍工作的参赞、 领事有责任协助代表机构履行任务， 行使权力。\n“一带一路”法律查明     第 3 卷 ·20·"}},{"id":"VN-H070-A68","no":68,"noLabel":{"zh":"第68条"},"chapter":{"zh":"第六章"},"text":{"zh":"公安部的责任公安部主管， 配合司法部、 外交部和各部门履行、 行使以下任务和权力：\n1. 按照法律规定， 保证全国人口数据库与电子户籍数据库的连通；\n2. 保证电子户籍数据库中的信息安全；\n3. 履行与户籍工作相关的其他任务。"}},{"id":"VN-H070-A69","no":69,"noLabel":{"zh":"第69条"},"chapter":{"zh":"第六章"},"text":{"zh":"省人民委员会、 中央直辖市的责任\n1. 省人民委员会、 中央直辖市 （以下简称 “省级人民委员会” ） 负责地方的国家户籍管理工作， 具有以下任务和权限：\n（a） 指导户籍登记和管理工作的组织实施；\n（b） 组织宣传、 普及相关户籍法律；\n（c） 根据政府的规定， 对县级、 乡级的户籍工作人员分配作出规定， 为户籍登记和管理工作提供物质保障；\n（d） 按照规定管理、 更新和使用电子户籍数据库；\n（đ） 依照权限清查、 处理投诉、 告发事件以及在户籍工作中出现的违法行为；\n（e） 除非法结婚外， 收回、 销毁由县级人民委员会颁发的违反本法规定的户籍证明；\n（g） 为户籍工作人员定期组织户籍业务培训；\n（h） 按照规定综合户籍情况， 进行户籍统计， 上报司法部。\n2. 司法厅协助省级人民委员会履行本条第 1 款 第（a）项 、第（b）项 、第（d）项 、第 （đ）项 、第 （g）项 、 第（h） 项赋予的任务和权限。\n3. 户籍登记、 管理工作以及在户籍登记、 管理工作中由于管理疏漏而出现的违法行为， 由省级人民委员会主席承担责任。"}},{"id":"VN-H070-A70","no":70,"noLabel":{"zh":"第70条"},"chapter":{"zh":"第六章"},"text":{"zh":"县级人民委员会的责任\n1. 县级人民委员会负责地方的国家户籍管理工作， 具有以下任务和权限：\n（a） 按照本法规定进行户籍登记；\n（b） 指导、 检查乡级人民委员会的户籍登记和管理工作；\n（c） 组织宣传、 普及相关户籍法律规定；\n（d） 按照规定管理、 使用户籍册和户籍样表；\n（đ） 根据省级人民委员会的规定， 分配户籍工作人员；\n（e） 按照规定管理、 更新和使用电子户籍数据库， 颁发户籍摘录副本；\n（g） 依照权限清查、 处理投诉、 告发事件以及在户籍工作中出现的违法行为；\n（h） 除非法结婚外， 收回、 销毁由乡级人民委员会颁发的违反本法规定的户籍证明；\n·21· （i） 按照政府规定， 综合户籍情况， 进行户籍统计， 上报省级人民委员会；\n（k） 保存户籍册和户籍登记档案。\n2. 司法办协助县级人民委员会履行本条第 1 款 第（a）项 、第（b）项 、第（c）项 、第 （d）项 、 第（e）项 、 第（g）项 、 第（i）项 、 第（k） 项赋予的任务和权限。\n3. 依照本法"}},{"id":"VN-H070-A71","no":71,"noLabel":{"zh":"第71条"},"chapter":{"zh":"第二节"},"text":{"zh":"的规定， 对于没有设立乡级行政单位的县级行政单位， 除了履行县级人民委员会的户籍登记和管理的任务和权限外， 还要履行乡级人民委员会的户籍登记和管理的任务和权限。\n4. 户籍登记、 管理工作以及在户籍登记、 管理工作中由于管理疏漏而出现的违法行为， 由县级人民委员会主席承担责任。\n第七十一条  乡级人民委员会的责任\n1. 乡级人民委员会负责地方的国家户籍管理工作， 具有以下任务和权限：\n（a） 按照本法规定进行户籍登记；\n（b） 根据上级人民委员会的规定， 分配司法– 户籍工作人员办理户籍登记；\n（c） 宣传、 普及相关户籍法律；\n（d） 按照规定管理、 使用户籍册和户籍样表；\n（đ） 按照规定管理、 更新和使用电子户籍数据库， 颁发户籍摘录副本；\n（e） 按照政府规定， 综合户籍情况， 进行户籍统计， 上报县级人民委员会；\n（g） 保存户籍册和户籍登记档案；\n（h） 依照权限处理投诉、 告发事件以及在户籍工作中出现的违法行为。\n2. 乡级人民委员会主席时常指导、 督促出生、 死亡登记事宜， 对户籍登记、 管理工作以及在户籍登记、 管理工作中由于管理疏漏而出现的违法行为承担责任。\n乡级司法 – 户籍工作人员履行本条第 1 款 第（a）项 、 第（c）项 、 第（d）项 、 第（đ）项 、 第 e）项 、 第（g） 项赋予的任务和权限。\n第二节  户籍工作人员"}},{"id":"VN-H070-A72","no":72,"noLabel":{"zh":"第72条"},"chapter":{"zh":"第二节"},"text":{"zh":"户籍工作人员\n1. 户籍工作人员包括乡级司法 – 户籍工作人员、 隶属县级人民委员会的司法办户籍工作人员、 代表机构中负责户籍工作的参赞和领事。\n2. 乡级司法 – 户籍工作人员需达到以下标准：\n（a） 具有中级法律专业毕业以上学历， 已进行过户籍业务培训；\n（b） 字迹清晰， 具有符合工作要求的计算机水平。\n“一带一路”法律查明     第 3 卷 ·22·\n3. 司法办的户籍工作人员必须具有法律学士学位以上学历， 已进行过户籍业务培训。\n4. 在代表机构负责户籍工作的参赞、 领事必须进行过户籍业务培训。"}},{"id":"VN-H070-A73","no":73,"noLabel":{"zh":"第73条"},"chapter":{"zh":"第二节"},"text":{"zh":"户籍工作人员的任务和权限\n1. 在户籍工作中， 乡级司法– 户籍工作人员具有以下任务和权限：\n（a） 遵守本法的规定以及与户籍相关的其他法律规定。\n（b） 在乡级人民委员会之前承担责任， 且承担户籍登记的法律责任。\n（c） 宣传、 普及、 动员人民遵守户籍法律的规定。\n（d） 协助乡级人民委员会及时、 准确、 客观、 真实地登记户籍， 在电子户籍数据库中将已登记的户籍信息更新完整。\n（đ） 主动进行审查工作， 以便及时登记管辖范围的出生、 死亡信息。\n对于居民分散、 出行条件艰苦、 距离乡级人民委员会驻地较远的管辖地区， 司法– 户籍工作人员上报乡级人民委员会， 由后者组织对出生、 结婚、 死亡等进行流动登记。\n（e） 经常提升法律知识水平以提高户籍登记业务能力， 参加由人民委员会或上级司法机构组织的各种业务专门培训。\n（g） 主动报告、 提议同级人民委员会配合各机构和组织审查、 确认户籍信息； 在进行户籍登记时， 要求各机构、 组织、 个人提供验证信息； 配合公安机构， 共同为全国人口数据库提供个人的基本户籍信息。\n2. 根据自身任务和权限， 本条第 1 款的规定也适用于司法办的户籍工作人员、 在代表机构负责户籍工作的参赞和领事。"}},{"id":"VN-H070-A74","no":74,"noLabel":{"zh":"第74条"},"chapter":{"zh":"第二节"},"text":{"zh":"户籍工作人员的禁止行为\n1. 进行户籍登记和管理时横行霸道、 打官腔、 勒索、 拖延、 制造麻烦、 收受贿赂。\n2. 进行户籍登记时收取比规定额度高的户籍手续费。\n3. 违反本法规定制定手续和证明， 故意延长户籍登记期限。\n4. 删除、 修改、 弄错户籍数据库中的信息。\n5. 违反本法规定登记、 颁发证明。\n6. 泄露通过登记户籍而得知的个人隐私。\n7. 按照法律规定， 违反本条规定的户籍工作人员根据违反的性质和程度可处以纪律处分或追究刑事责任。\n·23· 第七章  实施条款"}},{"id":"VN-H070-A75","no":75,"noLabel":{"zh":"第75条"},"chapter":{"zh":"第二节"},"text":{"zh":"在本法生效之前编制和颁发的户籍册和户籍证明的价值\n1. 在本法生效之前保留下来的户籍册仍然能够作为证明个人户籍信息， 查询、 颁发户籍摘录， 开具婚姻状况确认表的根据。\n2. 在本法生效之前按照相关户籍法律规定颁发给个人的户籍证明仍具有使用价值。"}},{"id":"VN-H070-A76","no":76,"noLabel":{"zh":"第76条"},"chapter":{"zh":"第二节"},"text":{"zh":"转交条款\n1. 在本法生效之前受理而没有办理完的户籍登记档案， 按照接收时的户籍法律规定继续办理。\n2. 政府对重新登记在本法生效之前办理的出生、 死亡、 结婚等作出具体规定。\n3. 政府对以下工作进行指导：\n为确保本法赋予的任务和权力得以履行和行使而进行的户籍业务审查和培训、 户籍工作人员队伍健全等工作； 规定出生、 结婚登记手续； 向越南公民颁发婚姻状况证明； 全国人口数据库建设完成前过渡时期的户籍册制作、 管理和使用制度， 最至至 2020 年 1 月 1 日， 必须依照本法在全国统一实施。"}},{"id":"VN-H070-A77","no":77,"noLabel":{"zh":"第77条"},"chapter":{"zh":"第二节"},"text":{"zh":"实施效力\n1. 本法自 2016 年 1 月 1 日起生效。\n2. 具有权限的政府、 机构对本法中的条款作出具体规定。\n2014 年 11 月 20 日， 第十三届越南社会主义共和国国会第八次会议通过本法。\n国会主席签字： 阮生雄国家主席办 原件复印本  河内，2014 年 12 月 4 日 （KT） 国家主席办公室文件号： 国家主席办复印本32 号 常务副主任国家主席办章江山"}}],"pack":"vn-p03","rebuiltFrom":"原为单条全文，2026-10-24 按条号标记重新切分（拼接无损校验通过）"};
  FT["VN-H071"] = {"id":"VN-H071","coverage":"full","language":"zh","sourceName":"越南官方发布渠道","sourceUrl":"","fetchedAt":"2026-10-04","articleCount":8,"structureMode":"ARTICLE","title":{"zh":"居住法","en":"Law on Residence","orig":null},"level":"law","status":"active","docNumber":"年份不详","issuingBody":"越南官方发布渠道","completenessNote":"全文，共 8 条；取自《东盟法律分类》归档中的 PDF 原件，逐字未改写。","country":"VN","countryName":"越南","layer":"intl","articles":[{"id":"VN-H071-A1","no":1,"noLabel":{"zh":"第 1 条"},"heading":{"en":"对第十三届国会 2014 年通过的第 59 号法律 《公民身份证法》 第9 条第 1 款进行"},"text":{"zh":"修改、 补充：\n“1. 接收、 更新的信息内容包括：\n（1） 姓氏、 垫字、 名 （tên khai sinh）；\n（2） 出生年月日；\n（3） 性别；\n（4） 出生所在地；\n（5） 籍贯；\n（6） 民族；\n（7） 宗教；\n（8） 国籍；\n（9） 婚姻情况；\n（10） 常住地；\n（11） 暂住地；\n（12） 暂离登记情况；\n（13） 现居住地；\n（14） 血型， 当公民要求更新和出具本人血型检查结果；\n（15） 父母、 配偶或合法代理人的姓氏、 垫字、 名、 新版身份证号或旧版身份证号、 国籍；\n（16） 家庭成员的姓氏、 垫字、 名、 新版身份证号或旧版身份证号、 国籍；\n（17） 死亡或失踪年月日。 ” “一带一路”法律查明     第 3 卷 ·94·"}},{"id":"VN-H071-A2","no":2,"noLabel":{"zh":"第 2 条"},"heading":{"en":"根据第十四届国会 2014 年通过的第 46 号法律、 第十三届国会 2015 年通过的第"},"text":{"zh":"97 号法律和第十四届国会 2018 年通过的第 35 号法律对第十二届国会 2008 年通过的第 25 号法律 《医疗保险法》 第2 条第 7 款进行如下修改、 补充：\n“7. 参加医疗保险家庭 （以下简称 “家庭” ） 是根据居住法律规定在同一合法居住地点常住登记或暂住登记的人。 ”"}},{"id":"VN-H071-A3","no":3,"noLabel":{"zh":"第 3 条"},"heading":{"zh":"自本法生效实施之日起， 已发放的户口簿、 暂住簿仍在使用且同居住确认证件、 材"},"text":{"zh":"终止第十三届国会 2012 年通过的第 25 号法律 《首都法》 第19 条第 3 款和第 4 款。"}},{"id":"VN-H071-A4","no":4,"noLabel":{"zh":"第 4 条"},"heading":{"zh":"中央政府、 部委、 部级机关和其他有关机关应当审查属于其发布职权范围内的法"},"text":{"zh":"终止第十二届国会 2009 年通过的第 28 号法律 《司法履历法》 第45 条第 1 款。\n第三十八条  实行条款"}},{"id":"VN-H071-A1-d2","no":1,"noLabel":{"zh":"第 1 条"},"text":{"zh":"本法自 2021 年 7 月 1 日起生效实施。"},"dupIndex":2},{"id":"VN-H071-A2-d2","no":2,"noLabel":{"zh":"第 2 条"},"heading":{"en":"第十一届国会 2006 年通过的第 81 号法律的部分条款已根据第十三届国会 2013"},"text":{"zh":"年通过的第 36 号法律进行修改、 补充部分， 并从本法生效实施之日起失去法律效力。"},"dupIndex":2},{"id":"VN-H071-A3-d2","no":3,"noLabel":{"zh":"第 3 条"},"heading":{"en":"自本法生效实施之日起， 已发放的户口簿、 暂住簿仍在使用且同居住确认证件、 材"},"text":{"zh":"料， 根据本法规定， 于2022 年 12 月 31 日失效。\n户口簿、 暂住证与居住数据库信息不一致的则使用居住数据库中的信息。\n公民进行居住登记时导致户口簿、 暂住簿信息变更的则居住登记机关负责收回已发放的户口簿、 暂住证， 根据本法规定在居住数据库更改、 更新信息， 不可新发放、 返还户口簿、 暂住簿。"},"dupIndex":2},{"id":"VN-H071-A4-d2","no":4,"noLabel":{"zh":"第 4 条"},"heading":{"en":"中央政府、 部委、 部级机关和其他有关机关应当审查属于其发布职权范围内的法"},"text":{"zh":"律文件， 其中记载有与户口簿、 暂住簿有关的规定或者是否符合本法规定的， 限制使用居住地信息是执行行政程序的一个条件。\n2020 年 11 月 13 日， 第十五届越南社会主义共和国第10 次会议通过本法。\n国会主席签字： 阮氏金银国家主席办原件复印本 河内，2020 年 12 月 4 日"},"dupIndex":2}],"pack":"vn-p03"};
  FT["VN-H072"] = {"id":"VN-H072","coverage":"full","language":"zh","sourceName":"越南官方发布渠道","sourceUrl":"","fetchedAt":"2026-10-04","articleCount":64,"structureMode":"ARTICLE","title":{"zh":"传染病防控法","en":"Law on Prevention and Control of Infectious Diseases","orig":null},"level":"law","status":"active","docNumber":"年份不详","issuingBody":"越南官方发布渠道","completenessNote":"文本未能可靠切分为条文（或原件为目录式排版），按整篇收录，未作改写。","country":"VN","countryName":"越南","layer":"intl","articles":[{"id":"VN-H072-A1","no":1,"noLabel":{"zh":"第1条"},"chapter":{"zh":"第一章"},"text":{"zh":"“一带一路”法律查明     第 3 卷 ·60· 越南社会主义共和国传染病防控法国会 2007 年 11 月 21 日第 03/2007/QH12 号 《传染病防控法》 ， 自2008 年 7 月 1 日起生效， 经过以下修订和补充：\n1. 国会 2008 年 6 月 3 日第 15/2008/QH12 号 《财产征购、 征用法》 ， 自2009 年 1 月 1 日起生效；\n2. 国会 2018 年 11 月 20 日第 35/2018/QH14 号《 对37 部与规划有关的法律中若干条款的修订、 补充法》 ， 自2019 年 1 月 1 日起生效。\n根据第 51/2001/QH10 号决议修订、 补充若干条款的 1992 年 《越南社会主义共和国宪法》 ， 国会颁布 《传染病防控法》 。\n第一章  总则\n调整范围， 适用对象\n1. 本法规定传染病防控、 边界医疗检疫、 抗疫、 人类传染病防控工作的保障条件。\n对由艾滋病病毒感染引起的人体获得性免疫缺陷综合征 （ HIV/AIDS） 的防控不属于本法调整范围。\n2. 本法适用于国内机构、 组织、 个人及越南境内的国外机构、 组织、 个人。"}},{"id":"VN-H072-A2","no":2,"noLabel":{"zh":"第2条"},"chapter":{"zh":"第一章"},"text":{"zh":"词语解释在本法中， 下列词语解释如下：\n1. 传染病， 是指通过传染病病原体在人与人之间或动物与人之间直接或间接传播的疾病。\n2. 传染病病原体， 是指可能引发传染病的病毒、 细菌、 寄生虫和真菌。\n3. 疾病传播媒介， 是指昆虫、 动物、 环境、 食品和其他携带传染病病原体并可能传播疾病的物体。\n4. 传染病患者， 是指感染传染病病原体并表现出疾病症状的人。\n* 译者： 陶文文， 北京外国语大学亚洲学院博士生。\n* ·61· 越南社会主义共和国传染病防控法\n5. 传染病病原携带者， 是指携带传染病病原体但没有疾病症状的人。\n6. 接触者， 是指与传染病患者、 传染病病原携带者、 疾病传播媒介有过接触并有可能感染疾病的人。\n7. 疑似传染病病人， 是指接触者或表现出传染病症状但病原体不明的人。\n8. 传染病监测， 是指持续地、 系统地收集与传染病情况和趋势有关的信息， 进行分析和解释， 为制订计划、 有效开展和评估传染病防控措施提供信息。\n9. 检验生物安全， 是指采取措施减少或消除检验设施内的传染病病原体从检验设施到环境和社会的向外传播风险。\n10. 疫苗， 是指含有抗原的制剂， 可使身体产生免疫反应， 用于预防疾病。\n11. 医疗生物制品， 是指用于预防、 治疗和诊断人体疾病的生物来源产品。\n12. 免疫状态， 是指个人或社会对某种传染病病原体的抵抗程度。\n13. 疫情， 是指在特定地点的确定时间段内出现感染人数超过正常预期感染人数的传染病的情况。\n14. 疫区， 是指被职权机构确定为有疫情的地区。\n15. 疫情风险区， 是指疫区附近地区或出现引发疫情因素的地区。\n16. 医疗隔离， 是指将传染病患者、 疑似传染病病人、 传染病病原携带者或可能携带传染病病原体的物体进行隔离， 限制疾病的传播。\n17. 医疗处理， 是指采取使用疫苗、 医疗生物制品、 医疗隔离、 消毒、 消灭传染病病原体和疾病传染媒介的措施和其他医疗措施。"}},{"id":"VN-H072-A3","no":3,"noLabel":{"zh":"第3条"},"chapter":{"zh":"第一章"},"text":{"zh":"传染病的分类\n1. 传染病包括以下种类：\n（1）A 类包括可以快速传染、 大范围散播且死亡率高或病原体不明的特别危险的传染病。\nA 类传染病包括小儿麻痹症， 甲型H5N1 禽流感， 鼠疫， 天花， 由埃博拉 （Ebola）、 拉沙（Lassa） 或马尔堡 （Marburg） 病毒引起的出血热， 西尼罗河热 （Nile） ， 黄热病， 霍乱， 由病毒和病原体不明的新发危险传染病引起的严重急性呼吸道感染疾病。\n（2）B 类包括可以快速传染并引起死亡的严重传染病。\nB 类传染病包括腺病毒病 （Adeno） ， 由艾滋病病毒引起的人体获得性免疫缺陷综合征（HIV/AIDS） ， 白喉， 流感， 狂犬病， 百日咳， 肺结核病， 人体猪链球菌病， 阿米巴痢疾 （Amibe） ， 细菌性痢疾， 腮腺炎， 登革热 （Dengue）、 登 革 （Dengue） 出血热， 疟疾， 斑疹伤寒， 麻疹， 手足口病， 炭疽病， 水痘， 伤寒， 破伤风， 风疹病 （Rubeon） ， 病毒性肝炎， 脑膜炎 “一带一路”法律查明     第 3 卷 ·62· 球菌病， 病毒性脑炎， 螺旋体性黄疸， 轮状病毒 （Rota） 腹泻。\n（3）C 类包括危险性小、 传播能力慢的传染病。\nC 组传染病包括： 衣原体， 梅毒， 蠕虫病， 淋病， 沙眼， 白色念珠菌 （Candida Albicans）， 诺卡菌病 （Nocardia） ， 麻风， 巨细胞病毒病 （Cytomegalo） ， 病毒性疱疹 （Herpes）， 绦 虫病， 片吸虫病， 肺吸虫病， 肠吸虫病， 恙虫病， 立克次体热， 汉他病毒 （Hanta） 出血热， 毛滴虫病 （Toricomonas） ， 传染性脓疱皮炎， 柯萨奇病毒 （Coxskie） 引起的咽炎、 口腔炎、 心肌炎， 贾第鞭毛虫 （Giardia） 引起的肠炎， 副溶血性弧菌 （Vibrio Parahaemolyticus）引 起的肠炎和其他传染病。\n2. 卫生部部长决定调整和补充本条第 1 款规定的各类传染病目录。"}},{"id":"VN-H072-A4","no":4,"noLabel":{"zh":"第4条"},"chapter":{"zh":"第一章"},"text":{"zh":"传染病防控的原则\n1. 以疾病预防为主， 其中以传染病的通知、 教育、 大众传播、 监测为主要措施。在传染病防控中将医疗专业技术措施与社会和行政措施相结合。\n2. 开展传染病防控的跨部门协调和社会动员， 将传染病防控活动纳入经济社会发展计划。\n3. 公开、 准确、 及时通报疫情。\n4. 主动、 积极、 及时、 彻底开展疫情防控活动。"}},{"id":"VN-H072-A5","no":5,"noLabel":{"zh":"第5条"},"chapter":{"zh":"第一章"},"text":{"zh":"国家的传染病防控政策\n1. 优先、 扶持预防医学专业的培训。\n2. 优先投资于干部队伍能力提升、 传染病检测监测系统、 疫苗和医疗生物制品的研究和生产。\n3. 扶持、 鼓励传染病防控领域的科学研究、 专家交流和培训、 技术转让。\n4. 扶持治疗和护理因职业风险和其他必要情况感染传染病的患者。\n5. 对因依法销毁携带传染病病原体的畜禽所造成的损失予以扶持。\n6. 动员全社会为传染病防控提供财力、 技术和人力贡献。\n7. 扩大与国际组织、 地区和世界各国的传染病防控合作。"}},{"id":"VN-H072-A6","no":6,"noLabel":{"zh":"第6条"},"chapter":{"zh":"第一章"},"text":{"zh":"传染病防控的国家管理机构\n1. 政府对全国范围内的传染病防控工作实行统一管理。\n2. 卫生部对政府负责， 对全国范围内的传染病防控工作实行国家管理。\n3. 各部委、 部级机构在其职权范围内， 有责任配合卫生部对传染病防控工作实行国家管理。\n4. 各级人民委员会根据政府分级， 对传染病防控工作实行国家管理。\n·63· 越南社会主义共和国传染病防控法"}},{"id":"VN-H072-A7","no":7,"noLabel":{"zh":"第7条"},"chapter":{"zh":"第一章"},"text":{"zh":"机构、 组织、 个人在传染病防控工作中的责任\n1. 机构、 组织、 人民武装单位在被交予的职权范围内， 有责任制定和组织落实传染病防控计划； 疫情发生时， 紧密配合、 互相帮助， 并遵守和执行抗疫指导委员会的指导和调度。\n2. 越南祖国阵线及其成员组织有责任宣传、 动员人民群众参与传染病防控， 参与监督传染病防控法律的实施。\n3. 国内机构、 组织、 个人和在越南的外国机构、 组织、 个人有责任根据本法规定参与传染病防控。"}},{"id":"VN-H072-A8","no":8,"noLabel":{"zh":"第8条"},"chapter":{"zh":"第二章"},"text":{"zh":"禁止行为\n1. 故意散播传染病病原体。\n2. 传染病患者、 疑似传染病病人和传染病病原携带者从事法律规定的易传播传染病病原体的工作。\n3. 隐瞒、 不上报或不及时上报法律规定的传染病感染病例。\n4. 故意对传染病进行虚假上报和通知。\n5. 区别对待传染病患者， 传送与传染病患者有关的负面图像、 信息。\n6. 不开展或不及时开展本法规定的传染病防控措施。\n7. 不按职权机构和组织的要求执行传染病防控措施。\n第二章  预防传染病第一目  传染病防控的通知、 教育、 大众传播"}},{"id":"VN-H072-A9","no":9,"noLabel":{"zh":"第9条"},"chapter":{"zh":"第二章"},"text":{"zh":"传染病防控通知、 教育、 大众传播的内容\n1. 党的传染病防控路线和主张， 国家对传染病防控的政策和法律。\n2. 疾病原因、 传染渠道、 识别方法和传染病防控措施。\n3. 传染病对人类健康、 生命和国家经济社会发展带来的后果。\n4. 机构、 组织、 个人在传染病防控中的责任。"}},{"id":"VN-H072-A10","no":10,"noLabel":{"zh":"第10条"},"chapter":{"zh":"第二章"},"text":{"zh":"传染病防控通知、 教育、 大众传播的对象\n1. 任何人都可以接受传染病防控的通知、 教育、 大众传播。\n2. 传染病患者、 疑似传染病病人、 传染病病原携带者及其家庭成员和疫区、 疫情风险区对象可以优先接受传染病防控的通知、 教育、 大众传播。\n“一带一路”法律查明     第 3 卷 ·64·"}},{"id":"VN-H072-A11","no":11,"noLabel":{"zh":"第11条"},"chapter":{"zh":"第二章"},"text":{"zh":"传染病防控通知、 教育、 大众传播的要求\n1. 准确、 清晰、 易懂、 切实、 及时。\n2. 符合对象、 文化传统、 民族、 社会道德、 宗教、 信仰和风俗习惯。"}},{"id":"VN-H072-A12","no":12,"noLabel":{"zh":"第12条"},"chapter":{"zh":"第二章"},"text":{"zh":"传染病防控通知、 教育、 大众传播的责任\n1. 机构、 组织、 人民武装单位在其职权范围内， 有责任开展传染病防控的通知、 教育、 大众传播。\n2. 卫生部有责任主持、 配合相关机构准确地、 及时地提供传染病信息。\n3. 信息和通信部有责任指导大众信息机构经常开展传染病防控的通知和大众传播， 将传染病防控节目纳入其他通知和大众传播节目。\n4. 教育与培训部有责任主持、 配合卫生部、 劳动伤兵与社会部、 有关部委和部级机构制定传染病防控教育内容， 并与其他教育内容相结合。\n5. 各级人民委员会有责任指导、 组织开展面向地方人民群众的传染病防控通知、 教育、 大众传播。\n6. 大众信息机构有责任根据信息和通信部规定， 为广播电台、 电视台的传染病防控通知、 教育、 大众传播优先播出时刻和时长， 为印刷报刊、 影像报刊、 电子报刊的传染病防控通知、 教育、 大众传播优先登载版面和位置。在各类大众信息手段上进行的传染病防控通知、 教育、 大众传播不收取费用， 但按照节日单独合同实行或由国内外组织、 个人赞助的情况除外。\n第二目  预防传染病卫生"}},{"id":"VN-H072-A13","no":13,"noLabel":{"zh":"第13条"},"chapter":{"zh":"第二章"},"text":{"zh":"国民教育系统下属教育单位的预防传染病卫生\n1. 教育单位必须建在干爽、 干净、 远离污染的高处， 有充足的生活用水和卫生设施；\n教室必须通风、 照明充足； 教育单位使用的食品必须确保安全的卫生质量。\n2. 教育单位有责任对学习者进行预防传染病的卫生教育， 包括个人卫生、 生活劳动卫生和环境卫生。\n3. 教育单位的医疗单位负责预防疾病的卫生宣传， 检查、 监测环境卫生、 食品卫生安全， 并开展传染病防控措施。\n4. 卫生部部长颁行本条第 1 款规定的教育单位预防疾病卫生的国家技术标准。"}},{"id":"VN-H072-A14","no":14,"noLabel":{"zh":"第14条"},"chapter":{"zh":"第二章"},"text":{"zh":"净水供应卫生， 生活水源卫生\n1. 净水必须确保符合卫生部部长规定的国家技术标准。\n2. 净水供应单位有责任采取技术措施， 保持环境卫生， 自行检查以确保净水质量。\n·65· 越南社会主义共和国传染病防控法\n3. 国家职权医疗机构有责任经常检查各单位供应的净水的质量， 检查净水供应单位工作人员的定期体检情况。\n4. 各级人民委员会有责任组织落实保护、 保持卫生， 不污染生活水源， 为净水供应创造条件。\n5. 机构、 组织、 个人有责任保护、 保持卫生， 不污染生活水源。"}},{"id":"VN-H072-A15","no":15,"noLabel":{"zh":"第15条"},"chapter":{"zh":"第二章"},"text":{"zh":"养殖、 运输、 屠宰、 销毁禽畜和其他动物的卫生\n1. 养殖、 运输、 屠宰、 销毁禽畜和其他动物必须确保卫生， 不污染环境、 生活水源或不散播传染病病原体。\n2. 国家职权兽医机构有责任指导组织、 个人落实养殖、 运输、 屠宰、 销毁禽畜和其他动物的卫生措施， 避免疾病传染人类。"}},{"id":"VN-H072-A16","no":16,"noLabel":{"zh":"第16条"},"chapter":{"zh":"第二章"},"text":{"zh":"食品安全卫生\n1. 从事食品种植、 养殖、 采收、 捕捞、 初加工、 加工、 包装、 保存、 运输、 买卖的组织和个人有责任确保食品不受传染病病原体感染， 并执行食品安全卫生法律的规定。\n2. 消费者有权获得食品安全卫生的信息， 有责任落实食品安全卫生， 充分执行食品安全卫生的指导， 上报食物中毒和食源性疾病。\n3. 国家食品安全卫生职权机构有责任指导组织、 个人采取措施确保食品安全卫生， 以防控传染病。"}},{"id":"VN-H072-A17","no":17,"noLabel":{"zh":"第17条"},"chapter":{"zh":"第二章"},"text":{"zh":"建造卫生\n1. 建造工程时必须遵守卫生部部长规定的国家建造卫生标准。\n2. 工业园区、 城区、 集中居住区、 传染病诊疗单位的投资建造项目， 必须在职权医疗机构审定健康影响评估报告后， 方可建造。\n3. 传染病诊疗单位、 有传染病病原体传染风险的单位必须根据卫生部部长的规定， 与居住区、 自然保护区保持环境安全距离。\n4. 机构、 组织、 个人有责任落实建造卫生保障事项。"}},{"id":"VN-H072-A18","no":18,"noLabel":{"zh":"第18条"},"chapter":{"zh":"第二章"},"text":{"zh":"停放、 防腐、 埋葬、 转移尸体和骸骨的卫生\n1. 死者必须在死亡后 48 小时内埋葬， 但按照卫生部部长的规定保存尸体的情况除外； 传染病患者或疑似A 类传染病病人死亡的， 尸体必须在24 小时内进行灭菌并埋葬。\n2. 尸体和骸骨的保存、 停放、 防腐、 埋葬、 转移事项按照卫生部部长的规定执行。"}},{"id":"VN-H072-A19","no":19,"noLabel":{"zh":"第19条"},"chapter":{"zh":"第二章"},"text":{"zh":"预防传染病卫生中的其他活动\n1. 机构、 组织、 个人必须执行居住地、 公共单位、 生产经营单位、 交通方式卫生和处理工业、 生活废物的保障措施以及法律规定的其他保障措施， 不使传染病发生和蔓延。\n“一带一路”法律查明     第 3 卷 ·66·\n2. 任何人都有责任做好个人卫生， 预防传染病。\n第三目  传染病监测"}},{"id":"VN-H072-A20","no":20,"noLabel":{"zh":"第20条"},"chapter":{"zh":"第二章"},"text":{"zh":"传染病监测活动\n1. 监测传染病感染、 疑似感染和病原携带病例。\n2. 监测传染病病原体。\n3. 监测疾病传播媒介。"}},{"id":"VN-H072-A21","no":21,"noLabel":{"zh":"第21条"},"chapter":{"zh":"第二章"},"text":{"zh":"传染病监测内容\n1. 监测传染病感染、 疑似感染和病原携带病例包括地点、 时间、 感染和死亡的病例， 病情， 免疫情况， 人数主要特点信息及其他必要信息。\n紧急情况下， 职权医疗机构可以对疑似传染病病人进行抽血检验以监测。\n2. 监测传染病病原体包括种类、 生物学特性和传染源传染方式的相关信息。\n3. 监测疾病传播媒介包括疾病传播媒介的传染病病原体数量、 密度、 成分和感染程度的相关信息。"}},{"id":"VN-H072-A22","no":22,"noLabel":{"zh":"第22条"},"chapter":{"zh":"第二章"},"text":{"zh":"传染病监测报告\n1. 传染病监测报告必须交送至国家职权医疗机构， 传染病监测报告的内容包括本法第 21 条规定的信息。\n2. 传染病监测报告必须以书面形式执行； 紧急情况下， 可以通过传真、 电子邮件、 电报、 电话形式报告或直接报告， 并在24 小时内交送书面报告。\n3. 传染病监测报告制度包括：\n（1） 定期报告；\n（2） 快速报告；\n（3） 突发报告。\n4. 国家职权医疗机构接到报告后必须处理并通知报告机构。\n5. 确认存在疫情时， 国家职权医疗机构必须立即报告上级国家职权医疗机构和公布疫情的职权人。\n6. 卫生部部长对传染病通知、 报告制度作具体规定。"}},{"id":"VN-H072-A23","no":23,"noLabel":{"zh":"第23条"},"chapter":{"zh":"第二章"},"text":{"zh":"传染病监测责任\n1. 各级人民委员会指导、 组织落实地方传染病监测。\n2. 国家职权医疗机构有责任协助同级人民委员会指导医疗单位进行传染病监测。\n3. 医疗单位有责任落实传染病监测活动。发现存在 A 类传染病病原体环境、A 类传 ·67· 越南社会主义共和国传染病防控法染病患者、 疑似A 类传染病病人、A 类传染病病原携带者时， 医疗单位必须通知国家职权医疗机构， 开展清洁、 杀菌、 消毒和其他传染病防控措施。\n4. 机构、 组织、 个人发现疾病或传染病迹象时， 有责任通知人民委员会、 专业医疗机构或就近的医疗单位。\n5. 在传染病监测过程中， 检验单位有责任按照职权医疗机构的要求进行检验。\n6. 卫生部部长颁行传染病监测的专业技术规定。\n7. 农业与农村发展部、 自然资源与环境部和其他部委、 部级机构在各自国家管理范围内执行任务和行使权限时， 如发现传染病病原体有责任配合卫生部进行监测活动。\n第四目  检验的生物安全"}},{"id":"VN-H072-A24","no":24,"noLabel":{"zh":"第24条"},"chapter":{"zh":"第二章"},"text":{"zh":"检验室生物安全保障\n1. 检验室必须确保符合各个级别的生物安全条件， 并仅在获得国家职权医疗机构颁发的生物安全标准达标证书后方可进行检验。\n2. 政府对检验室生物安全保障作具体规定。"}},{"id":"VN-H072-A25","no":25,"noLabel":{"zh":"第25条"},"chapter":{"zh":"第二章"},"text":{"zh":"疾病样本管理\n1. 采集、 运输、 保存、 储存、 使用、 研究、 交换和销毁与传染病患者有关的疾病样本， 必须遵守疾病样本管理制度的规定。\n2. 只有具备充足条件的单位才可以保管、 储存、 使用、 研究、 交换和销毁A 类传染病的疾病样本。\n3. 卫生部部长对本条第 1 款 、第2 款规定的疾病样本管理制度和疾病样品管理单位的条件作具体规定。"}},{"id":"VN-H072-A26","no":26,"noLabel":{"zh":"第26条"},"chapter":{"zh":"第二章"},"text":{"zh":"检验室工作人员保护\n1. 与传染病病原体接触的检验室工作人员必须接受专业知识、 操作能力的培训， 并配备个人防护装备， 防止病原体传染。\n2. 与传染病病原体接触的检验室工作人员必须执行检验专业技术流程。\n第五目  预防疾病的疫苗、 医疗生物制品的使用"}},{"id":"VN-H072-A27","no":27,"noLabel":{"zh":"第27条"},"chapter":{"zh":"第二章"},"text":{"zh":"使用疫苗、 医疗生物制品的原则\n1. 使用的疫苗、 医疗生物制品必须确保符合 《药物法》 第36 条规定的条件。\n2. 使用疫苗、 医疗生物制品遵循自愿或强制形式。\n3. 疫苗、 医疗生物制品必须用于正确的目的、 对象、 时间、 种类和使用技术流程。\n4. 疫苗、 医疗生物制品必须在具备充足条件的医疗单位使用。\n“一带一路”法律查明     第 3 卷 ·68·"}},{"id":"VN-H072-A28","no":28,"noLabel":{"zh":"第28条"},"chapter":{"zh":"第二章"},"text":{"zh":"自愿使用疫苗、 医疗生物制品\n1. 任何人都有权使用疫苗、 医疗生物制品保护自身和社会健康。\n2. 国家扶持和鼓励公民自愿使用疫苗、 医疗生物制品。\n3. 直接参与护理、 治疗传染病患者的医师、 医护人员以及接触传染病病原体的检验室工作人员可以免费使用疫苗、 医疗生物制品。"}},{"id":"VN-H072-A29","no":29,"noLabel":{"zh":"第29条"},"chapter":{"zh":"第二章"},"text":{"zh":"强制使用疫苗、 医疗生物制品\n1. 位于疫区和前往疫区的有感染传染病风险的人员必须针对有预防疫苗和医疗生物制品的疾病强制使用疫苗、 医疗生物制品。\n2. 少年儿童、 怀孕妇女必须针对 《扩大接种计划》 中的传染病强制使用疫苗、 医疗生物制品。\n3. 少年儿童父母或监护人、 所有民众有责任在强制使用疫苗、 医疗生物制品中执行职权医疗单位的要求。\n4. 以下人员免费强制使用疫苗、 医疗生物制品：\n（1） 位于疫区的有感染传染病风险的人员；\n（2） 被国家职权机构派往疫区的人员；\n（3） 本条第2 款规定的对象。"}},{"id":"VN-H072-A30","no":30,"noLabel":{"zh":"第30条"},"chapter":{"zh":"第二章"},"text":{"zh":"组织使用疫苗、 医疗生物制品的责任\n1. 国家有责任为本法第 28 条第 3 款和第 29 条第 4 款规定的疫苗、 医疗生物制品的使用提供经费保障。\n2. 卫生部部长有责任：\n（1） 颁布本法第29 条第 1 款规定的必须强制使用疫苗、 医疗生物制品的传染病目录；\n（2） 组织落实 《扩大接种计划》 ， 并规定必须强制使用疫苗、 医疗生物制品的传染病目录以及本法第 29 条第 2 款规定的属于 《扩大接种计划》 对象的少年儿童年龄段；\n（3） 根据疫情规定强制使用疫苗、 医疗生物制品的范围和对象；\n（4） 规定本法第27 条第 3 款规定的疫苗、 医疗生物制品的使用， 本法第27 条第 4 款规定的医疗单位的条件；\n（5） 规定专业咨询委员会的设立、 组织和活动， 在本条第5 款 、第6 款规定的使用疫苗、 医疗生物制品过程中发生事故时检查原因。\n3. 省、 中央直辖市人民委员会 （以下简称 “省级人民委员会” ） 有责任指导组织开展接种、 使用疫苗和医疗生物制品。\n·69· 越南社会主义共和国传染病防控法\n4. 医疗单位有责任根据卫生部部长的规定在专业范围内接种和使用疫苗、 医疗生物制品。\n5. 生产、 经营、 保存疫苗、 医疗生物制品的组织和个人以及接种和使用疫苗、 医疗生物制品的工作人员在疫苗、 医疗生物制品的生产、 经营、 保管过程中造成过错的， 依法承担对疫苗、 医疗生物制品使用人造成事故的违规行为的责任。\n6. 实行扩大接种时， 如发生严重影响被接种人健康或危害其生命的事故的， 国家有责任对被接种人进行赔偿。认定过错由生产、 经营、 保存疫苗、 医疗生物制品的组织和个人或者接种疫苗工作人员造成的， 则该组织和个人必须依法向国家偿还。\n第六目  疾病诊疗单位的传染病预防"}},{"id":"VN-H072-A31","no":31,"noLabel":{"zh":"第31条"},"chapter":{"zh":"第二章"},"text":{"zh":"疾病诊疗单位的传染病预防措施\n1. 隔离传染病患者。\n2. 进行环境灭菌、 消毒， 并处理疾病诊疗单位的废物。\n3. 个人防护、 个人卫生。\n4. 法律规定的其他专业措施。"}},{"id":"VN-H072-A32","no":32,"noLabel":{"zh":"第32条"},"chapter":{"zh":"第二章"},"text":{"zh":"疾病诊疗单位在传染病预防中的责任\n1. 根据各种疾病类型采取适当的隔离措施， 对传染病患者进行综合护理。患者不执行疾病诊疗单位隔离要求的， 根据政府规定对其采取强制隔离措施。\n2. 组织实施环境杀菌、 消毒措施和处理疾病诊疗单位的废物。\n3. 保障医师、 医护人员、 患者及其家属的防护服和个人卫生条件。\n4. 对直接参与护理、 治疗A 类传染病患者的医师、 医护人员进行健康观察。\n5. 向同级医疗预防机构通报传染病患者的相关信息。\n6. 执行法律规定的其他专业措施。"}},{"id":"VN-H072-A33","no":33,"noLabel":{"zh":"第33条"},"chapter":{"zh":"第二章"},"text":{"zh":"医师、 医护人员在疾病治疗单位的传染病预防中的责任\n1. 执行本法第 31 条规定的传染病预防措施。\n2. 为患者及其家属解答传染病预防措施。\n3. 对患者信息保密。"}},{"id":"VN-H072-A34","no":34,"noLabel":{"zh":"第34条"},"chapter":{"zh":"第三章"},"text":{"zh":"患者及其家属在疾病诊疗单位的传染病预防中的责任\n1. 患者有责任：\n（1） 如实汇报病情变化；\n（2） 遵守医师、 医护人员的指示和指导以及疾病诊疗单位的规章制度；\n“一带一路”法律查明     第 3 卷 ·70·\n（3）A 类传染病患者出院后必须立即向居住地乡、 坊、 镇医疗单位登记进行健康观察。\n2. 患者家属有责任执行医师、 医护人员的指示和指导以及疾病诊疗单位的规章制度。\n第三章  边界医疗检疫"}},{"id":"VN-H072-A35","no":35,"noLabel":{"zh":"第35条"},"chapter":{"zh":"第三章"},"text":{"zh":"边界医疗检疫的对象和地点\n1. 必须进行边界医疗检疫的对象包括：\n（1） 入境、 出境、 过境越南的人员；\n（2） 入境、 出境、 过境越南的运输工具；\n（3） 进出口、 过境越南的货物；\n（4） 运输经过越南边界的尸体、 骸骨、 医学微生物样本、 细胞组织、 人体器官。\n2. 边界医疗检疫在各口岸进行。"}},{"id":"VN-H072-A36","no":36,"noLabel":{"zh":"第36条"},"chapter":{"zh":"第三章"},"text":{"zh":"边界医疗检疫的内容\n1. 本法第 35 条第 1 款规定的必须接受边界医疗检验的对象， 必须进行医疗申报。\n2. 医疗检查包括检查医疗相关文件和实际检查。实际检查在被检查对象从疫区出发或经过疫区或被怀疑感染疾病或携带传染病病原体的情况下进行。\n3. 在已进行医疗检查并发现医疗检疫对象有携带 A 类传染病病原迹象时， 进行医疗处理。接到运输工具所有人申报或有明确证据显示交通工具、 乘客、 货物有携带 A 类传染病病原迹象的情况， 则该交通工具及其搭载乘客、 货物在办理入境、 进口、 过境手续前， 必须隔离进行医疗检查； 不执行边界医疗检疫单位的隔离要求的， 则采取强制隔离措施。\n4. 按照本法第二章第三目的规定在口岸地区开展传染病监测活动。"}},{"id":"VN-H072-A37","no":37,"noLabel":{"zh":"第37条"},"chapter":{"zh":"第三章"},"text":{"zh":"开展边界医疗检疫的责任\n1. 本法第 35 条第 1 款 第（1） 项规定的对象， 第35 条第 1 款 第（2）项 、第（3）项 、第\n（4） 项规定的交通工具所有人或其管理人必须进行医疗申报， 执行医疗监测、 检查、 处理措施， 并依法缴纳医疗检疫费用。\n2. 边界医疗检疫单位有责任组织实施本法第 36 条规定的医疗检疫内容， 并开具医疗处理证明书。\n3. 口岸职能机构有责任在边界医疗检疫工作中配合边界医疗检疫单位。\n4. 国家职权机构有责任在边界地区传染病防控工作中配合各国有关机构和国际组织。\n5. 政府对边界医疗检疫作具体规定。\n·71· 越南社会主义共和国传染病防控法第四章  抗疫第一目  公布疫情"}},{"id":"VN-H072-A38","no":38,"noLabel":{"zh":"第38条"},"chapter":{"zh":"第三章"},"text":{"zh":"公布疫情的原则、 权限、 时间和条件\n1. 公布疫情的原则如下：\n（1） 任何疫情都必须公布；\n（2） 对疫情及疫情结束的公布必须公开、 准确、 及时且符合权限。\n2. 疫情的公布权限规定如下：\n（1） 省级人民委员会主席根据卫生厅厅长建议， 公布B 类和 C 类传染病的疫情；\n（2） 两个以上省份、 中央直辖市已公布疫情时， 卫生部部长根据省级人民委员会主席建议， 公布A 类传染病和若干 B 类传染病的疫情；\n（3） 疫情发生省际传播、 严重影响人类生命健康时， 政府总理根据卫生部部长的建议， 公布A 类传染病的疫情。\n3. 自接到公布疫情的建议起 24 小时内， 本条第2 款规定的职权人对公布疫情事宜作出决定。\n4. 政府总理对公布疫情的条件作具体规定。"}},{"id":"VN-H072-A39","no":39,"noLabel":{"zh":"第39条"},"chapter":{"zh":"第三章"},"text":{"zh":"公布疫情的内容\n1. 公布疫情的内容包括：\n（1） 疫病名称；\n（2） 疫情发生时间、 地点和规模；\n（3） 疫情发生原因、 传播路径、 性质、 危险程度；\n（4） 疫情防控措施；\n（5） 接收、 治疗传染病患者的疾病诊疗单位。\n2. 必须及时向有关机构、 组织、 个人通报本条第1 款规定的内容， 以便开展抗疫措施。"}},{"id":"VN-H072-A40","no":40,"noLabel":{"zh":"第40条"},"chapter":{"zh":"第三章"},"text":{"zh":"公布疫情结束的条件和权限\n1. 公布疫情结束的条件包括：\n（1） 在一定时间段内未发现新增感染病例， 且满足政府总理规定的各种疾病的其他条件。\n（2） 已实行本法第四章第三目规定的抗疫措施。\n2. 公布疫情职权人有权根据本法第38 条第 2 款规定的职权机构的建议公布疫情结束。\n“一带一路”法律查明     第 3 卷 ·72·"}},{"id":"VN-H072-A41","no":41,"noLabel":{"zh":"第41条"},"chapter":{"zh":"第三章"},"text":{"zh":"发布疫情消息大众信息机构有责任正确依照国家职权医疗机构提供的内容， 在公布疫情和公布疫情结束后准确地、 及时地、 真实地发布情况信息。\n第二目  宣布疫情紧急状态"}},{"id":"VN-H072-A42","no":42,"noLabel":{"zh":"第42条"},"chapter":{"zh":"第三章"},"text":{"zh":"宣布疫情紧急状态的原则和权限\n1. 宣布疫情紧急状态依照以下原则进行：\n（1） 疫情大范围快速传播， 严重威胁人类生命健康和国家经济社会时， 必须宣布紧急状态；\n（2） 宣布紧急状态必须公开、 准确、 及时和符合权限。\n2. 国会常务委员会根据政府总理建议颁布宣布紧急状态的决议； 国会常务委员会无法立即召开会议的情况下， 则由国家主席颁布宣布紧急状态令。"}},{"id":"VN-H072-A43","no":43,"noLabel":{"zh":"第43条"},"chapter":{"zh":"第三章"},"text":{"zh":"宣布疫情紧急状态的内容\n1. 宣布紧急状态的理由。\n2. 处于紧急状态的地界。\n3. 紧急状态开始的日期、 时刻。\n4. 组织施行宣布紧急状态的决议或令的权限。"}},{"id":"VN-H072-A44","no":44,"noLabel":{"zh":"第44条"},"chapter":{"zh":"第三章"},"text":{"zh":"解除紧急状态的权限疫情被拦截或扑灭时， 根据政府总理的提议， 国会常务委员会颁布决议或国家主席颁布令解除其宣布的紧急状态。"}},{"id":"VN-H072-A45","no":45,"noLabel":{"zh":"第45条"},"chapter":{"zh":"第三章"},"text":{"zh":"发布疫情紧急状态\n1. 越南通讯社、 越南之声电台、 越南电视台、 人民报、 人民军队报有责任立即全文登载国会常务委员会或国家主席颁布的宣布疫情紧急状态的决议或令、 政府总理组织施行国会常务委员会或国家主席颁布的宣布疫情紧急状态的决议或令的决定， 及时发布有关紧急状态地界所采取的措施和克服疫情后果情况的信息， 全文登载国会常务委员会或国家主席颁布的解除疫情紧急状态的决议或令。\n国会常务委员会或国家主席颁布的宣布或解除疫情紧急状态的决议或令必须在机构、 组织本部和公共单位进行公开张贴。\n2. 中央和地方的其他大众信息手段有责任发布宣布、 解除疫情紧急状态以及克服疫情后果过程的信息。\n·73· 越南社会主义共和国传染病防控法第三目  抗疫措施"}},{"id":"VN-H072-A46","no":46,"noLabel":{"zh":"第46条"},"chapter":{"zh":"第三章"},"text":{"zh":"成立抗疫指导委员会\n1. 公布疫情后必须立即成立抗疫指导委员会。\n2. 抗疫指导委员会的组成规定如下：\n（1） 国家抗疫指导委员会包括医疗、 财政、 信息通信、 外交、 国防、 公安和其他有关机构的代表。根据公布疫情的地界范围和疫情性质， 总理可以自行担任或指定副总理或卫生部部长之一担任指导委员长。卫生部是指导委员会的常务机构。\n（2） 省、 县、 乡级抗疫指导委员会包括医疗、 财政、 信息通信、 军队、 公安和其他有关机构的代表。抗疫指导委员长为同级人民委员会主席。同级医疗单位是指导委员会的常务机构。\n3. 抗疫指导委员会有责任组织执行抗疫措施和克服疫情后果， 成立机动抗疫队伍以直接执行急救、 治疗和处理疫点的措施。\n4. 政府总理对各级抗疫指导委员会的成立、 组织和活动权限作具体规定。"}},{"id":"VN-H072-A47","no":47,"noLabel":{"zh":"第47条"},"chapter":{"zh":"第三章"},"text":{"zh":"疫情的申报和报告\n1. 发生疫情时， 病例或病例和疑似病例的发现人必须在自发现疫情起 24 小时内向就近的医疗机构上报。\n2. 发现病例或接到疫病上报时， 医疗机构必须向疫情发生地的人民委员会和医疗预防单位报告， 尽快组织开展抗疫措施。\n3. 卫生部部长对疫情的上报、 报告制度作具体要求。"}},{"id":"VN-H072-A48","no":48,"noLabel":{"zh":"第48条"},"chapter":{"zh":"第三章"},"text":{"zh":"组织急救和疾病诊疗抗疫指导委员会指导采取以下措施， 组织为病例和疑似病例进行急救、 诊疗：\n1. 根据卫生部的诊断和治疗指导， 对病例进行分类、 初期救治、 及时急救。\n2. 调动手段、 药物、 医疗设备、 病床、 诊疗单位， 安排专业医务人员24 小时不间断值班， 随时做好抢救和诊疗准备， 为抗疫服务。对A 类传染病患者予以免费诊疗。\n3. 根据疫病的性质、 程度和规模， 抗疫指导委员会决定采取以下措施：\n（1） 组织疫区治疗单位接收、 抢救患者；\n（2） 调遣机动抗疫队伍进入疫区， 在患者处进行检测、 抢救和治疗， 将患者转移至诊疗单位；\n（3） 动员诊疗单位参加抗疫急救、 诊疗；\n（4） 采取其他法律规定的必要措施。\n“一带一路”法律查明     第 3 卷 ·74·"}},{"id":"VN-H072-A49","no":49,"noLabel":{"zh":"第49条"},"chapter":{"zh":"第三章"},"text":{"zh":"组织医疗隔离\n1. 疫病病例、 疑似疫病病人、 疫病病原携带者、A 类及若干 B 类疫病病原体接触者必须根据卫生部部长的规定进行隔离。\n2. 隔离形式包括居家隔离、 诊疗单位隔离或在其他地点隔离。\n3. 疫区医疗单位有责任根据抗疫指导委员会的指导组织隔离。本条第 1 款规定的对象不执行医疗单位的隔离要求的， 则根据政府规定采取强制隔离措施。"}},{"id":"VN-H072-A50","no":50,"noLabel":{"zh":"第50条"},"chapter":{"zh":"第三章"},"text":{"zh":"疫区卫生、 杀菌、 消毒\n1. 卫生、 杀菌、 消毒措施包括：\n（1） 环境、 水、 食品卫生和个人卫生；\n（2） 对确定或疑似存在疫病病原体的区域进行杀菌、 消毒；\n（3） 销毁动物、 食品和其他疾病传染媒介。\n2. 机动抗疫队伍有责任在抗疫委员会提出要求后立即依照专业标准采取卫生、 杀菌、 消毒措施。\n3. 机构、 组织、 个人有责任根据职权医疗单位的指导执行卫生、 杀菌、 消毒措施； 不自觉执行措施的， 医疗单位有权采取强制卫生、 杀菌、 消毒措施。"}},{"id":"VN-H072-A51","no":51,"noLabel":{"zh":"第51条"},"chapter":{"zh":"第三章"},"text":{"zh":"个人防护措施\n1. 参加抗疫人员和存在感染风险的人员必须采取以下一项或若干项措施进行个人防护：\n（1） 个人防护装备；\n（2） 使用预防疾病的药物；\n（3） 使用疫苗、 医疗生物制品预防疾病；\n（4） 使用灭菌化学品和防疾病传染媒介的化学品。\n2. 国家为参加抗疫人员采取本条第 1 款规定的个人防护措施提供保障。"}},{"id":"VN-H072-A52","no":52,"noLabel":{"zh":"第52条"},"chapter":{"zh":"第三章"},"text":{"zh":"疫情期间的其他抗疫措施\n1. 必要情况下， 国家职权机构可以采取以下抗疫措施：\n（1） 暂停疫区内具有疫病传染风险的公共饮食服务单位的活动；\n（2） 禁止经营、 使用被职权医疗单位确认为疫病传染媒介的食品；\n（3） 限制人群聚集或暂停疫区公共单位的活动和服务。\n2. 政府对采取本条第 1 款规定的措施作具体规定。\n·75· 越南社会主义共和国传染病防控法"}},{"id":"VN-H072-A53","no":53,"noLabel":{"zh":"第53条"},"chapter":{"zh":"第三章"},"text":{"zh":"对进出 A 类疾病疫区的监管\n1. 对进出 A 类疾病疫区的监管措施包括：\n（1） 限制人员和工具进出疫区， 必要时必须进行检查、 监测和医疗处理；\n（2） 禁止存在疫病传染可能的物品、 动物、 植物、 食品和其他货物离开疫区；\n（3） 对本法第51 条第 1 款规定的进入疫区人员采取个人防护措施；\n（4） 其他法律规定的必要措施。\n2. 抗疫指导委员会在进出疫区的交通枢纽设立检疫卡口点、 检疫站， 落实本条第 1 款规定的措施。"}},{"id":"VN-H072-A54","no":54,"noLabel":{"zh":"第54条"},"chapter":{"zh":"第三章"},"text":{"zh":"疫情紧急状态下采取的措施\n1. 在紧急状态下， 根据本法第46 条第 2 款 第（1） 项的规定成立抗疫指导委员会。\n2. 在宣布疫情紧急状态的情况下， 指导委员会有权：\n（1） 调动、 征用本法"}},{"id":"VN-H072-A55","no":55,"noLabel":{"zh":"第55条"},"chapter":{"zh":"第三章"},"text":{"zh":"规定的资源；\n（2） 设立告示牌、 看守站， 指引出行， 避开疫区；\n（3） 要求运输工具在驶离疫区前进行检查和医疗处理；\n（4） 禁止疫区人群聚集以及存在疫病传染风险的其他活动；\n（5） 禁止非任务人员、 工具进入疫区；\n（6） 组织大范围的消毒、 杀毒；\n（7） 销毁动物、 食品以及存在疫病传人风险的其他物品；\n（8） 采取本章第三目规定的其他措施。\n第五十五条  为抗疫活动调动资源\n1. 根据疫病性质、 危险程度和危及人民健康的规模， 职权人可以调集人员， 调动物质基础、 医疗设备、 药物、 化学品、 医疗物资、 公共服务设施、 交通工具及其他资源用于抗疫。对参加抗疫的交通工具依照交通法律予以优先。\n2. 被调用的财产如归还， 必须在归还前进行清洁、 杀菌、 消毒。\n3. 政府、 各级人民委员会有责任根据本法规定保障抗疫措施的实施条件。"}},{"id":"VN-H072-A56","no":56,"noLabel":{"zh":"第56条"},"chapter":{"zh":"第三章"},"text":{"zh":"抗疫国际合作\n1. 疫情发生时， 根据疫病的性质和危险程度， 卫生部部长决定在抗疫活动中开展疾病样本、 疫情信息、 专业、 技术、 设备、 经费等方面的国际交流合作。\n2. 在宣布疫情紧急状态的情况下， 政府总理呼吁各国、 国际组织援助抗疫资源， 并配合开展措施， 防止疫情传播。\n“一带一路”法律查明     第 3 卷 ·76· 第五章  传染病防控的保障条件"}},{"id":"VN-H072-A57","no":57,"noLabel":{"zh":"第57条"},"chapter":{"zh":"第三章"},"text":{"zh":"传染病防控单位\n1. 传染病防控单位包括：\n（1） 医疗预防单位；\n（2） 传染病诊疗单位包括传染病专科医院， 郡、 县、 县级市、 省辖市以上综合医院下属的传染病科和其他具有传染病诊疗任务的医疗单位。\n2. 郡、 县、 县级市、 省辖市以上综合医院必须设立传染病科。\n3. 卫生部部长对传染病诊疗单位的位置、 设计、 物质基础条件以及技术、 设备、 人力作出规定。"}},{"id":"VN-H072-A58","no":58,"noLabel":{"zh":"第58条"},"chapter":{"zh":"第三章"},"text":{"zh":"传染病防控工作人员的培训、 培养\n1. 国家具有计划和优先对传染病防控工作人员进行业务培训、 再培训和培养。\n2. 卫生部部长主持配合教育与培训部部长和相关机构、 组织负责人， 组织对传染病防控工作人员进行业务培训、 再培训和培养。"}},{"id":"VN-H072-A59","no":59,"noLabel":{"zh":"第59条"},"chapter":{"zh":"第三章"},"text":{"zh":"对传染病防控工作人员和参加抗疫人员的制度\n1. 传染病防控工作人员可以享受行业补贴制度和其他优待制度。\n2. 参加抗疫人员可以享受抗疫补贴制度， 如被感染疫病可以享受行业风险制度。\n3. 在抗疫过程中， 参加抗疫人员因英勇救人死亡或受伤的， 可以考虑认定为烈士或伤兵， 根据优待革命功勋法律的规定享受伤兵同等政策。\n4. 政府总理对本条第 1 款 、第2 款和第 3 款规定的制度作具体规定。"}},{"id":"VN-H072-A60","no":60,"noLabel":{"zh":"第60条"},"chapter":{"zh":"第三章"},"text":{"zh":"传染病防控工作的经费\n1. 传染病防控工作的经费包括：\n（1） 国家财政预算；\n（2） 援助资金；\n（3） 法律规定的其他经费来源。\n2. 国家每年为传染病防控活动保障充足、 及时的财政预算， 传染病防控的财政预算不得用于其他目的。"}},{"id":"VN-H072-A61","no":61,"noLabel":{"zh":"第61条"},"chapter":{"zh":"第三章"},"text":{"zh":"防控疫情的国家储备\n1. 国家实行经费、 药物、 化学品、 医疗设备的国家储备用于疫情防控。\n2. 建立、 组织、 管理、 调度和使用国家储备用于疫情防控必须按照国家储备法律执行。\n·77· 越南社会主义共和国传染病防控法"}},{"id":"VN-H072-A62","no":62,"noLabel":{"zh":"第62条"},"chapter":{"zh":"第六章"},"text":{"zh":"防控疫情扶持基金\n1. 疫情防控扶持基金按照法律的规定设立和活动， 用于治疗、 护理传染病患者和其他疫情防控活动。\n2. 基金财政来源于自愿捐助、 国内外组织和个人赞助。\n第六章  条款施行"}},{"id":"VN-H072-A63","no":63,"noLabel":{"zh":"第63条"},"chapter":{"zh":"第六章"},"text":{"zh":"施行效力本法自 2008 年 7 月 1 日起生效。"}},{"id":"VN-H072-A64","no":64,"noLabel":{"zh":"第64条"},"chapter":{"zh":"第六章"},"text":{"zh":"施行指导政府对本法作具体规定并指导施行。"}}],"pack":"vn-p03","rebuiltFrom":"原为单条全文，2026-10-24 按条号标记重新切分（拼接无损校验通过）"};
  FT["VN-H073"] = {"id":"VN-H073","coverage":"full","language":"zh","sourceName":"越南官方发布渠道","sourceUrl":"","fetchedAt":"2026-10-04","articleCount":7,"structureMode":"ARTICLE","title":{"zh":"边防法","en":"Law on Border Defence","orig":null},"level":"law","status":"active","docNumber":"年份不详","issuingBody":"越南官方发布渠道","completenessNote":"全文，共 7 条；取自《东盟法律分类》归档中的 PDF 原件，逐字未改写。","country":"VN","countryName":"越南","layer":"intl","articles":[{"id":"VN-H073-A2","no":2,"noLabel":{"zh":"第 2 条"},"heading":{"en":"国界所在地各级人民委员会在其职权范围内， 开展国家对边境的管理工作， 履行"},"text":{"zh":"下列职责：\n（a） 进行财政预算并提交同级人民议会， 为开展边防工作和建设地方的核心和专门力量提供保障。\n（b） 集中和调动各项资源， 建设政治、 经济、 文化、 社会、 科技、 国防、 安全、 外交等方面都稳固的边境地区； 在当地建设强大的全民边防事业和全民边防态势； 落实全民边防日政策； 执行军队后方的各项政策。\n（c） 妥善安置居民， 建设基础设施， 把经济、 文化、 社会、 科技发展与巩固和加强边境地区的国防、 安全和对外交流相结合。\n（d） 主持并配合同级越南祖国阵线委员会、 有关机关和组织， 组织群众运动参与管理和保卫国界， 维护边境地区的安全、 社会秩序和稳定的工作。\n（đ） 建设和平、 友好、 合作、 发展的边境地区。"}},{"id":"VN-H073-A3","no":3,"noLabel":{"zh":"第 3 条"},"heading":{"en":"国界所在地的各级人民议会和人民委员会在其职权范围内有下列职责："},"text":{"zh":"（a） 各级人民议会决定方针、 措施、 财政预算， 监督和调动各项资源以确保边防工作的开展。\n（b） 各级人民委员会参与并配合各机关、 组织开展边防工作， 构筑强大的全民边防事业和全民边防态势； 宣传、 普及边防法律； 参与发展边境地区经济、 文化、 社会、 科学、 技术和对外交流的各项项目的实施； 落实全民边防日政策； 执行军队后方的各项政策。\n第三十四条  越南祖国阵线及其成员组织的职责越南祖国阵线及其成员组织在其职责和权限范围内， 配合有关机关和组织宣传和动员人民遵守边防法律， 监督边防相关法律的实施。\n第六章  执行条款\n第三十五条  将第 06/2003/QH11 号国家边界法第 21 条修改、 补充如下：\n“第 21 条"}},{"id":"VN-H073-A1","no":1,"noLabel":{"zh":"第 1 条"},"text":{"zh":"因国防、 安全或特殊原因， 或应有关国家要求或通知， 可限制或暂停人员、 交通工具、 货物跨境， 包括无害通过越南领海。"},"partIndex":2},{"id":"VN-H073-A2-d2","no":2,"noLabel":{"zh":"第 2 条"},"heading":{"en":"在边境带、 边境地区限制活动， 在口岸和陆地边境小道限制或暂停跨境活动， 应符"},"text":{"zh":"合越南边防法的规定。\n“一带一路”法律查明     第 3 卷 ·38·"},"dupIndex":2,"partIndex":2},{"id":"VN-H073-A3-d2","no":3,"noLabel":{"zh":"第 3 条"},"heading":{"en":"本条第 1 款规定的限制或暂停活动的决定权， 除本条第 2 款规定的情况外， 归中"},"text":{"zh":"央政府所有。限制或暂停活动的决定必须通知地方政府和有关国家的职能部门。 ”\n第三十六条  执行效力"},"dupIndex":2,"partIndex":2},{"id":"VN-H073-A1-d2","no":1,"noLabel":{"zh":"第 1 条"},"text":{"zh":"本边防法自 2022 年 1 月 1 日起施行。"},"dupIndex":2,"partIndex":2},{"id":"VN-H073-A2-d3","no":2,"noLabel":{"zh":"第 2 条"},"text":{"zh":"第 02/1997/PL-UBTVQH9 号边防部队法令自本边防法生效之日起失效。\n本边防法于 2020 年 11 月 11 日由越南社会主义共和国第十四届国会第十次会议通过。\n国会主席阮氏金银"},"dupIndex":3,"partIndex":2}],"pack":"vn-p03"};
  FT["VN-H074"] = {"id":"VN-H074","coverage":"full","language":"zh","sourceName":"越南官方发布渠道","sourceUrl":"","fetchedAt":"2026-10-04","articleCount":51,"structureMode":"ARTICLE","title":{"zh":"反恐怖主义法","en":"Law on Counter-Terrorism","orig":null},"level":"law","status":"active","docNumber":"年份不详","issuingBody":"越南官方发布渠道","completenessNote":"文本未能可靠切分为条文（或原件为目录式排版），按整篇收录，未作改写。","country":"VN","countryName":"越南","layer":"intl","articles":[{"id":"VN-H074-A1","no":1,"noLabel":{"zh":"第1条"},"chapter":{"zh":"第一章"},"text":{"zh":"“一带一路”法律查明     第 3 卷 ·204· 越南社会主义共和国反恐怖主义法根据 1992 年 《越南社会主义共和国宪法》 （经第51/2001/QH10 号决议修订、 补充若干条款） ， 国会颁布 《反恐怖主义法》 。\n第一章  总  则\n调整范围本法规定了反恐怖主义的原则、 政策、 措施、 力量， 反恐怖主义国际合作以及机构、 组织、 个人的职责。"}},{"id":"VN-H074-A2","no":2,"noLabel":{"zh":"第2条"},"chapter":{"zh":"第一章"},"text":{"zh":"适用对象本法适用于越南公民、 机构和组织； 在越南境内居住和活动的国际组织、 外国组织和外国人， 但越南社会主义共和国加入的国际条约另有规定的除外。"}},{"id":"VN-H074-A3","no":3,"noLabel":{"zh":"第3条"},"chapter":{"zh":"第一章"},"text":{"zh":"词语解释在本法中， 下列词语解释如下：\n1. 恐怖主义， 是指组织、 个人以反对人民政权， 强迫人民政权、 外国组织和国际组织， 妨碍越南社会主义共和国的国际关系或引发公众恐慌为目的的行为， 包括：\n（1） 侵犯他人生命、 健康、 人身自由或威胁侵犯他人生命、 精神的；\n（2） 霸占、 损坏、 破坏或威胁破坏机构、 组织和个人的财产， 攻击、 侵害、 阻碍、 扰乱机构、 组织和个人的计算机网络、 电信网络、 互联网和数字设备运行的；\n（3） 引导制造、 生产、 使用或制造、 生产、 储藏、 运输、 交易武器、 爆炸物、 放射物、 有毒物、 易燃物和用于实施本条第1 款 第（1）项 、 第（2） 项规定行为的其他用品、 工具的；\n（4） 宣传、 引诱、 教唆、 强迫、 雇佣或提供便利、 协助实施本条第1 款 第（1）项 、 第（2） 项规定行为的；\n（5） 建立、 参与组织、 招募、 培训、 训练实施本条第1 款（1）项 、 第（2）项 、 第（3）项 、 第（4） 项规定行为的对象的；\n* 译者： 陶文文， 北京外国语大学亚洲学院博士生。\n* ·205· 越南社会主义共和国反恐怖主义法\n（6） 越南社会主义共和国加入的反恐怖主义国际条约规定的其他恐怖主义行为。\n2. 恐怖主义融资， 是指为任何形式的恐怖主义组织和个人筹集、 资助资金和财产的行为。\n3. 反恐怖主义， 包括防范恐怖主义、 恐怖主义融资和打击恐怖主义、 恐怖主义融资的活动。"}},{"id":"VN-H074-A4","no":4,"noLabel":{"zh":"第4条"},"chapter":{"zh":"第一章"},"text":{"zh":"反恐怖主义的原则\n1. 在越南共产党领导、 国家统一管理和全社会的参与下， 以人民公安力量主持配合人民军队为核心。\n2. 遵守宪法和法律， 保障祖国独立、 主权、 领土统一和完整、 国家利益和机构、 组织、 个人的合法权益。\n3. 防范为主， 主动发现、 及时阻止、 严正处理进行恐怖主义和恐怖主义融资的组织和个人。\n4. 保护人民生命、 健康安全以及机构、 组织的财产安全， 最大限度地降低损失。"}},{"id":"VN-H074-A5","no":5,"noLabel":{"zh":"第5条"},"chapter":{"zh":"第一章"},"text":{"zh":"反恐怖主义的政策\n1. 国家审判并严惩一切恐怖主义和恐怖主义融资行为， 同步采取措施组织反恐怖主义工作， 宣传、 动员组织和个人参与反恐怖主义活动。\n2. 国家具有调动科技成果为反恐怖主义活动服务的政策。\n3. 国家优先为反恐怖主义、 反恐怖主义融资力量投资专业技术设备和工具， 并为其提供制度和政策保障。\n4. 国家具有保护参加反恐怖主义活动的组织和个人的政策和措施。参加反恐怖主义活动的个人遭受人身伤害、 健康损害或者死亡的， 其本人或其亲属有权享受法律规定的制度和政策优待。组织和个人的财产被调用为反恐怖主义活动服务如有损失的， 应当予以赔偿。\n5. 在反恐怖主义活动中有功劳的组织和个人， 依照竞赛、 表彰法律的规定予以表彰。\n6. 国家采取宽大政策对待主动放弃恐怖主义、 恐怖主义融资意图； 自行中止实施恐怖主义、 恐怖主义融资行为， 或在恐怖主义、 恐怖主义融资行为被告发前， 积极阻止、 减轻危害， 补救后果， 并自首、 诚实报告， 积极帮助责任机构发现、 制止、 调查、 起诉和审理恐怖主义、 恐怖主义融资的组织和个人。"}},{"id":"VN-H074-A6","no":6,"noLabel":{"zh":"第6条"},"chapter":{"zh":"第一章"},"text":{"zh":"禁止行为\n1. 本法第 3 条第 1 款 、第2 款规定的恐怖主义、 恐怖主义融资行为。\n2. 藏匿、 窝藏、 不检举恐怖主义、 恐怖主义融资。\n“一带一路”法律查明     第 3 卷 ·206·\n3. 在反恐怖主义工作中泄露国家机密。\n4. 故意散布有关恐怖主义、 恐怖主义融资的虚假信息， 阻碍、 妨碍反恐怖主义活动。\n5. 利用反恐怖主义工作的职权侵犯国家利益和组织、 个人的合法权益。"}},{"id":"VN-H074-A7","no":7,"noLabel":{"zh":"第7条"},"chapter":{"zh":"第一章"},"text":{"zh":"反恐怖主义的责任\n1. 反恐怖主义是机构、 组织和公民的责任。\n2. 机构领导人、 组织负责人在其职权范围内， 负责执行反恐怖主义法律。\n3. 在越南境内居住和活动的国际组织、 外国组织和外国人， 有责任依照本法和其他相关法律的规定， 参与反恐怖主义活动。"}},{"id":"VN-H074-A8","no":8,"noLabel":{"zh":"第8条"},"chapter":{"zh":"第一章"},"text":{"zh":"越南祖国阵线及其成员组织的职责越南祖国阵线及其成员组织在其职权范围内， 有责任宣传和动员人民严格执行反恐怖主义法律， 监督反恐怖主义法律的执行。"}},{"id":"VN-H074-A9","no":9,"noLabel":{"zh":"第9条"},"chapter":{"zh":"第一章"},"text":{"zh":"对恐怖主义罪犯和恐怖主义融资罪犯的调查、 起诉和审判对恐怖主义罪犯和恐怖主义融资罪犯的调查、 起诉和审判应当遵守 《刑法》 《刑事诉讼法》 及其他相关法律的规定。"}},{"id":"VN-H074-A10","no":10,"noLabel":{"zh":"第10条"},"chapter":{"zh":"第一章"},"text":{"zh":"对与恐怖主义和恐怖主义融资有关的资金和财产的处理\n1. 对与恐怖主义、 恐怖主义融资有关的资金和财产， 应当依法予以暂停流通、 封锁、 查封、 暂扣和处理。\n2. 暂停流通、 封锁、 查封、 暂扣、 处理与恐怖主义、 恐怖主义融资有关的资金和财产的条件、 手续、 权限和形式， 由政府作具体规定。"}},{"id":"VN-H074-A11","no":11,"noLabel":{"zh":"第11条"},"chapter":{"zh":"第二章"},"text":{"zh":"反恐怖主义活动的保障经费\n1. 反恐怖主义活动保障经费的来源包括：\n（1） 国家财政预算；\n（2） 其他合法的经费来源。\n2. 反恐怖主义活动保障经费的管理和使用， 应当按法律规定执行。\n第二章  反恐怖主义活动的组织"}},{"id":"VN-H074-A12","no":12,"noLabel":{"zh":"第12条"},"chapter":{"zh":"第二章"},"text":{"zh":"反恐怖主义指导委员会\n1. 政府设立国家反恐怖主义指导委员会， 国家反恐怖主义指导委员会的成员按兼职制度工作。\n公安部是国家反恐怖主义指导委员会的常设机构， 设有专职咨询和协助机构。\n2. 省级人民委员会设立省级反恐怖主义指导委员会。省级反恐怖主义指导委员会的 ·207· 越南社会主义共和国反恐怖主义法成员按兼职制度工作。\n省公安厅是省级反恐怖主义指导委员会的常设机构， 设有咨询和协助机构。\n3. 根据政府总理下达的任务及其指导， 部长和部级首长设立部委反恐怖主义指导委员会。"}},{"id":"VN-H074-A13","no":13,"noLabel":{"zh":"第13条"},"chapter":{"zh":"第二章"},"text":{"zh":"反恐怖主义指导委员会的任务和权限\n1. 国家反恐怖主义指导委员会的任务和权限如下：\n（1） 向政府和政府总理提供组织和指导全国反恐怖主义活动的咨询；\n（2） 协助政府和政府总理组织开展跨部门反恐怖主义协作和国际反恐怖主义合作；\n（3） 协助政府和政府总理检查、 督促和指导反恐怖主义工作。\n2. 省级反恐怖主义指导委员会的任务和权限如下：\n（1） 向同级人民委员会和人民委员会主席提供组织和指导当地反恐怖主义活动的咨询；\n（2） 协助同级人民委员会和人民委员会主席组织开展当地跨部门反恐怖主义协作；\n（3） 协助同级人民委员会和人民委员会主席检查、 督促和指导反恐怖主义工作。\n3. 各部委反恐怖主义指导委员会协助部长、 部级机构首长， 组织、 指导其负责领域的反恐怖主义工作， 并配合其他部委、 地方、 机构执行反恐怖主义工作。\n4. 各级反恐怖主义指导委员会的组织、 任务、 权限和协调关系， 由政府作具体规定。"}},{"id":"VN-H074-A14","no":14,"noLabel":{"zh":"第14条"},"chapter":{"zh":"第二章"},"text":{"zh":"反恐怖主义力量\n1. 反恐怖主义力量包括：\n（1） 公安部、 国防部下属的受命执行反恐怖主义任务的机构、 单位；\n（2） 其他被调集参与反恐怖主义的力量。\n2. 本条第 1 款 第（1） 项规定的机构、 单位的任务和权限， 由公安部部长、 国防部部长作具体规定。"}},{"id":"VN-H074-A15","no":15,"noLabel":{"zh":"第15条"},"chapter":{"zh":"第二章"},"text":{"zh":"反恐怖主义指挥员\n1. 反恐怖主义指挥员由职权机构决定。\n2. 职权机构尚未决定反恐怖主义指挥员的， 恐怖主义活动发生地的国家机构、 人民武装部队和人民委员会负责人有职责按照本法"}},{"id":"VN-H074-A16","no":16,"noLabel":{"zh":"第16条"},"chapter":{"zh":"第二章"},"text":{"zh":"第 2 款的规定采取反恐怖主义措施。\n3. 飞机、 船舶离开机场、 港口后发生恐怖主义活动的， 该运输工具的指挥人员有责任指挥反恐怖主义工作。\n4. 政府对本条内容作详细规定。\n“一带一路”法律查明     第 3 卷 ·208·\n第十六条  反恐怖主义指挥员的任务和权限\n1. 本法第 15 条第 1 款规定的反恐怖主义指挥员， 具有下列任务和权限：\n（1） 为职权机构决定必要的反恐怖主义方案和措施提供参谋和建议；\n（2） 根据职权机构决定的方案和措施指挥反恐怖主义工作；\n（3） 遭遇紧急情况但职权机构尚未决定方案和措施的， 反恐怖主义指挥官有职责采取本法第 30 条第 2 款规定的措施， 但该措施具有政治和外交影响、 侵犯他人生命或破坏特殊价值财产的情况除外。\n2. 本法第 15 条第 2 款规定的国家机构、 人民武装部队、 人民委员会领导人有职责采取本法第 30 条第 2 款 第（1）项 、第（2）项 、第（3）项 、第（4）项 、第（6）项 、第（7）项 、 第（8）项 、第（11） 项规定的反恐怖主义紧急措施， 但该措施具有政治和外交影响、 侵犯他人生命或破坏特殊价值财产的情况除外。\n3. 本法第 15 条第 3 款规定的反恐怖主义指挥负责人有职责依法采取措施阻止和制止恐怖主义行为。\n4. 本条第 1 款 、第2 款 、第3 款规定的人员对其行为和决定负法律责任。"}},{"id":"VN-H074-A17","no":17,"noLabel":{"zh":"第17条"},"chapter":{"zh":"第二章"},"text":{"zh":"反恐怖主义武器、 工具、 手段的配备和使用\n1. 反恐怖主义力量应优先配备反恐怖主义的武器、 辅助工具和专业技术手段。\n2. 反恐怖主义力量使用武器、 辅助工具和专业技术手段， 应符合本法和其他相关法律的规定。"}},{"id":"VN-H074-A18","no":18,"noLabel":{"zh":"第18条"},"chapter":{"zh":"第三章"},"text":{"zh":"调集反恐怖主义的力量和手段， 征购和征用用于反恐怖主义的财产\n1. 发生恐怖主义活动时， 法律规定的职权人员可以调集力量和手段打击恐怖主义。\n被调集进行反恐怖主义活动的机构、 组织和个人有责任予以执行。\n2. 发生恐怖主义活动时， 征购和征用用于反恐怖主义的财产应遵守财产征购、 征用法律的规定。\n第三章  防范恐怖主义"}},{"id":"VN-H074-A19","no":19,"noLabel":{"zh":"第19条"},"chapter":{"zh":"第三章"},"text":{"zh":"防范恐怖主义的措施采取本法"}},{"id":"VN-H074-A20","no":20,"noLabel":{"zh":"第20条"},"chapter":{"zh":"第三章"},"text":{"zh":"至第 27 条规定的措施及法律规定的其他措施防范恐怖主义和恐怖主义融资。\n第二十条  反恐怖主义的通知、 宣传、 教育\n1. 职权机构和人员有责任进行反恐怖主义的通知、 宣传和教育， 以提高反恐怖主义的意识、 责任感和有效性。\n·209· 越南社会主义共和国反恐怖主义法\n2. 反恐怖主义的通知、 宣传、 教育内容包括：\n（1） 恐怖主义的危机、 演变和情况， 恐怖主义的活动手段和方式、 危险性、 危害；\n（2） 反恐怖主义的措施、 经验、 政策和法律；\n（3） 机构、 组织和个人在反恐怖主义活动中的责任；\n（4） 其他反恐怖主义的必要内容。"}},{"id":"VN-H074-A21","no":21,"noLabel":{"zh":"第21条"},"chapter":{"zh":"第三章"},"text":{"zh":"治安行政管理\n1. 通过其活动进行治安行政管理的职权机构和人员， 有责任及时主动发现恐怖主义组织和个人的原因、 条件、 阴谋、 方式、 手段和活动， 并采取相应的处理措施。\n2. 通过治安行政管理防范恐怖主义的措施， 包括：\n（1） 管理公民居留、 档案、 身份信息；\n（2） 管理武器、 爆炸物、 辅助工具、 易燃物、 有毒物和放射物；\n（3） 保卫和保护越南境内与国家安全、 国防工程、 军区、 外交使团办事处、 外国领事机构、 国际组织代表机构有关的重要工程；\n（4） 巡查、 监管、 监控与治安、 机场、 港口、 火车站、 汽车站、 口岸、 边境地区、 人员聚集场所及其他公共场所等有关的重点目标；\n（5） 管理入境、 出境和过境；\n（6） 法律规定的其他治安行政管理措施。"}},{"id":"VN-H074-A22","no":22,"noLabel":{"zh":"第22条"},"chapter":{"zh":"第三章"},"text":{"zh":"交通运输活动的监管监管公路、 铁路、 水路、 海路和航空交通运输的职权机构和人员， 有责任主动发现、 及时制止和处理利用上述方式进行恐怖主义活动的行为。"}},{"id":"VN-H074-A23","no":23,"noLabel":{"zh":"第23条"},"chapter":{"zh":"第三章"},"text":{"zh":"资金和财产交易的监管监管资金和财产交易的职权机构和人员， 有责任关注、 监督和制止有恐怖主义迹象的资金和财产交易； 依法对应上报价值的资金和财产交易进行监督， 以及时发现有恐怖主义迹象的交易。"}},{"id":"VN-H074-A24","no":24,"noLabel":{"zh":"第24条"},"chapter":{"zh":"第三章"},"text":{"zh":"入境、 出境、 过境工具和货物的监管监管入境、 出境、 过境工具和货物的职权机构和人员， 有责任严格监管入境、 出境、 过境的工具和货物， 以及时发现、 制止、 处理利用上述方式进行恐怖主义活动的行为。"}},{"id":"VN-H074-A25","no":25,"noLabel":{"zh":"第25条"},"chapter":{"zh":"第三章"},"text":{"zh":"出版、 报刊、 邮政、 电信和其他信息形式的监管出版、 报刊、 邮政、 电信和其他信息形式活动的职权机构和人员， 有责任监管和及时发现、 制止、 处理利用上述方式进行恐怖主义活动的行为。\n“一带一路”法律查明     第 3 卷 ·210·"}},{"id":"VN-H074-A26","no":26,"noLabel":{"zh":"第26条"},"chapter":{"zh":"第三章"},"text":{"zh":"食品、 疾病防治药物卫生安全保障活动的监管监管粮食、 食品、 饲料、 化肥、 治疗药物、 预防药物、 兽药、 植物保护药物、 化验标本卫生安全的职权机构和人员， 有责任及时发现、 制止、 处理利用上述方式进行恐怖主义活动的行为。"}},{"id":"VN-H074-A27","no":27,"noLabel":{"zh":"第27条"},"chapter":{"zh":"第四章"},"text":{"zh":"制定和组织实施反恐怖主义方案\n1. 公安部、 国防部、 有关部委、 各级人民委员会在其职责范围内， 负责制定、 训练、 演习和组织实施反恐怖主义方案。\n2. 经批准的反恐怖主义方案中确定的机构、 组织和单位有责任予以执行。\n第四章  打击恐怖主义"}},{"id":"VN-H074-A28","no":28,"noLabel":{"zh":"第28条"},"chapter":{"zh":"第四章"},"text":{"zh":"发现恐怖主义\n1. 机构、 组织和个人通过其活动积极发现恐怖主义。\n2. 本法第 14 条第 1 款 第（1） 项规定的反恐怖主义力量， 有责任采取专业技术措施发现恐怖主义， 指导和协助机构、 组织和个人认识、 发现、 通报、 检举恐怖主义活动。"}},{"id":"VN-H074-A29","no":29,"noLabel":{"zh":"第29条"},"chapter":{"zh":"第四章"},"text":{"zh":"对恐怖主义通报和检举的接收和处理\n1. 机构、 组织和个人发现恐怖主义迹象或行为时， 应及时通知本法第14 条第 1 款第\n（1） 项规定的反恐怖主义力量或就近的公安机关、 军队和人民委员会。公安机关、 军队和人民委员会有责任充分受理有关恐怖主义的通报和检举。\n2. 公安机关、 军队和人民委员会在收到本条第 1 款规定的有关恐怖主义的通报和检举或自行发现恐怖主义迹象和行为后， 应立即通知本法第 14 条第 1 款 第（1） 项规定的反恐怖主义力量， 对举报人信息保密； 发现已经发生、 正在发生或者有理由相信即将发生恐怖活动的， 依照本法第16 条第 2 款的规定采取反恐怖主义紧急措施。\n3. 本法第 14 条第 1 款 第（1） 项规定的反恐怖主义力量在收到有关恐怖主义的通报和检举后， 应及时处理， 并向职权机构和职权反恐怖主义委员会报告。发现已经发生、 正在发生或者有理由相信即将发生恐怖活动的， 依照本法第 16 条第 2 款的规定采取反恐怖主义紧急措施。\n4. 发生恐怖活动时， 反恐怖主义指导委员会必须向上级反恐怖主义指导委员会报告， 反恐怖主义单位应直接向上级反恐怖主义单位报告。"}},{"id":"VN-H074-A30","no":30,"noLabel":{"zh":"第30条"},"chapter":{"zh":"第四章"},"text":{"zh":"反恐怖主义措施\n1. 应当采取本法和保护国家安全保护、 保障社会治安法律规定的措施打击恐怖主义。\n2. 反恐怖主义紧急措施是在恐怖活动已经发生、 正在发生或有理由相信即将发生时 ·211· 越南社会主义共和国反恐怖主义法立即采取的措施， 旨在及时制止恐怖活动， 消除和限制恐怖主义危害。反恐怖主义紧急措施包括：\n（1） 包围和封锁发生恐怖活动的地区；\n（2） 解救人质， 紧急救助受害者， 隔离人员， 将交通工具和财产转移出恐怖主义危险区；\n（3） 与恐怖分子谈判；\n（4） 包围、 追踪、 控制和逮捕恐怖分子， 解除用于恐怖活动的武器、 工具和手段；\n（5） 攻击、 消灭恐怖分子， 销毁用于恐怖活动的武器、 工具和手段；\n（6） 暂停用于恐怖活动的交通工具、 信息和通信工具；\n（7） 破坏、 拆除妨碍反恐怖主义活动的房屋和建筑， 移除妨碍反恐怖主义活动的障碍物， 设置阻碍恐怖活动的障碍物；\n（8） 保护、 移动、 隐藏、 伪装恐怖活动袭击对象的工程和目标；\n（9） 调集力量和手段打击恐怖主义；\n（10） 检查、 冻结与恐怖主义有关的账户和资金来源， 停止与恐怖主义有关的资金和财产交易， 暂时扣押与恐怖主义有关的资金和财产；\n（11） 开封、 查验、 扣押与恐怖主义有关的信件、 电报、 邮包、 邮件、 包裹和货物；\n（12） 收集与恐怖主义有关的材料和证据。\n3. 本条第 2 款规定的采取反恐怖主义紧急措施的权限、 条件、 程序和手续， 由政府作具体规定。"}},{"id":"VN-H074-A31","no":31,"noLabel":{"zh":"第31条"},"chapter":{"zh":"第四章"},"text":{"zh":"打击外交使团办事处、 外国领事机构、 国际组织代表机构及其成员住所的恐怖主义\n1. 当有理由相信在越南境内的外交使团办事处、 外国领事机构、 国际组织代表机构及其成员住所已经发生、 正在发生或即将发生恐怖活动时， 有关机构、 组织和个人或知情人应当及时通知本法第 14 条第 1 款 第（1） 项规定的反恐怖主义力量或就近的公安机关、 军队、 人民委员会。公安机关、 军队和人民委员会收到有关恐怖主义的通报和检举后， 应当依照本法第 29 条的规定受理。\n2. 在外交使团办事处、 外国领事机构、 国际组织代表机构及其成员住所进行反恐怖主义活动时， 越南机构、 组织和个人必须遵守本法和越南社会主义共和国加入的各项国际条约的规定。"}},{"id":"VN-H074-A32","no":32,"noLabel":{"zh":"第32条"},"chapter":{"zh":"第五章"},"text":{"zh":"打击越南驻外机构、 组织和公民的恐怖主义活动当有理由相信越南驻外机构、 组织或公民已经发生、 正在发生或即将发生恐怖活动 “一带一路”法律查明     第 3 卷 ·212· 时， 越南社会主义共和国驻外代表机构领导人应当立即根据其权限采取符合国际法律和所在国法律的必要措施， 并及时向外交部和国家反恐指导委员会报告。\n第五章  打击恐怖主义融资"}},{"id":"VN-H074-A33","no":33,"noLabel":{"zh":"第33条"},"chapter":{"zh":"第五章"},"text":{"zh":"恐怖主义融资活动的发现， 对恐怖主义融资活动通报和检举的受理\n1. 国家银行、 金融机构、 从事非金融行业的相关组织和个人以及其他组织和个人发现恐怖主义融资活动的迹象和行为时， 应及时向本法第 14 条第 1 款 第（1） 项规定的反恐怖主义力量报告。\n2. 本法第 14 条第 1 款 第（1） 项规定的反恐怖主义力量， 有责任充分接收有关恐怖主义融资的通报和检举并迅速处理， 向职权机构和职权反恐怖主义指导委员会汇报； 在发现已经发生、 正在发生或有理由相信即将发生恐怖主义融资活动时， 应立即采取本法第 30 条第 2 款 第（6）项 、第（9）项 、第（10）项 、第（11）项 、第（12） 项规定的反恐怖主义紧急措施。"}},{"id":"VN-H074-A34","no":34,"noLabel":{"zh":"第34条"},"chapter":{"zh":"第五章"},"text":{"zh":"识别、 更新客户信息和采取临时措施从事非金融行业的金融机构、 组织和个人有义务采取措施识别和更新客户信息； 当怀疑客户或客户的交易与恐怖主义融资活动有关或客户被列入黑名单时， 应当向公安部反恐怖主义力量、 越南国家银行下属职能部门报告， 并应当根据反洗钱法律采取临时措施。"}},{"id":"VN-H074-A35","no":35,"noLabel":{"zh":"第35条"},"chapter":{"zh":"第六章"},"text":{"zh":"现金、 贵金属、 珠宝和流通票据跨境流动的监管根据本法第 24 条和 《反洗钱法》 第24 条规定的监管现金、 贵金属、 珠宝和流通票据经越南边境流动的职权组织和个人， 有责任及时发现、 制止、 处理利用上述方式进行恐怖主义融资的行为。\n第六章  反恐怖主义国际合作"}},{"id":"VN-H074-A36","no":36,"noLabel":{"zh":"第36条"},"chapter":{"zh":"第六章"},"text":{"zh":"国际合作的原则越南社会主义共和国在遵守越南法律和越南社会主义共和国加入的国际反恐怖主义条约， 尊重国际法的基本原则， 保障祖国的独立、 主权、 领土统一和完整， 保护国家利益和组织、 个人合法权益的基础上， 开展反恐怖主义领域的国际合作。"}},{"id":"VN-H074-A37","no":37,"noLabel":{"zh":"第37条"},"chapter":{"zh":"第六章"},"text":{"zh":"国际合作的内容和责任\n1. 国际合作的内容包括：\n（1） 交换反恐怖主义的信息；\n·213· 越南社会主义共和国反恐怖主义法\n（2） 进行反恐怖主义训练和演习；\n（3） 提高反恐怖主义的法律能力， 进行反恐怖主义知识和技能的培训和训练；\n（4） 加强反恐怖主义的物质条件；\n（5） 解决恐怖主义案件；\n（6） 根据越南法律和越南社会主义共和国加入的国际条约的规定， 开展其他国际合作内容。\n2. 公安部主持并配合有关部委， 协助政府谈判、 提议签署或加入与反恐怖主义有关的国际条约， 主持并配合有关部委执行反恐怖主义工作。"}},{"id":"VN-H074-A38","no":38,"noLabel":{"zh":"第38条"},"chapter":{"zh":"第七章"},"text":{"zh":"解决恐怖主义案件的国际合作解决恐怖主义案件的国际合作， 按照本法第 4 条 、第36 条以及越南社会主义共和国加入的国际条约规定的原则进行。越南社会主义共和国与有关国家未加入多边条约或未签署双边条约的， 越南职权机构在本法第 4 条 、第36 条规定以及符合本国需要和能力的原则上， 开展解决恐怖主义案件的国家合作。\n第七章  国家机构在反恐怖主义工作中的职责"}},{"id":"VN-H074-A39","no":39,"noLabel":{"zh":"第39条"},"chapter":{"zh":"第七章"},"text":{"zh":"反恐怖主义工作的国家管理机构\n1. 政府对反恐怖主义工作实行国家统一管理。\n2. 公安部向政府负责， 主持并配合国防部及有关部委对反恐怖主义工作进行国家管理。\n3. 各级人民委员会在其职权范围内， 有责任对本地区的反恐怖主义工作进行国家管理。"}},{"id":"VN-H074-A40","no":40,"noLabel":{"zh":"第40条"},"chapter":{"zh":"第七章"},"text":{"zh":"公安部的职责\n1. 公安部在反恐怖主义国家管理工作中的职责如下：\n（1） 向政府提议制定和完善反恐怖主义法律；\n（2） 主持、 配合制定和呈报颁布机构或根据职权颁布反恐怖主义的法律法规、 战略、 项目、 计划、 方案和措施；\n（3） 主持、 配合有关部委， 并指导省级人民委员会组织执行反恐怖主义的法律法规、 战略、 项目、 计划、 方案和措施；\n（4） 主持、 配合国防部、 有关机构和组织颁布和组织执行培训、 培养反恐怖主义干部的规定；\n（5） 主持、 配合有关机构和组织执行反恐怖主义的汇报和总结制度， 建议、 提议与反 “一带一路”法律查明     第 3 卷 ·214· 恐怖主义有关的解决办法；\n（6） 监察、 检查、 解决反恐怖主义工作中的投诉和控告；\n（7） 根据本法第37 条第 2 款的规定， 开展国际反恐怖主义合作。\n2. 公安部在组织、 执行反恐怖主义工作时， 履行下列职责：\n（1） 为人民公安反恐力量配备和保障装备；\n（2） 主持、 配合有关部委、 机构、 组织， 根据本法第三、 四、 五章的规定， 在全国范围内指导和组织执行反恐怖主义工作， 配合国防部在其管理对象和地区内指导和组织执行反恐怖主义工作；\n（3） 指导下属机构单位执行本法第三、 四、 五章规定的任务和职权， 发现、 调查和依法处理进行恐怖主义、 恐怖主义融资的组织和个人；\n（4） 执行本法及其他相关法律规定的其他任务。"}},{"id":"VN-H074-A41","no":41,"noLabel":{"zh":"第41条"},"chapter":{"zh":"第七章"},"text":{"zh":"国防部的职责\n1. 配合公安部执行本法第 40 条第 1 款 第（3）项 、第（4） 第和第2 款 第（2） 项规定的任务。\n2. 主持、 配合公安部、 有关机构、 组织在国防部管理的目标和地区执行反恐怖主义工作。\n3. 为国防部反恐怖主义力量配备和保障装备并指导其活动。\n4. 指导下属机构单位配合人民公安机构单位， 制定、 训练、 演练、 组织执行反恐怖主义方案。\n5. 指导边防部队配合人民公安机关单位、 海关及其他机关单位， 通过监管边防口岸出境、 入境、 过境人员的方式执行反恐怖主义措施。\n6. 配合公安部、 外交部根据职权开展国际反恐怖主义合作。"}},{"id":"VN-H074-A42","no":42,"noLabel":{"zh":"第42条"},"chapter":{"zh":"第七章"},"text":{"zh":"外交部的职责\n1. 在职权范围内， 依照本法和其他有关法律的规定， 组织实施反恐怖主义活动。\n2. 根据职权人员的调动决定， 指导下属机关单位做好参加反恐怖主义工作的准备。\n3. 指导越南社会主义共和国驻外使团领导人配合所在国有关部门进行反恐怖主义工作。\n4. 配合公安部制定和组织反恐怖主义方案的训练、 演习。\n5. 发生恐怖主义活动时， 配合公安部、 国防部和驻越南外交使团办事处、 外国领事馆、 国际组织代表机构所在地方制定保护方案、 处置方案。\n6. 配合职能机构保护在越南访问和执行公务的外国代表团的安全。在发生恐怖活动 ·215· 越南社会主义共和国反恐怖主义法时， 配合有关机构和地方管理、 指导外国记者的新闻活动。\n7. 与恐怖主义高发国家驻越南外交使团和领事使团配合交流情报， 提出防范、 制止措施， 制定、 训练、 演练各种反恐怖主义情形。\n8. 配合公安部及其他相关部委开展国际反恐怖主义合作， 参加反恐怖主义国际条约和国际协定的谈判、 签署、 加入和落实。"}},{"id":"VN-H074-A43","no":43,"noLabel":{"zh":"第43条"},"chapter":{"zh":"第七章"},"text":{"zh":"交通运输部的职责\n1. 在职权范围内， 依照本法和其他有关法律组织实施反恐怖主义活动。\n2. 根据职权人员的调动决定， 指导下属机关单位做好参加反恐怖主义工作的准备。\n3. 配合公安部、 国防部、 有关部委和地方人民委员会制定、 训练、 演练、 组织实施预防和打击劫机、 劫船、 劫持人质以及飞机、 船舶、 火车和其他交通工具发生爆炸的方案， 保障机场、 港口、 火车站和汽车站的安全。\n4. 配合公安部、 国防部和地方人民委员会， 维护重要机场、 火车站、 码头、 汽车站、 海港、 桥梁、 公路隧道的治安； 监管司机、 乘客和交通工具， 以发现、 制止和处理恐怖活动。"}},{"id":"VN-H074-A44","no":44,"noLabel":{"zh":"第44条"},"chapter":{"zh":"第七章"},"text":{"zh":"财政部的职责\n1. 在职权范围内， 依照本法和其他有关法律组织实施反恐怖主义活动。\n2. 根据职权人员的调动决定， 指导下属机关单位做好参加反恐怖主义工作的准备。\n3. 指导海关配合人民公安机构、 边防部队和其他有关机构监管入境、 出境、 过境的货物和运输工具， 执行反恐怖主义措施。"}},{"id":"VN-H074-A45","no":45,"noLabel":{"zh":"第45条"},"chapter":{"zh":"第七章"},"text":{"zh":"越南国家银行的职责\n1. 在职权范围内， 依照本法和其他有关法律， 组织实施反恐怖主义活动。\n2. 根据责任人的调动决定， 指导下属机构单位做好参加反恐怖主义工作的准备。\n3. 接收金融机构和从事非金融行业的组织和个人有关恐怖主义和恐怖主义融资的可疑交易信息和报告； 有依据怀疑交易涉及恐怖主义或恐怖主义融资的， 应当及时通知公安部反恐怖主义力量并配合查证。\n4. 配合公安部开展国际反恐怖主义合作。"}},{"id":"VN-H074-A46","no":46,"noLabel":{"zh":"第46条"},"chapter":{"zh":"第七章"},"text":{"zh":"信息通信部的职责\n1. 在职权范围内， 依照本法和其他有关法律， 组织实施反恐怖主义活动。\n2. 根据职权人员的调动决定， 指导下属机关单位做好参加反恐怖主义工作的准备。\n3. 指导出版、 报刊、 邮政、 电信和信息技术单位和企业开展下列活动：\n（1） 组织反恐怖主义活动的信息安全保障工作。\n（2） 配合公安机关、 军队制定和开展出版、 报刊、 邮政、 电信、 信息技术和联络网站点 “一带一路”法律查明     第 3 卷 ·216· 的反恐怖主义措施； 监管出版、 报刊、 邮政、 电信和信息技术活动， 以发现和处理利用上述方式进行恐怖活动、 恐怖主义融资活动的行为。\n（3） 管控在公众媒体上发布的恐怖主义信息， 宣传、 教育、 提高干部和人民的反恐怖主义意识， 打击恐怖主义组织、 个人的信息和通信活动。"}},{"id":"VN-H074-A47","no":47,"noLabel":{"zh":"第47条"},"chapter":{"zh":"第七章"},"text":{"zh":"有关部委在反恐怖主义工作中的职责\n1. 在职权范围内， 依照本法和其他有关法律， 组织实施反恐怖主义活动。\n2. 配合公安部在其职责范围内执行反恐怖主义国家管理工作。\n3. 根据职权人员的调动决定， 指导下属机关单位做好参加反恐怖主义工作的准备。"}},{"id":"VN-H074-A48","no":48,"noLabel":{"zh":"第48条"},"chapter":{"zh":"第七章"},"text":{"zh":"人民检察院和人民法院的职责人民检察院、 人民法院应当在职责范围内， 及时处理恐怖主义、 恐怖主义融资犯罪行为， 依法配合有关机构和组织执行反恐怖主义工作。"}},{"id":"VN-H074-A49","no":49,"noLabel":{"zh":"第49条"},"chapter":{"zh":"第八章"},"text":{"zh":"各级人民委员会的职责\n1. 在职权范围内， 执行本地区反恐怖主义的国家管理工作， 依照本法和其他有关法律的规定组织实施反恐怖主义活动。\n2. 配合越南祖国阵线和同级政治社会组织， 开展全民运动， 维护国家安全， 参加反恐怖主义活动。\n3. 指导当地人民武装力量和职能部门制定、 开展执行当地反恐怖主义工作。\n4. 向职权部门呈报反恐怖主义的财政预算， 根据国家财政预算法规定管理和使用反恐怖主义财政预算。\n第八章  条款施行"}},{"id":"VN-H074-A50","no":50,"noLabel":{"zh":"第50条"},"chapter":{"zh":"第八章"},"text":{"zh":"施行效力本法自 2013 年 10 月 1 日起施行。"}},{"id":"VN-H074-A51","no":51,"noLabel":{"zh":"第51条"},"chapter":{"zh":"第八章"},"text":{"zh":"详细规定和施行指南政府对本法各条款作详细规定， 并指导施行。\n本法于 2013 年 6 月 12 日由越南社会主义共和国第十三届国会第五次会议通过。"}}],"pack":"vn-p03","rebuiltFrom":"原为单条全文，2026-10-24 按条号标记重新切分（拼接无损校验通过）"};
  FT["VN-H075"] = {"id":"VN-H075","coverage":"full","language":"zh","sourceName":"越南官方发布渠道","sourceUrl":"","fetchedAt":"2026-10-04","articleCount":8,"structureMode":"ARTICLE","title":{"zh":"电子商务法","en":"Law on E-Commerce","orig":null},"level":"law","status":"active","docNumber":"年份不详","issuingBody":"越南官方发布渠道","completenessNote":"全文，共 8 条；取自《东盟法律分类》归档中的 PDF 原件，逐字未改写。","country":"VN","countryName":"越南","layer":"intl","articles":[{"id":"VN-H075-A1","no":1,"noLabel":{"zh":"第 1 条"},"chapter":{"zh":"第七章"},"heading":{"en":"应国家主管机关要求，各机构、组织和个人负有以下责任："},"text":{"zh":"14\n（1）保存一个特定通信信息，包括移动数据到另一个计算机系统或其他存储位置；\n（2）维护特定通信信息的完整性；\n（3）出示或提供该机构、组织或个人拥有或正在控制的某种通信信息， 包括密码和其他加密方法；\n（4）在请求的机构、组织或个人是有权控制该信息的服务提供者的情况下，呈现或提供有关服务使用者的信息；\n（5）法律规定的其他职责。"}},{"id":"VN-H075-A2","no":2,"noLabel":{"zh":"第 2 条"},"chapter":{"zh":"第七章"},"heading":{"zh":"当事人协商无果的，则依法律规定的权限、命令和程序按照解决电子商务"},"text":{"zh":"国家主管机关必须对其请求承担法律责任。\n第四十九条 国家主管机关的权利和责任"}},{"id":"VN-H075-A1-d2","no":1,"noLabel":{"zh":"第 1 条"},"chapter":{"zh":"第七章"},"heading":{"en":"国家主管机关享有以下权利："},"text":{"zh":"（1）搜索或执行对部分或整个计算机系统以及该系统内数据消息的访问；\n（2）查封全部或部分计算机系统；\n（3）复制并保留通信信息的副本；\n（4）阻止访问计算机系统；\n（5）法律规定的其他权利。"},"dupIndex":2},{"id":"VN-H075-A2-d2","no":2,"noLabel":{"zh":"第 2 条"},"chapter":{"zh":"第七章"},"heading":{"zh":"当事人协商无果的，则依法律规定的权限、命令和程序按照解决电子商务"},"text":{"zh":"国家主管机关行使本条第 1 款规定的权利时，必须对其决定承担法律责任。\n第七章 争端解决和违法行为的处理\n第五十条 电子商务违法行为的处理"},"dupIndex":2},{"id":"VN-H075-A1-d3","no":1,"noLabel":{"zh":"第 1 条"},"chapter":{"zh":"第七章"},"heading":{"en":"违反电子商务法的行为人将根据违法行为的性质和严重程度受到纪律处"},"text":{"zh":"分、行政处罚或刑事处罚，造成损害的，必须依照法律规定给予赔偿。"},"dupIndex":3},{"id":"VN-H075-A2-d3","no":2,"noLabel":{"zh":"第 2 条"},"chapter":{"zh":"第七章"},"heading":{"en":"在电子商务中违法的机关、组织，根据违法行为的性质和严重程度，给予"},"text":{"zh":"行政处分，暂停其业务；造成损害的，必须依照法律规定给予赔偿。\n第五十一条 电子商务纠纷电子商务纠纷是指以电子方式进行交易过程中发生的纠纷。\n第五十二条 电子商务争端解决"},"dupIndex":3},{"id":"VN-H075-A1-d4","no":1,"noLabel":{"zh":"第 1 条"},"chapter":{"zh":"第七章"},"text":{"zh":"国家鼓励电子商务发生争议的当事人协商解决。\n15"},"dupIndex":4},{"id":"VN-H075-A2-d4","no":2,"noLabel":{"zh":"第 2 条"},"chapter":{"zh":"第八章"},"heading":{"en":"当事人协商无果的，则依法律规定的权限、命令和程序按照解决电子商务"},"text":{"zh":"纠纷。\n第八章 施行规定\n第五十三条 施行效力本法自 2006 年 3 月 1 日起施行。\n第五十四条 施行说明政府制定并指导本法的实施。\n本法由越南社会主义共和国第十一届国会第八次会议于 2005 年 11 月 29 日通过"},"dupIndex":4}],"pack":"vn-p03"};
  FT["VN-H076"] = {"id":"VN-H076","coverage":"full","language":"zh","sourceName":"越南官方发布渠道","sourceUrl":"","fetchedAt":"2026-10-04","articleCount":30,"structureMode":"ARTICLE","title":{"zh":"增值税法","en":"Law on Value Added Tax","orig":null},"level":"law","status":"active","docNumber":"年份不详","issuingBody":"越南官方发布渠道","completenessNote":"文本未能可靠切分为条文（或原件为目录式排版），按整篇收录，未作改写。","country":"VN","countryName":"越南","layer":"intl","articles":[{"id":"VN-H076-A1","no":1,"noLabel":{"zh":"第1条"},"chapter":{"zh":"第一章"},"text":{"zh":"增值税法 (1997 年5 月10 日02/1997/QH9 号） 为了促进生产，扩大商品和服务流通，鼓励发展国民经济， 动员消费者的一部分收入上交国家财政；\n根据1992年越南社会主义共和国宪法；\n本法规定增值税。\n第一章 总则\n【增值税】 增值税是发生在生产、流通及消费过程中的商品、服务的增加价值之上计算的税收。"}},{"id":"VN-H076-A2","no":2,"noLabel":{"zh":"第2条"},"chapter":{"zh":"第一章"},"text":{"zh":"【应税对象】 在越南用于生产、经营和消费的商品、服务是应税对象，但本法\n第四条规定的除外。"}},{"id":"VN-H076-A3","no":3,"noLabel":{"zh":"第3条"},"chapter":{"zh":"第一章"},"text":{"zh":"【纳税对象】 生产、经营应税商品、服务的单位、个人（统称为经营单位）和进口应税商品的其它单位、个人（统称为进口商）是缴纳增值税的对象。"}},{"id":"VN-H076-A4","no":4,"noLabel":{"zh":"第4条"},"chapter":{"zh":"第一章"},"text":{"zh":"【不属于增值税应税对象范围的对象】 下列商品、服务不属于增值税应税对象范围：\n1、未加工成其它产品或者只经过自销自产的单位、个人的一般加工的种植、饲养、水产养殖产品；\n2、盐；\n3、属于特别销售税应税对象的商品、服务在缴纳特别销售税环节不缴纳增值税；\n4、属于国内还不能生产而单位有按照该项目作为固定资产的进口投资项目的专用设备、机械、运输工具；\n5、转让属于土地使用权转让应税范围的土地使用权；\n6、国家出售给租用人的属于国家所有的住宅；\n7、信用、投资基金服务；\n8、人寿保险；学生保险；家禽、作物保险和各类非经营用途的保险；\n9、医疗服务；\n10、非经营用途的文化、展览和体育活动；艺术表演；电影制作；\n发行和播放胶片电影、材料录像影片；\n11、教学、授业；\n12、印刷、出版和发行报纸、杂志、专业刊物、政治书本、教科书、教程、法律文本、少数民族由于印刷版本；用于宣传的图画、 相片、宣传画；银钞；\n13、道路和居民区卫生、排泄的公共服务；动物园、花园、公园、 道路绿化、公共照明维护；丧礼服务；\n14、利用人民捐赠的资金和人道援助资金维修、修理、建设文化、 艺术工程、公共服务项目、基础设施和情义房；\n16、运送乘客的公共汽车；\n17、调查、勘探地质，测量、绘制属于国家基本调查类的地图；\n18、服务农业生产的排灌；单位、个人自发开采的服务农村、山区、海岛和偏远地区的生活用水；\n19、保护国防安全的武器装备；\n20、属于下列情形的进口货物：人道援助，无偿援助的货物；赠送给国家机关、政治组织、政治—社会组织、社会组织、社会— 行业组织、人民武装单位的赠品；享有外交豁免权的外国组织、 个人的用品；免税行李标准内随身携带的物品；\n21、转口、过境、借道越南的商品；暂入再出和暂出再入货物；\n22、直接提供给国际运输和越南外消费者的商品、服务；\n23、技术转让；\n24、未加工成美术工艺品、装饰品或其它产品的条状、块状进口黄金；\n25、对于出口产品是开采后未加工的矿产品的情形，由政府具体规定；\n26、低收入的经营个体的商品、服务。低收入度由政府规定。\n本条规定的不属于增值税应税范围的商品、服务不得抵扣或返还产前投入税。\n必要时，国会常务委员会可以修改、补充本条所规定的增值税非应税对象范围的商品、服务名单，并报告以便国会在最近的会议上批准。"}},{"id":"VN-H076-A5","no":5,"noLabel":{"zh":"第5条"},"chapter":{"zh":"第二章"},"text":{"zh":"【《增值税法》的履行义务、责任】\n1、经营单位和进口商有义务依照本法的规定足额、按时纳税。\n2、税务机关在自身任务、权限范围内有责任正确执行本法的规定。\n3、国家机关、政治组织、政治—社会组织、社会组织、社会— 行业组织、人民武装单位在自身的职责、任务、权限范围内，在履行《增值税法》的过程中的监察、配合税务机关。\n4、越南公民有责任在履行本法的过程中的帮助税务机关、税务干部。\n第二章 税款计算依据和方法"}},{"id":"VN-H076-A6","no":6,"noLabel":{"zh":"第6条"},"chapter":{"zh":"第二章"},"text":{"zh":"【税款计算依据】 增值税计算依据是税款计算价格和税率。"}},{"id":"VN-H076-A7","no":7,"noLabel":{"zh":"第7条"},"chapter":{"zh":"第二章"},"text":{"zh":"【税款计算价格】 增值税计算价格规定如下：\n1、对于商品、服务是没有增值税的销售价；\n2、进口商品是在港口的进口价加上进口税；\n3、用于交流，内部使用，赠送的商品、服务是在活动进行当时同类或相似商品、服务的增值税计算价格。\n4、对于出租财产的活动是分期收取的租金；\n5、对于按照分期支付的方式出售的商品是商品的售价，按一次性支付的售价计算，不按分期支付的金额计算；\n6、对于加工商品是加工价；\n7、其它商品、服务是由政府规定的价格；\n本条规定的商品、服务的增值税计算价格包括经营机构享受的服价款和增收费。\n对于纳税人有用外汇买卖的营业额的，应按照越南国家银行在营业额发生时间公布的正式汇率兑换成越南盾以确定税款计算价格。"}},{"id":"VN-H076-A8","no":8,"noLabel":{"zh":"第8条"},"chapter":{"zh":"第二章"},"text":{"zh":"【税率】 增值税率规定如下：\n1、出口商品，税率为 0%;\n2、税率为 5%的商品、服务：\n（1）生产和生活用水；\n（2）肥料、生产肥料的矿石：杀虫剂和促进家禽、作物生产的生产剂；\n（3）医疗设备和工具；医疗卫生棉和绷带；\n（4）治病、防病药物；\n（5）教学和学习用的教具；\n（6）玩具；科学—技术书，文学艺术书，儿童读物，法律文本， 但本法第四条第13款规定的除外；\n（7）未加工的种植、饲养、水产养殖产品，包括种蓄、种苗、 种子，但本法第四条第1 款规定的除外；\n（8）未加工的林产（木材、竹笋除外)，新鲜食品；\n（9）国内原棉；\n（10）家蓄、家禽食物和其它禽蓄的食物；\n（11）科学技术服务；\n（12）直接用于农业生产的服务；\n3、税率为 10%的商品、服务：\n（1）石油、天然气、原煤、矿石和其它矿产；\n（2）电力商品；\n（3）电子、机械、电器产品；\n（4）化工原料，工艺品；\n（5）纤维、布料，缝纫和刺绣产品；\n（6）纸和纸制品；\n（7）食糖、乳、饼、糖果、饮料和其它各类加工食品；\n（8）陶、瓷、玻璃、橡胶、塑料、木材和木制品；水泥、砖、 瓦和其它建筑材料；\n（9）建设、安装；\n（10）运输、装卸；\n（11）邮电、邮政、电信服务；\n（12）出租房屋、仓库、码头、工厂、机械、设备、运输工具；\n（13）法律咨询服务；\n（14）拍摄、印刷、放大照片；录磁带、转录磁带、出租磁带；\n拍录像、放录像、复印；\n（15）烫发、做服装、染发、洗熨、漂净；\n（16）本条第1、2和 4款没规定的其他各类商品、服务，但在进出口环节收取特别销售税的商品除外；\n4、税率为 20%的商品、服务：\n（1）由经营机构购买销售的黄金、白银、宝石；\n（2）旅店、旅游、饮食；\n（3）建设彩票和其它各类彩票；\n（4）海轮代理；\n（5）媒体服务；\n必要时，国会常务委员会可以按照本条所规定的税率修改、补充商品、服务名单，并报告以便国会在最近的会议上批准。"}},{"id":"VN-H076-A9","no":9,"noLabel":{"zh":"第9条"},"chapter":{"zh":"第二章"},"text":{"zh":"【税款计算方法】 增值税应纳税款按照抵扣税款的方法或在增值价格之上直接计算的方法计算。\n1、抵扣税款的方法。\n应纳税额等于产出增值税减去产前投入增值税。\n产出增值税等于销售的商品、服务的税款计算价格乘以税率。\n产前投入增值税等于记录在购买商品、服务的增值发票或者进口商品增值税交纳凭证上的已清算的增值税总额。\n2、在增值价格之上直接计算的方法。\n应纳税额等于商品、服务的增加价值乘以增值税率。\n增加价值等于销售商品、服务的清算价减去相应购买商品、服务的清算价格。\n在增值价格之上直接计算的方法只适用下列对象：\n（1）生产、经营个体和在越南经营的外国组织、个人不遵循《外国在越南投资法》，没有充分履行有关会计，发票，凭证的条件， 以抵扣税款的方法作为计算税款的依据。\n（2）购买销售黄金、白银、宝石的经营机构。"}},{"id":"VN-H076-A10","no":10,"noLabel":{"zh":"第10条"},"chapter":{"zh":"第二章"},"text":{"zh":"【抵扣产前投入增值税】\n1、按照抵扣税款的方法缴纳增值税的经营机构可抵扣下列产前投入增值税（称为产前投入税)：\n（1）用于生产、经营增值税应税商品、服务的商品、服务的产前投入税可全部抵扣；\n（2）同时用于生产、经营增值税应税和非应税商品、服务的商品、服务的产前投入税可抵扣用于生产、经营增值税应税商品、 服务的商品、服务的产前投入税；\n（3）产前投入税发生在哪个月，在确定当月的应纳税额时可申报、抵扣；但对于固定资产，如果产前投入税抵扣较多，可逐渐抵扣或按照政府的规定返还税款;\n（4）对于生产、加工单位生产者还未加工的农产、林产、水产养殖而没有增值发票的，可抵扣在农产、林产、水产养殖购买价之上计算的1%至 5%的产前投入税；各类商品的抵扣比例由政府规定；\n本点规定的税款抵扣不适用于出口；\n（5）其它特殊情形，产前投入税的抵扣由政府规定。\n2、确定可抵扣的产前投入税额的依据是：\n（1）记录在购买商品、服务的增值发票或进口商品的增值税的交纳凭证上的增值税额；购买的商品、服务没有增值发票或者发票没有记录增值税额的，不能进行税款抵扣；\n（2）本条第 1 款规定的商品、商品购买清单按照税务机关的样式。"}},{"id":"VN-H076-A11","no":11,"noLabel":{"zh":"第11条"},"chapter":{"zh":"第三章"},"text":{"zh":"【发票，凭证】\n1、商品的购买销售依法都应有发票、凭证。\n2、按照抵扣税款的方法纳税的经营单位应使用增值税发票，并应充分、准确记录规定的要素，付价款、增收费、增值税、清算价。\n发票没有记录增值税的，增值税确定为发票的清算价乘以增值税税率。\n3、可看作清算凭证的各类印花、票据原本已印上了清算价的， 印花、票据的清算价已包含增值税。\n第三章 登记，申报，纳税，清算税款"}},{"id":"VN-H076-A12","no":12,"noLabel":{"zh":"第12条"},"chapter":{"zh":"第三章"},"text":{"zh":"【纳税登记】\n1、经营单位，包括其直属机构应按照税务机关的说明向直接管理的税务机关登记缴纳增值税。对于新成立的经营单位，登记缴纳增值税的时间最迟不超过十日，从发给经营登记许可证之日起。对于兼并、合并、分开、划分、解体、破产或更换经营，经营单位在兼并、合并、分开、划分、解体、破产或更换经营之前十五日呈报税务机关。\n2、按照在增值价格之上直接计算的方法纳税的经营单位，如果充分遵守凭证、发票、计算簿规则，自愿登记按照抵扣税款的方法纳税的，税务机关审查办理。"}},{"id":"VN-H076-A13","no":13,"noLabel":{"zh":"第13条"},"chapter":{"zh":"第三章"},"text":{"zh":"【纳税申报】\n1、经营单位应逐月申报增值税，并在下一个月的前十日向税务机关递交税款登记表。对于没有发生产前投入税的情形，经营单位仍然应申报并向税务机关递交登记表。经营单位应按照正确定税务登记格式填写充分，并对申报道准确性负责。\n2、经营单位、商品进口商每一次进口商品都应申报并递交增值税登记表，同时向进口港口当地的税务机关申报进口税。\n3、临时商业经营单位每一次交易在运输商品前都应商品购买当地的税务机关申报并纳税。\n4、兼营不同增值税税率的多种商品、服务的机构应按照各类商品、服务的税率申报增值税。如果经营单位按照各种税率无法确定的，应按照单位生产、经营的商品、服务的最髙税率核算并纳税。\n财政部规定税款登记表格式并指导说明申报事项。"}},{"id":"VN-H076-A14","no":14,"noLabel":{"zh":"第14条"},"chapter":{"zh":"第三章"},"text":{"zh":"【增值税按下列规定上交国家财政：】\n1、经营单位按照税务机关的纳税通知，足额、按时缴纳增值税。\n当月纳税期限记录在通知之中，最迟不迟于下月二十五日。\n2、经营单位、进口商应在每一次进口时缴纳增值税。进口商品的增值税的通知期限和缴纳期限依照进口税的通知期限缴纳期限确定。\n3、税款清算期，经营单位按照抵扣税款的方法缴纳增值税，如果产前投入税多于产出税，则在下一个税款清算期中抵扣。\n对于经营单位新投资固定资产，产前投入税扣除较多，则依照本法第十条第一款第三点的规定执行。\n4、增值税以越南盾上交国家财政。"}},{"id":"VN-H076-A15","no":15,"noLabel":{"zh":"第15条"},"chapter":{"zh":"第三章"},"text":{"zh":"【决算税款】 经营单位应每年与税务机关决算税款。税款清算年按公历计算。\n从年终起六十日内，经营单位应向税务机关递交决算报告，并在递交了决算报告起十日内向国家财政缴纳完毕欠税，如果缴纳有多余，则在下一期应纳税额中抵扣。\n对于兼并、合并、分开、划分、解体、破产的，经营单位应与税务机关完成决算，并在四十五日内向税务机关递交决算报告，从决定进行兼并、合并、分开、划分、解体、破产之日起。"}},{"id":"VN-H076-A16","no":16,"noLabel":{"zh":"第16条"},"chapter":{"zh":"第三章"},"text":{"zh":"【返还税款返还增值税的情形如下：】\n1、按照抵扣税款的方法纳税的经营单位，如果季度内各月抵扣的产前投入税多于产出税，可按季度返还税款，或者按照本法第十条第一款第三点的规定返还固定资产的产前投入税；\n2、在进行兼并、合并、分开、划分、解体、破产时决算税款， 缴纳税款有多余的；\n3、审批机关依法作出的返还税款的处理决定。\n财政部依据本条具体规定办理返还税款的手续和审批权。"}},{"id":"VN-H076-A17","no":17,"noLabel":{"zh":"第17条"},"chapter":{"zh":"第三章"},"text":{"zh":"【税务机关的任务、权限和责任】 税务机关有下列任务、权限和责任任务、权限和责任：\n1、指导登记经营的单位依照本法的规定履行登记、申报、纳税的制度；\n2、正确依照规定通知经营单位应纳税额和纳税期限；如果超过了记录在通知上的纳税期限而经营单位还没有缴纳的，继续按照本法第十九条第二款的规定通知应纳税额和滞纳金；如果经营单位仍不足额缴纳税款、罚金的，可采取本法第十九条第四款规定的措施以保证足额征收税款、罚金；如果采取了以上措施而经营单位仍不足额缴纳税款、罚金的，则将档案转交有审批权的国家机关依法处理；\n3、检查、清查经营单位申报、纳税、决算税款情况以保证正确履行法律规定；\n4、处理税收行政违法行为和受理有关税收的起诉；\n5、要求纳税人提供会计簿、发票、凭证和与税款计算、税款缴纳相关的其它档案材料；要求信用机构、银行和其它相关单位、 个人提供与税款计算、税款缴纳相关的档案、材料；\n6、按规定保存和使用经营单位和其它对象提供的数据、材料。"}},{"id":"VN-H076-A18","no":18,"noLabel":{"zh":"第18条"},"chapter":{"zh":"第四章"},"text":{"zh":"【税款确定权】\n1、下列情形，税务机关确定纳税人应纳税额：\n（1）不履行或不正确履行会计、发票、凭证制度；\n（2）不申报或超过通知的登记表递交时间仍不正确履行；已递交了税款登记表但申报不符合确定增值税额的依据；\n（3）拒绝出示会计簿、发票、凭证与增值税计算相关的材料；\n（4）被发现经营没有登记经营。\n2、税务机关依据对经营单位的经营活动情况的调查材料或者依据同行业，有相当经营规模的经营单位的应纳税额来确定应纳税额。\n对于不同意已确定的应纳税额的，经营单位有权向直接上级税务机关起诉；在等待解决定时间，经营单位仍需按照已确定的税额缴纳税额。\n第四章 处罚、嘉奖"}},{"id":"VN-H076-A19","no":19,"noLabel":{"zh":"第19条"},"chapter":{"zh":"第四章"},"text":{"zh":"对【纳税人税收违法行为的处理】 纳税人违反《增值税法》的，处理如下：\n1、不正确执行有关登记、申报、纳税、决算税款的规定，本法\n第十一条、第十二条、第十三条、第十四条和第十五条规定的会计和留存发票、凭证的制度，视违法性质、程度予以税收行政违法处罚；\n2、比规定应交纳或者税收处理处理决定的期限迟缴纳税款、罚金的，除了足额缴纳税款、罚金外，每迟缴一日，还应缴0.1%(千分之一）滞纳金的罚金；\n3、瞒税、逃税，除了依法足额缴纳税款外，视违法性质、程度还要处以一至五倍欺诈税款的罚款；逃税数目巨大或者已予以税收行政违法充分，但还违反或者有其它严重违法行为的，依法追究刑事责任；\n4、不按照通知或税收处理决定纳税，缴纳罚金的，处理如下：\n（1）提取纳税人在银行、金库、信用组织的存款来缴纳税款、 罚金；\n在收取债务前，银行、金库、信用组织有责任依照税务机关或审批机关的税收处理决定提取纳税人的存款帐户上的资金来缴纳税款、罚金上交国家财政。\n（2）扣留物品，保证足额征收税款、罚金。\n（3）依法登记财产，保证足额征收欠税、罚金。"}},{"id":"VN-H076-A20","no":20,"noLabel":{"zh":"第20条"},"chapter":{"zh":"第四章"},"text":{"zh":"【税务机关在税收违法行为的处理中的权力】\n1、直接管理税收的税务机关的首长有权处理本法第十九条第一款、第二款和第三款规定的纳税人的违法行为；\n2、对于本法第十九条第三款规定的违法行为，直接管理税收的税务机关局长、分局长，可采取本法第十九条第四款规定的措施并将档案转送审批机关以依法处理。"}},{"id":"VN-H076-A21","no":21,"noLabel":{"zh":"第21条"},"chapter":{"zh":"第四章"},"text":{"zh":"【对税务干部和其它个人的违法行为的处理】\n1、税务干部、其它个人利用职务、权力非法使用、占有税款、 罚金的，应将非法使用、占有的全部税款、罚金交还，并视违法行为的性质、程度予以纪律处分或者依法追究刑事责任。\n2、税务干部、其它个人由于缺少责任感或作错误办理，给纳税人造成损失的，应依法赔偿损失，并视违法行为的性质、程度予以纪律处分或者依法追究刑事责任。\n3、税务干部、其它个人利用职务、权力串通、包庇违反《增值税法》或有其它违反本法规定的行为的人，并视违法行为的性质、程度予以纪律处分或者依法追究刑事责任。\n4、妨碍或唆使他人妨碍《增值税法》实施的人，并视违法行为的性质、程度予以行政处分或者依法追究刑事责任。"}},{"id":"VN-H076-A22","no":22,"noLabel":{"zh":"第22条"},"chapter":{"zh":"第五章"},"text":{"zh":"【嘉奖】 出色完成交给的任务的税务机关、税务干部；《增值税法》执行过程中取得成绩的组织、个人；很好旅行纳税义务的纳税人，给予嘉奖。\n政府具体规定嘉奖办法。\n第五章 起诉和时效"}},{"id":"VN-H076-A23","no":23,"noLabel":{"zh":"第23条"},"chapter":{"zh":"第五章"},"text":{"zh":"【税收起诉中纳税人的权力和责任】\n1、纳税人有权起诉税务干部、税务机关执法不符《增值税法》 的情况。\n起诉书在三十日内送达直接管理税收的税务机关，从收到税务干部或税务机关的通知或处理决定之日起。\n在等待解决的过程中，纳税人仍应按照税务机关的通知或处理决定执行。\n2、对于起诉人不同意起诉受理机关的决定或者超过本法"}},{"id":"VN-H076-A24","no":24,"noLabel":{"zh":"第24条"},"chapter":{"zh":"第六章"},"text":{"zh":"规定的期限而仍未解决，则有权上诉直接上级税务机关或者依法向法院上诉。\n第二十四条【税务机关在受理税收起诉中的责任和权力】\n1、税务机关在收到税收起诉时应在十五日内审查解决，从接到起诉书日起；对于复杂的案件期限可适当延长，但最长不得超过三十日；如果案件不在自已的权限之内的，应在十日内转送档案或者报告有权限的机关受理，并通知起诉人，从接到起诉之日起。\n2、起诉受理机关有权要求起诉人向起诉提供档案、材料；如果起诉人拒绝提供档案、材料的，有权拒绝审查受理起诉。\n3、税务机关应在十日内返还不合理的税款、罚金给纳税人，从收到上级机关或者依法具有审批权的机关的决定之日起。\n4、如果发现并确认存在欺诈、逃税行为，税务机关有责任追缴五年前以来的税款、罚金或返还税款，从检查发现存在欺诈、逃税行为或税收存在差错之日起；经营单位不登记申报、纳税的， 追缴税款、罚金的期限从经营单位开始业务之日起。\n5、上级税务机关首长有责任解决纳税人对下级税务机关的税收起诉。\n财政部长关于税收起诉的裁决是终审裁决。\n第六章 组织执行"}},{"id":"VN-H076-A25","no":25,"noLabel":{"zh":"第25条"},"chapter":{"zh":"第六章"},"text":{"zh":"政府指导全国范围内《增值税法》的组织执行。"}},{"id":"VN-H076-A26","no":26,"noLabel":{"zh":"第26条"},"chapter":{"zh":"第六章"},"text":{"zh":"财政部长负责组织执行和检查全国范围内《增值税法》的执行情况。"}},{"id":"VN-H076-A27","no":27,"noLabel":{"zh":"第27条"},"chapter":{"zh":"第七章"},"text":{"zh":"各级人民委员会，在自已的任务、权限范围内指导地方上《增值税法》执行情况的实现和检查。\n第七章 实施"}},{"id":"VN-H076-A28","no":28,"noLabel":{"zh":"第28条"},"chapter":{"zh":"第七章"},"text":{"zh":"《增值税法》自1999年 1月 1日起实施生效。\n废除《营业收入税法》，《〈营业收入税法〉和其它法律文本中有关营业收入税的规定的部分条款的修订法》，从《增值税法》实施生效之日起。\n1999 年 1 月 1 日之前有关税收、决算税、免减税存在的问题的解决和有关营业税违法行为的处理按照《营业收入税法》，《〈营业收入税法〉和其它法律文本中有关营业收入税的规定的部分条款的修订法》的相应规定执行。\n对于《增值税法》使用的开始几年中生产、建设、运输单位由于应纳税额多于按之前的《营业收入税》核算的税款而遭受亏损的， 减少应纳增值税额。增值税的减少量与由此原因造成的损失相对应，但最多不超过50%应纳税额。减少时间逐年审查，并按公历年决算，但最多不超过三年，从《增值税法》实施生效之日起。\n政府按照本条具体规定增值税审查减少事项。"}},{"id":"VN-H076-A29","no":29,"noLabel":{"zh":"第29条"},"chapter":{"zh":"第七章"},"text":{"zh":"对于越南缔结或者参加的国际条约对进出口税有与本法不同规定的，则增值税适用国际条约。"}},{"id":"VN-H076-A30","no":30,"noLabel":{"zh":"第30条"},"chapter":{"zh":"第七章"},"text":{"zh":"政府规定本法的实施细则。\n本法已于1997年5月10日越南社会主义共和国第九届国会第十一次会议通过。\n国会主席 农德孟"}}],"pack":"vn-p03","rebuiltFrom":"原为单条全文，2026-10-24 按条号标记重新切分（拼接无损校验通过）"};
  FT["VN-H077"] = {"id":"VN-H077","coverage":"full","language":"zh","sourceName":"越南官方发布渠道","sourceUrl":"","fetchedAt":"2026-10-04","articleCount":41,"structureMode":"ARTICLE","title":{"zh":"海警法","en":"Law on the Vietnam Coast Guard","orig":null},"level":"law","status":"active","docNumber":"年份不详","issuingBody":"越南官方发布渠道","completenessNote":"文本未能可靠切分为条文（或原件为目录式排版），按整篇收录，未作改写。","country":"VN","countryName":"越南","layer":"intl","articles":[{"id":"VN-H077-A1","no":1,"noLabel":{"zh":"第1条"},"chapter":{"zh":"第二章"},"text":{"zh":"·97· 越南社会主义共和国海警法 a 第一章  总   则\n调整范围本法规定了越南海警的地位、 职能、 任务、 权限、 组织和活动原则； 对于越南海警的制度、 政策； 相关机关、 组织、 个人的责任。"}},{"id":"VN-H077-A2","no":2,"noLabel":{"zh":"第2条"},"chapter":{"zh":"第二章"},"text":{"zh":"词语解释在本法中， 词语理解如下：\n（一） 在越南海域保卫国家的主权、 主权权利、 裁判权是对于机关、 组织或个人违反关于越南社会主义共和国主权、 主权权利、 裁判权相关法律法规行为的防范、 发现、 处理行动。\n（二） 越南海警的干部、 战士包括士官、 专业军人、 下士、 兵士、 工人、 越南海警在编人员。"}},{"id":"VN-H077-A3","no":3,"noLabel":{"zh":"第3条"},"chapter":{"zh":"第二章"},"text":{"zh":"越南海警的地位、 职能\n（一） 越南海警是人民武装力量， 是国家的专职力量， 是作为执法保卫国家海上安宁、 秩序和安全的骨干力量。\n（二） 越南海警有责任为国防部长根据职权颁行或党和国家制定关于保护国家海上安全、 秩序、 安宁的相关政策、 法律作出参谋； 保卫越南海域的国家主权、 主权权利、 裁判权； 根据职权要求进行安宁、 秩序和安全管理， 保证越南法律、 越南社会主义共和国参与的国际条约、 国际协议的执行。"}},{"id":"VN-H077-A4","no":4,"noLabel":{"zh":"第4条"},"chapter":{"zh":"第二章"},"text":{"zh":"越南海警的组织和活动原则\n（一） 绝对、 直接服从越南共产党的领导， 国家主席的总领， 政府的统一管理， 国防部长的直接指导、 指挥。\n（二） 遵守越南宪法和法律及越南社会主义共和国参与的国际条约。\n（三） 根据自越南海警司令部到基层单位的集中、 统一管理。\n* 本文译者： 王佳微， 系国家海洋信息中心研究实习员。\n* “一带一路”法律查明     第 1 卷 ·98·\n（四） 主动防御、 发现、 斗争和处理违法行为。\n（五） 结合保卫国家主权、 主权权利、 裁判权的任务， 在发展海洋经济的同时对海上安宁、 秩序和安全进行管理。\n（六） 依靠人民， 发挥人民力量， 接受人民监督。"}},{"id":"VN-H077-A5","no":5,"noLabel":{"zh":"第5条"},"chapter":{"zh":"第二章"},"text":{"zh":"建设越南海警\n（一） 国家要建设革命化、 正规化、 精锐化、 现代化的越南海警， 为越南海警发展提供优先资源。\n（二） 越南的机关、 组织和工人有责任参加建设清白、 牢靠的越南海警。"}},{"id":"VN-H077-A6","no":6,"noLabel":{"zh":"第6条"},"chapter":{"zh":"第二章"},"text":{"zh":"机关、 组织、 个人参与、 配合、 帮助越南海警工作的责任、 制度和政策\n（一） 机关、 组织、 个人在越南海域活动时， 有责任参加、 配合、 帮助越南海警的工作使其履行其职能、 任务、 权限。\n（二） 越南机关、 组织、 公民有责任配合越南海警完成由实权部门颁布的民间人力、 船只、 工具、 技术设备调用决定以保卫越南海域的国家主权、 主权权利、 裁判权。\n（三） 机关、 组织和个人在参加、 配合、 帮助海警工作国家根据其要求为其保守秘密；\n有成绩的给予表扬， 财产损失的给予补偿， 名誉损害的帮其恢复， 受伤或生命、 健康受到损害的则其亲人或家庭享受法律规定的制度、 政策。"}},{"id":"VN-H077-A7","no":7,"noLabel":{"zh":"第7条"},"chapter":{"zh":"第二章"},"text":{"zh":"严厉禁止的行为\n（一） 抵触、 阻碍越南海警活动； 在越南海警执行公务或因公务理由时对其进行报复、 恐吓、 侵犯其生命健康、 人格、 名誉。\n（二） 收买、 贿赂、 要挟越南海警的干部和战士使其违反职责、 任务、 权限。\n（三） 冒充越南海警的干部、 战士， 假冒越南海警的船只、 设施； 做假、 买卖、 非法使用越南海警的服装、 印章、 公文。\n（四） 利用、 滥用越南海警干部、 战士的工作职务、 权限、 地位违反法律； 侵犯机关、 组织、 个人的合法权利和利益。\n（五） 越南海警干部、 战士对机构、 组织、 个人在越南海域合法活动进行敲诈勒索或者使其合法活动产生困难。\n（六） 违反本法规定的其他行为。\n第二章  越南海警的任务、 权限"}},{"id":"VN-H077-A8","no":8,"noLabel":{"zh":"第8条"},"chapter":{"zh":"第二章"},"text":{"zh":"越南海警的任务\n（一） 收集、 分析、 评价、 预报情况， 提出保卫国家安全的主张、 解决办法、 方案， 执行 ·99· 海上法律； 为各级职权部门颁行关于保卫越南海域国家主权、 主权权利、 裁判权， 保证海上秩序、 安全， 防范打击海上犯罪、 违法活动的政策、 法律开展研究、 分析、 预报、 参谋。\n（二） 保卫国家主权、 主权权利、 裁判权， 保卫国家和民族安全、 利益， 保护海洋资源、 环境， 保护机构、 组织、 个人在海上的合法财产、 权利、 利益。\n（三） 防范、 打击海上犯罪和违法行为， 保护海上安宁、 秩序和安全， 进行海上搜救、 救难， 参与处理海上环境事故。\n（四） 参与国防、 安全体系建设， 处理海上国防、 安全状况。\n（五） 进行法律宣传、 普及、 教育。\n（六） 接受、 使用被调用参与保卫越南海域内主权、 主权权利、 裁判权的民间人力、 船只、 工具、 技术设备。\n（七） 在与越南海警职能、 任务、 权限相关的国际协议和越南社会主义共和国签署的国际条约的基础上开展国际合作。"}},{"id":"VN-H077-A9","no":9,"noLabel":{"zh":"第9条"},"chapter":{"zh":"第二章"},"text":{"zh":"越南海警的权限\n（一） 根据本法和其他相关法律规定对越南海域内的人员、 船只、 货物、 行李进行巡查、 检查、 搜查。\n（二） 根据本法第14 条规定使用工作任务中所需要的武器、 爆炸物、 辅助工具。\n（三） 根据本法第15 条和其他相关法律规定使用设施、 专业技术设备。\n（四） 根据处理行政违法相关法律处理行政违法案件。\n（五） 根据组织机关调查刑事案件相关法律和刑事诉讼相关法律， 开展部分刑事调查活动。\n（六） 追捕海上违法船只。\n（七） 在紧急情况下调用属于越南机关、 组织、 公民的人员、 船只、 工具、 技术设备。\n（八） 在紧急情况下提议国外组织、 个人在越南海域内开展救助、 帮助活动。\n（九） 依法扣留海上违法船只。\n（十） 根据本法第12 条之规定开展工作。"}},{"id":"VN-H077-A10","no":10,"noLabel":{"zh":"第10条"},"chapter":{"zh":"第三章"},"text":{"zh":"越南海警干部、 战士的义务和责任\n（一） 对祖国、 人民、 党和国家绝对忠诚； 严格执行党的方针、 路线， 国家政策、 法律， 上级命令、 指示。\n（二） 坚决维护越南海域国家主权、 主权权利、 裁判权； 防范、 打击海上犯罪、 违法行为， 保证社会安宁、 秩序和安全， 保护越南海域的和平、 稳定和发展。\n（三） 严守国家秘密、 工作秘密， 严格执行海警工作办法。\n“一带一路”法律查明     第 1 卷 ·100·\n（四） 遵守越南签署的各项国际条约和与越南海警职能、 任务、 权限相关的国际协议。\n（五） 加强学习， 提高政治本领、 法律意识、 专业水平、 业务能力、 组织纪律意识， 开展体能训练。\n（六） 在执行任务时对法律和上级决定负责。\n第三章  越南海警的活动第一部分  越南海警的活动范围和工作办法"}},{"id":"VN-H077-A11","no":11,"noLabel":{"zh":"第11条"},"chapter":{"zh":"第三章"},"text":{"zh":"活动范围\n（一） 越南海警在越南海域活动履行本法规定的职能、 任务、 权限。\n（二） 因人道、 和平目的， 防范、 打击犯罪和违法活动时， 越南海警可以在越南海域外开展活动， 在开展活动时要遵守越南法律、 越南签署的各项国际条约和与越南海警职能、 任务、 权限相关的国际协议的规定。"}},{"id":"VN-H077-A12","no":12,"noLabel":{"zh":"第12条"},"chapter":{"zh":"第二部"},"text":{"zh":"越南海警工作办法\n（一） 越南海警在开展工作时运用群众运动办法、 法律办法、 外交办法、 经济办法、 科学技术办法、 业务办法、 武装办法。\n（二） 越南海警司令根据本条第 1 款规定决定海警使用的办法， 并为自己的决定对法律和上级负责。\n第二部分  越南海警海上执法"}},{"id":"VN-H077-A13","no":13,"noLabel":{"zh":"第13条"},"chapter":{"zh":"第二部"},"text":{"zh":"巡查、 检查、 搜查\n（一） 越南海警开展对于人、 船只、 货物、 行李的巡查、 检查、 搜查活动， 发现、 杜绝、 处理海上违法行为。\n（二） 需要船只停靠进行检查、 搜查的情形包括：\n1. 直接发现有违法行为或有违法征兆的；\n2. 通过专业工具、 技术设备发现、 确认有违法行为或有违法征兆的；\n3. 举报、 线报有犯罪、 违法行为的；\n4. 实权部门对违法人员、 船只、 工具有紧追、 羁押请求的；\n5. 违法人员自觉交代违法行为的。\n（三） 在进行巡查、 检查、 搜查时， 越南海警的船只、 飞机和其他工具须展示颜色； 根据本法第 29 条 、第31 条规定展示旗号、 徽章、 标志、 服装。\n（四） 在越南海域内的机关、 组织、 个人有义务接受越南海警的检查、 搜查。\n·101·\n（五） 国防部部长规定越南海警的巡查、 检查、 搜查程序。"}},{"id":"VN-H077-A14","no":14,"noLabel":{"zh":"第14条"},"chapter":{"zh":"第二部"},"text":{"zh":"使用武器、 爆炸物、 辅助工具\n（一） 在执行任务时， 越南海警的干部、 战士， 可根据 《管理、 使用武器、 爆炸物和辅助工具法》 之规定使用武器、 爆炸物和辅助工具并开火。\n（二） 除根据 《管理、 使用武器、 爆炸物和辅助工具法》 之规定开火外， 在执行防范打击犯罪、 保证海上安宁、 秩序和安全任务时， 在下列情形之一， 越南海警的干部、 战士可以向除外交机构代表船只、 外国领事机构船只、 国际组织代表机构船只、 载有乘客的船只或者已经停下的载有人质的船只外的船只开火：\n1. 已经控制的船只进攻或者直接威胁到执行公务人员或他人生命的；\n2. 已明确由犯罪对象控制的船只有逃跑倾向的；\n3. 已明确船上载有犯罪对象或者载有非法武器、 爆炸物、 反动材料、 国家秘密、 毒品、 国宝且有逃跑倾向的；\n4. 已明确知晓船上的对象具有在越南社会主义共和国参加的国际条约中规定和 《刑法》 中规定的海盗行为、 武装劫船行为且有逃跑倾向的。\n（三） 本条第 2 款规定的开枪场合中， 越南海警的干部、 战士在向船只开火前要通过行动、 命令、 言语或朝天开枪的方式进行警告； 在执行有组织任务时需遵守实权者的命令。"}},{"id":"VN-H077-A15","no":15,"noLabel":{"zh":"第15条"},"chapter":{"zh":"第二部"},"text":{"zh":"使用设施、 专业技术设备\n（一） 越南海警在收集、 分析、 评价、 预报情况保卫国家主权、 主权权利、 裁判权， 保护国家、 民族海上安全、 利益时； 发现、 逮捕、 调查、 处理犯罪、 违法行为时根据保护国家安全相关法律、 处理行政违法相关法律和刑事诉讼相关法律使用设施、 专业技术设备、 搜集结果。\n（二） 越南海警的设施、 专业技术设备在使用之前需进行鉴定、 校准、 试验使其符合法律规定程序和安全保证。\n（三） 政府规定越南海警使用设施、 专业技术设备的管理、 使用和名目。"}},{"id":"VN-H077-A16","no":16,"noLabel":{"zh":"第16条"},"chapter":{"zh":"第二部"},"text":{"zh":"调用民间人员、 船只、 工具、 技术设备\n（一） 在人员、 船只、 工具违法需要紧急逮捕时， 搜救时， 应对、 克服严重环境事故的情况时， 海警的干部、 战士可调用越南机关、 组织、 公民的人员、 船只、 工具、 技术设备。\n（二） 本条第1 款规定的调用工作要保证符合被调用民间人员、 船只、 工具、 技术设备的实际能力且在紧急情况结束时需立即归还。\n被调用参加工作的人员、 财产受到伤害， 则根据本法第6 条第 3 款规定享受的制度、 “一带一路”法律查明     第 1 卷 ·102· 政策、 补偿。实施调用的干部、 战士所属机构有责任根据法律规定进行补偿。\n（三） 越南的机关、 组织、 公民有责任完成越南海警的调用工作。\n（四） 在发生人员、 船只、 工具违法需要紧急逮捕时， 开展搜救时， 应对、 克服严重环境事故时， 越南海警干部、 战士可提议在越南海域活动的外国组织、 个人参与帮助、 救援。"}},{"id":"VN-H077-A17","no":17,"noLabel":{"zh":"第17条"},"chapter":{"zh":"第二部"},"text":{"zh":"实施对海上船只的紧追权\n（一） 越南海警在下列情况下实施对海上船只的紧追权：\n1. 在海上违反越南国家主权、 主权权利、 裁判权的；\n2. 不执行本法第 13 条第 3 款规定的海警停船信号、 号令的；\n3. 开展国际追捕合作的；\n4. 法律规定的其他情形。\n（二） 越南海警实施对海上船只紧追权的范围、 权力、 程序根据越南法律和越南社会主义共和国参与的国际条约的规定执行。"}},{"id":"VN-H077-A18","no":18,"noLabel":{"zh":"第18条"},"chapter":{"zh":"第三部"},"text":{"zh":"公布、 通报、 更改航行安全指数越南海警司令部负责公布或更改航行安全指数并向职权部门通报， 接收、 处理航行安全信息， 向在越南海域活动的船只通报符合应用需要的安全航行办法。\n第三部分  越南海警的国际合作"}},{"id":"VN-H077-A19","no":19,"noLabel":{"zh":"第19条"},"chapter":{"zh":"第三部"},"text":{"zh":"越南海警的国际合作原则\n（一） 在遵守越南法律、 越南社会主义共和国参与的国际条约、 职权相关的国际协议的基础上开展国际合作， 尊重国际法的基本原则， 保证国家的独立、 主权、 主权权利、 裁判权， 保卫国家、 民族利益及组织、 个人在海上活动的合法权利和利益。\n（二） 发挥自身力量和国际社会的支持、 帮助， 保证海上法律的执行。"}},{"id":"VN-H077-A20","no":20,"noLabel":{"zh":"第20条"},"chapter":{"zh":"第三部"},"text":{"zh":"国际合作内容\n（一） 防范、 打击海盗、 武装劫船。\n（二） 在越南海警任务、 权限范围内防范打击毒品犯罪、 拐卖人口、 非法武器买卖、 恐怖活动、 非法出入境活动、 非法跨境交易、 非法货物运输、 非法开采海产和其他海上违法活动。\n（三） 在越南海警职能、 任务、 权限范围内， 防范污染， 预防、 应对、 处理海上环境事故， 检查保护海洋资源， 保护海洋生物多样性和海洋生态系统， 对自然灾害作出防御、 警报， 开展人道主义援助， 灾难应对， 海上搜救、 救难。\n（四） 开展培训、 培养、 专业训练， 进行经验交流， 转交装备、 科学技术， 提高越南海警 ·103· 能力。\n（五） 越南法律、 越南社会主义共和国参与的国际条约、 与越南海警职能、 任务、 权限相关的国际协议中规定的其他国际合作内容。"}},{"id":"VN-H077-A21","no":21,"noLabel":{"zh":"第21条"},"chapter":{"zh":"第四章"},"text":{"zh":"国际合作形式\n（一） 交流与海上安宁、 秩序和安全相关的信息。\n（二） 组织或参加关于海上安宁、 秩序、 安全和法律执行的国际会议、 研讨会。\n（三） 根据法律规定， 与其他国家职能部门、 国际组织一起参加国际协议的签订。\n（四） 配合巡查、 检查、 搜查以保证海上安宁、 秩序、 安全和法律的实施。\n（五） 参加演习、 训练， 依照世界和地区内各国海上法律开展礼节性接待、 访问。\n（六） 与越南法律、 越南社会主义共和国参与的国际条约和国际协议中规定的和越南社会主义共和国有联系的常设机构、 关键部门开展工作。\n（七） 越南法律、 越南社会主义共和国参与的国际条约、 国际协议中规定的其他国际合作形式。\n第四章  越南海警与职能机关、 组织、 部队联合开展活动"}},{"id":"VN-H077-A22","no":22,"noLabel":{"zh":"第22条"},"chapter":{"zh":"第四章"},"text":{"zh":"配合范围\n（一） 根据本法规定和相关法律的其他规定， 越南海警牵头， 并与部属机关、 组织、 部队及其他部级机关和省级人民委员会联合履行越南海警的任务和权限。\n（二） 越南海警和国防部所属机构的联合工作由国防部部长规定。"}},{"id":"VN-H077-A23","no":23,"noLabel":{"zh":"第23条"},"chapter":{"zh":"第四章"},"text":{"zh":"配合原则\n（一） 配合工作要在部属机关、 组织、 部队， 部级机关和省级人民委员会职能基础上开展； 禁止妨碍机关、 组织、 个人在海上的合法活动。\n（二） 越南海警和部属机关、 组织、 部队， 部级机关和省级人民委员会相互协调， 及时完成任务， 互相协助履行法律规定的职能、 任务和权限。\n（三） 确保集中统一的主持、 调度， 在配合过程中对机关、 组织、 部队的国防、 安全、 业务方法相关信息进行保密。\n（四） 确保配合方式灵活、 具体、 有效， 与主持、 配合机关的领导责任人紧密联系。\n（五） 在同一海域上， 当发现与多个机关、 组织、 部队职能、 任务、 权限相关的违法行为时， 则先发现的机关、 组织、 部队根据法律规定的职权进行处理。不属于自己职权范围内的场合、 事项， 则将违法档案、 人员、 赃物、 船只、 工具转交有实权主持解决的机关、 组织、 部队； 接受的机关、 组织、 部队有责任向交予方通报调查、 处理结果。\n“一带一路”法律查明     第 1 卷 ·104·"}},{"id":"VN-H077-A24","no":24,"noLabel":{"zh":"第24条"},"chapter":{"zh":"第四章"},"text":{"zh":"配合内容\n（一） 信息、 材料交流， 研究、 制定法律规范文本。\n（二） 保卫海上国家安全、 主权、 主权权利和裁判权。\n（三） 保护海洋环境和资源， 海上国家、 组织、 个人财产， 海上合法活动个人的生命、 健康、 名誉、 人格。\n（四） 开展海上巡查、 检查、 搜查保护海上安宁、 秩序、 安全； 防止、 发现、 制止、 打击违法行为， 打击、 防御海盗和武装劫船。\n（五） 防范自然灾害， 开展搜救、 救难， 克服、 应对海上环境事故。\n（六） 培训、 训练、 培养越南海警干部、 战士， 向人民开展法律宣传、 推广、 教育。\n（七） 开展国际合作。\n（八） 开展其他相关活动的配合。"}},{"id":"VN-H077-A25","no":25,"noLabel":{"zh":"第25条"},"chapter":{"zh":"第五章"},"text":{"zh":"部级机关部长、 副部长、 省级人民委员会主席在配合越南海警时的责任部级机关部长、 副部长、 省级人民委员会主席在自己任务、 权限范围内， 有责任根据政府规定， 配合国防部部长开展与越南海警相关活动。\n第五章  越南海警的组织"}},{"id":"VN-H077-A26","no":26,"noLabel":{"zh":"第26条"},"chapter":{"zh":"第五章"},"text":{"zh":"越南海警的组织体系\n（一） 越南海警的组织体系包括：\n1. 越南海警司令部；\n2. 区域海警司令部和越南海警司令部直属单位；\n3. 基层单位。\n（二） 政府规定本条第1 款细节。"}},{"id":"VN-H077-A27","no":27,"noLabel":{"zh":"第27条"},"chapter":{"zh":"第五章"},"text":{"zh":"越南海警传统日每年的 8 月 28 日是越南海警传统日。"}},{"id":"VN-H077-A28","no":28,"noLabel":{"zh":"第28条"},"chapter":{"zh":"第五章"},"text":{"zh":"国际译名越南海警的国际译名是 Vietnam Coast Guard。"}},{"id":"VN-H077-A29","no":29,"noLabel":{"zh":"第29条"},"chapter":{"zh":"第五章"},"text":{"zh":"越南海警的颜色、 旗帜、 徽章和识别标志\n（一） 越南海警的船只、 飞机和其他工具有其自身独特的颜色、 旗帜、 徽章和识别标志。当执行任务时， 船只必须悬挂国旗和越南海警旗号。\n（二） 政府规定本条第1 款细节。\n·105·"}},{"id":"VN-H077-A30","no":30,"noLabel":{"zh":"第30条"},"chapter":{"zh":"第五章"},"text":{"zh":"越南海警的印章在履行职能、 任务权限时， 越南海警使用有国徽图案的印章。"}},{"id":"VN-H077-A31","no":31,"noLabel":{"zh":"第31条"},"chapter":{"zh":"第六章"},"text":{"zh":"越南海警的服饰政府规定越南海警的警号、 军衔、 军衔、 徽章、 警服、 礼服。\n第六章  越南海警政策、 制度和活动保障"}},{"id":"VN-H077-A32","no":32,"noLabel":{"zh":"第32条"},"chapter":{"zh":"第六章"},"text":{"zh":"越南海警的经费和物质保障基础\n（一） 国家为越南海警的活动提供资金和物质基础、 土地、 办事处、 项目支持。\n（二） 国家优先为越南海警投资现代装备， 应用先进的研究、 科学成果。"}},{"id":"VN-H077-A33","no":33,"noLabel":{"zh":"第33条"},"chapter":{"zh":"第六章"},"text":{"zh":"越南海警的装备\n（一） 越南海警持有船只、 飞机和其他工具， 各类武器、 爆炸物、 辅助工具和专业技术设备来履行职能和任务。\n（二） 国防部部长规定本条第1 款细节。"}},{"id":"VN-H077-A34","no":34,"noLabel":{"zh":"第34条"},"chapter":{"zh":"第六章"},"text":{"zh":"越南海警干部、 战士的等级、 军衔、 职务、 服务制度、 政策制度和权利\n（一） 根据 《越南人民军军官法》 《专业军人法》 《国防工作人员法》 《军事义务法》 和其他有关法律规定， 实施对越南海警干部、 战士的职务任免， 升职， 降职， 剥夺职级、 军衔， 工资增减， 教育、 培训， 录用， 服务、 退伍等制度、 政策和其他规定的权利。\n（二） 越南海警干部、 战士在军队服役时， 有权享受适合其任务性质、 特殊工作以及政府规定的优惠政策。"}},{"id":"VN-H077-A35","no":35,"noLabel":{"zh":"第35条"},"chapter":{"zh":"第六章"},"text":{"zh":"越南海警选拔条件、 标准\n（一） 满18 周岁， 男女不限， 政治品质良好， 讲道德， 身体健康， 意愿鲜明并自愿长期服务于越南海警的越南公民。\n（二） 具有专业技术的证书文凭， 具有与越南海警的任务要求相符的技能。\n（三） 国防部具体规定本条细节。"}},{"id":"VN-H077-A36","no":36,"noLabel":{"zh":"第36条"},"chapter":{"zh":"第七章"},"text":{"zh":"越南海警干部、 战士教育、 培训越南海警的干部、 战士可参与政治、 专业、 法律、 外语和其他与其任务和权限相关的必要知识教育和培训， 鼓励发展长期服务越南海警的才能。\n第七章  对越南海警的国家管理和部、 部级机关、 地方政府责任"}},{"id":"VN-H077-A37","no":37,"noLabel":{"zh":"第37条"},"chapter":{"zh":"第七章"},"text":{"zh":"国家对越南海警的管理内容\n（一） 在权限范围内颁布、 提交文件和组织实施越南海警相关法律文件。\n“一带一路”法律查明     第 1 卷 ·106·\n（二） 组织、 指导越南海警活动。\n（三） 教育、 培训越南海警干部、 战士。\n（四） 落实越南海警的政策制度。\n（五） 检查、 监察、 解决越南海警活动中的投诉、 指控、 小结、 总结、 奖励和违法行为。\n（六） 开展法律宣传、 推广、 教育。\n（七） 越南海警的国际合作。"}},{"id":"VN-H077-A38","no":38,"noLabel":{"zh":"第38条"},"chapter":{"zh":"第七章"},"text":{"zh":"国家对于越南海警的管理责任\n（一） 政府对越南海警进行统一的国家管理。\n（二） 国防部对政府开展的越南海警国家管理工作负责。\n（三） 同级部门部长和负责人在其职责范围内有义务配合国防部开展对越南海警的国家管理工作。"}},{"id":"VN-H077-A39","no":39,"noLabel":{"zh":"第39条"},"chapter":{"zh":"第七章"},"text":{"zh":"各级人民委员会和政府的责任各级人民委员会和政府在其职责和权限范围内， 为越南海警利用地方土地资金建设驻地、 船只泊位、 仓库、 码头创造条件； 开展越南海警相关法律的宣传、 普及、 教育工作；\n根据法律规定为越南海警的干部、 战士实施社会住宅政策。"}},{"id":"VN-H077-A40","no":40,"noLabel":{"zh":"第40条"},"chapter":{"zh":"第八章"},"text":{"zh":"越南祖国阵线及其成员组织的责任越南祖国阵线及其成员组织在各自的任务和权限范围内， 有责任配合有关机构和组织宣传和动员人民实施越南海警相关法律； 根据法律规定对越南海警进行监督。\n第八章  实施条款"}},{"id":"VN-H077-A41","no":41,"noLabel":{"zh":"第41条"},"chapter":{"zh":"第八章"},"text":{"zh":"实施效力 《越南海警法》 自2019 年 7 月 1 日起生效。\n2008 年 1 月 26 日颁布的第 03/2008/PL-UBTVQH12 号 《越南海警力量法令》 自本法生效之日起失效。\n本法已于越南社会主义共和国第十四届国会第六次会议通过。"}}],"pack":"vn-p03","rebuiltFrom":"原为单条全文，2026-10-24 按条号标记重新切分（拼接无损校验通过）"};
})(typeof window !== 'undefined' ? window : globalThis);
